export const DVAR_TORAH_EXCERPTS = Object.freeze({"bereshit":[{"workId":"Kli_Yakar_on_Genesis","unitId":"Kli_Yakar_on_Genesis.1.1","commentator":"כלי יקר","sourceLine":"כלי יקר · Vocalized Edition · נחלת הכלל · ספריא","chapter":1,"verse":1,"dh":"בְּרֵאשִׁית בָּרָא אֱלֹהִים אֵת הַשָּׁמַיִם וְאֵת הָאָרֶץ.","text":"מַה שֶּׁהִתְחִיל הַתּוֹרָה בְּבֵי״ת, לְפִי שֶׁבְּכָל סֵפֶר קֹהֶלֶת מְדַמֶּה שְׁלֹמֹה הַמֶּלֶךְ הַתּוֹרָה לַשֶּׁמֶשׁ, שֶׁאֵין מַהֲלָכָהּ כִּי אִם בְּשָׁלֹשׁ רוּחוֹת, כְּצוּרַת הַבֵּי״ת הַפְּתוּחָה לַצָּפוֹן, וּנְתִינָתָהּ עַל יְדֵי מֹשֶׁה שֶׁפָּנָיו כַּחַמָּה.","complete":false},{"workId":"Or_HaChaim_on_Genesis","unitId":"Or_HaChaim_on_Genesis.2.18","commentator":"אור החיים","sourceLine":"אור החיים · Vocalized Edition · נחלת הכלל · ספריא","chapter":2,"verse":4,"dh":"וְנִרְאֶה","text":"כִּי לֶהֱיוֹת שֶׁקָּדַם וְהוֹדִיעַ הַכָּתוּב כִּי אָמַר ה׳ לַנִּבְרָאִים שֶׁיַּעֲשׂוּ גַּם הֵם תּוֹלָדוֹת, לַשָּׁמַיִם לַחְלוֹק הַמַּיִם וְהַרְבֵּה פְּרָטִים כָּאָמוּר בְּדִבְרֵיהֶם, וְלָאָרֶץ אָמַר גַּם כֵּן לְהוֹצִיא חַיּוֹת וּלְהוֹצִיא עֲצֵי פֵּרוֹת וַעֲשָׂבִים, וְלַמַּיִם אָמַר ״יִשְׁרְצוּ הַמַּיִם״ וְגוֹ׳, כְּדֵי שֶׁלֹּא יִטְעֶה אָדָם וְיַחְשׁוֹב כִּי הָאָרֶץ וְהַשָּׁמַיִם מֵעַצְמָן עָשׂוּ הַפְּעֻלָּה וְתוֹלִיד הַמַּחְשָׁבָה הַלֵּזוּ תּוֹלָדוֹת מְשֻׁבָּשׁוֹת. לָזֶה בָּא הַכָּתוּב וְאָמַר אֵלֶּה תוֹלְדוֹת הַשָּׁמַיִם, פֵּרוּשׁ:","complete":false},{"workId":"Haamek_Davar_on_Genesis","unitId":"Haamek_Davar_on_Genesis.2.39","commentator":"העמק דבר","sourceLine":"העמק דבר · ספר תורת אלוהים, וילנא 1879 · נחלת הכלל · ספריא","chapter":2,"verse":20,"dh":"ולאדם לא מצא עזר כנגדו.","text":"בזה שקרא שמות ראה אדם שקשה להשיג עבורו עזר. וביאור הדברים שאדם מתחלה לא הבין בעצמו אם יש לו כל חליפי המדות. שהרי מעולם לא כעס מאין ידע שיש לו מדת הכעס. וכן רחמנות וכדומה. אבל בעת אשר התבונן על כל הברואים ועמד על טבעם מזה התבונן שאצלו כל המדות שבכל מיני ברואים נכללים. דבל״ז לא היה עומד על כחותיהם דמי שאינו יודע רגז לא יאמין ולא יתבונן מה הוא רוגז. ואחר שהתבונן כי כן הוא התבונן שנצרך לו עזר שיהיה גם בה כח להיות עזר כנגדו כמו שביארנו לעיל. ואם אפי׳ יברא הקב״ה בריאה חדשה שיהא ג״כ מלוקט מכל חלקי עפר מן האדמה ויהא כלול בה ג״כ כל המדות. עדיין לא תהא עזר לאדם. אלא נקבה בפ״ע בשנויי מדות.","complete":false},{"workId":"Sforno_on_Genesis","unitId":"Sforno_on_Genesis.3.37","commentator":"ספורנו","sourceLine":"ספורנו · Vocalized Edition · נחלת הכלל · ספריא","chapter":3,"verse":22,"dh":"כְּאַחַד מִמֶּנּוּ לָדַעַת טוֹב וָרָע.","text":"הוּא יוֹדֵעַ טוֹב וָרָע עִם הֱיוֹתוֹ בְּצַלְמֵנוּ, וְאִם יִהְיֶה נִצְחִי בְּזֶה הָעִנְיָן, הִנֵּה יִרְדּוֹף כָּל הַיָּמִים אַחַר הֶעָרֵב וְיַשְׁלִיךְ אַחֲרֵי גֵוּוֹ כָּל הַשָּׂגָה שִׂכְלִית וְכָל מַעֲשֶׂה טוֹב, וְלֹא יַשִּׂיג הָאוֹשֶׁר הָרוּחָנִי הַמְכֻוָּן מֵאֵת הָאֵל יִתְבָּרַךְ בְּצַלְמוֹ וּדְמוּתוֹ:","complete":true},{"workId":"Rabbeinu_Bahya_on_Genesis","unitId":"Rabbeinu_Bahya_on_Genesis.4.26","commentator":"רבינו בחיי","sourceLine":"רבינו בחיי · Midrash Rabbeinu Bachya [ben Asher]. Warsaw, 1878 · נחלת הכלל · ספריא","chapter":4,"verse":23,"dh":"כי איש הרגתי לפצעי.","text":"הביא למך החרב והרציחה בעולם ומעשה אבות יעשו בנים כי הוא בנו של קין הרוצח הראשון. והוליד שלשה בנים, הבן הבכור למדהו ענין המרעה כפי טבעי הבהמות. הבן השני למדהו חכמת הנגון. הבן השלישי למדהו כלי המלחמה בחרבות וברמחים וללטוש נחשת. והנשים שלו היו מתפחדות ממנו שלא ימות בעונש חטאו לפי שהביא הרציחה בעולם, וע\"כ היה אומר להן כי איש הרגתי לפצעי או ילד לחבורתי שעשיתי בו כמו שעשה קין, כונתו לומר כי האדם יכול להרוג בלא חרב ואין החרב סבת הרציחה, ואע\"פ שהוא הוציא בעולם אומנותו אין עליו עונש בזה כי אפשר להמית במיתה קשה מן החרב.","complete":true}],"noach":[{"workId":"Or_HaChaim_on_Genesis","unitId":"Or_HaChaim_on_Genesis.6.14","commentator":"אור החיים","sourceLine":"אור החיים · Vocalized Edition · נחלת הכלל · ספריא","chapter":6,"verse":9,"dh":"אֵלֶּה תּוֹלְדוֹת נֹחַ.","text":"אָמְרוֹ אֵלֶּה שֶׁיּוֹרֶה עַל פִּסּוּל זוּלָתָם. יֵשׁ מָקוֹם לוֹמַר שֶׁנִּתְכַּוֵּן לִפְסוֹל דּוֹרוֹ, אֶלָּא שֶׁלֹּא הָיָה צָרִיךְ לְהוֹדִיעַ זֶה שֶׁכְּבָר נִפְסְלוּ וְנֶחְתְּמוּ לִמָּחוֹת. אָכֵן יִתְבָּאֵר עַל דֶּרֶךְ אָמְרָם זִכְרוֹנָם לִבְרָכָה (בראשית רבה ל:ו) עִקַּר תּוֹלְדוֹתֵיהֶם שֶׁל צַדִּיקִים מִצְווֹת וּמַעֲשִׂים טוֹבִים, עַד כָּאן.","complete":false},{"workId":"Ramban_on_Genesis","unitId":"Ramban_on_Genesis.7.1","commentator":"רמב״ן","sourceLine":"רמב״ן · On Your Way · נחלת הכלל · ספריא","chapter":7,"verse":1,"dh":"ויאמר ה' לנח","text":"הודיעו השם כי במדת רחמים ימלט אותו ואת ביתו ויחיה מהם זרע לדורות וזה טעם לחיות זרע על פני כל הארץ (בראשית ז׳:ג׳) כי מתחלה אמר להחיות אתך (בראשית ו׳:י״ט) ורמז לו עתה במדת רחמים על הקרבן להודיע אותו שישעה אל קרבנו ובזכות קרבנו יקיים העולם ולא יכרת עוד מפני מי המבול ועל כן מזכיר בו השם המיוחד כי בכל ענין הקרבנות לא יזכיר \"אלהים\" כאשר אזכיר (ויקרא א ט) בהגיעי לשם בעזרת השם:","complete":true},{"workId":"Haamek_Davar_on_Genesis","unitId":"Haamek_Davar_on_Genesis.7.20","commentator":"העמק דבר","sourceLine":"העמק דבר · ספר תורת אלוהים, וילנא 1879 · נחלת הכלל · ספריא","chapter":7,"verse":19,"dh":"והמים גברו מאד מאד על הארץ.","text":"הוסיפו לעקור ארץ רבה ונעשה ע״י זה הרים וגבעות מה שלא הי׳ לפני המבול. תדע שהרי לפי הנראה מפרשה זו היו הרי אררט גבוהים מכל הרים שבעולם ובאמת אינו כן אלא אותם ההרים נעשו בימי המבול. וגם שינו בעולם במעינות וכדאיתא ברבה דאע״ג שנסכרו אח״כ כל מעינות מ״מ נשתיירו כמה מעינות ששוטפים עד היום:","complete":true},{"workId":"Kli_Yakar_on_Genesis","unitId":"Kli_Yakar_on_Genesis.8.3","commentator":"כלי יקר","sourceLine":"כלי יקר · Vocalized Edition · נחלת הכלל · ספריא","chapter":8,"verse":16,"dh":"צֵא מִן הַתֵּבָה אַתָּה וְאִשְׁתֶּךָ.","text":"וּבִכְנִיסָתָם הִזְכִּיר הַזְּכָרִים לְבַד וְהַנְּקֵבוֹת לְבַד, הַיְינוּ כְּדֵי שֶׁלֹּא יִפְרוּ וְיִרְבּוּ בַּתֵּיבָה, דְּאִם לֹא כֵן יֵשׁ לָחוּשׁ שֶׁיִּרְאוּ מֵהֶם כָּל שְׁאָר הַבַּעֲלֵי חַיִּים וְיִפְרוּ וְיִרְבּוּ בַּתֵּיבָה, וְאָז לֹא תָכִיל אוֹתָם הַתֵּיבָה, כִּי לֹא נַעֲשֵׂית כִּי אִם בְּשִׁעוּר לְכָל הַנִּכְנָסִים בָּהּ. וְאִם תֹּאמַר שֶׁגַּם הַנִּכְנָסִים שָׁמָּה עָמְדוּ בְּנֵס, מִכָּל מָקוֹם לָמָּה יַעֲשֶׂה הַקָּדוֹשׁ בָּרוּךְ הוּא נֵס לְלֹא צֹרֶךְ, בִּפְרָט לְאוֹתָם שֶׁאֵין מִצְטַעֲרִים בִּזְמַן שֶׁכָּל הָעוֹלָם שָׁרוּי בְּצַעַר.","complete":true},{"workId":"Sforno_on_Genesis","unitId":"Sforno_on_Genesis.9.9","commentator":"ספורנו","sourceLine":"ספורנו · Vocalized Edition · נחלת הכלל · ספריא","chapter":9,"verse":9,"dh":"וַאֲנִי הִנְנִי מֵקִים אֶת בְּרִיתִי.","text":"עַל זֶה הַתְּנַאי שֶׁלֹּא תִּשְׁפְּכוּ דָּם נָקִי אֲנִי מֵקִים אֶת בְּרִיתִי שֶׁלֹּא לְשַׁחֵת עוֹד הָאָרֶץ, אֲבָל בִּשְׁפִיכַת דָּם נָקִי תִּשָּׁחֵת הָאָרֶץ, כְּאָמְרוֹ (במדבר לה:לג) \"כִּי הַדָּם הוּא יַחֲנִיף אֶת הָאָרֶץ וְלָאָרֶץ לֹא יְכֻפַּר וְגוֹ'\". אֲבָל עַל כָּל שְׁאָר הָעֲבֵרוֹת יִלְקֶה הַחוֹטֵא וְלֹא תִּשָּׁחֵת הָאָרֶץ.","complete":true},{"workId":"Rabbeinu_Bahya_on_Genesis","unitId":"Rabbeinu_Bahya_on_Genesis.9.19","commentator":"רבינו בחיי","sourceLine":"רבינו בחיי · Midrash Rabbeinu Bachya [ben Asher]. Warsaw, 1878 · נחלת הכלל · ספריא","chapter":9,"verse":20,"dh":"או","text":"אפשר לפרש לפי שהיה נח עשירי והעשירי קדש, כאשר נתעסק עתה בדבר היין נעשה חולין, וזה לשון ויחל. והגיד לנו הכתוב צרות רבות ורעות שהיין סבה להם, כי החטיא את הצדיק התמים אשר הציל כ העולם, וגרם לו שיהיה זרעו מקולל. והנה הפרשה הזאת אזהרה על היין כפרשת נזיר או יותר, וכן דרשו ז\"ל בסנהדרין (דף ע עא) י\"ג ווי\"ן נאמרו ביין, ויחל, וישת, וישכר, ויתגל, וירא חם, ויגד, ויקח, שם ויפת, וישימו וילכו אחורנית ויכסו, ויקץ, וידע. וכן אמר שלמה (משלי כ״ג:כ״ט) למי אוי למי אבוי למי מדינים למי שיח וגו'.","complete":false}],"lech-lecha":[{"workId":"Sforno_on_Genesis","unitId":"Sforno_on_Genesis.12.1","commentator":"ספורנו","sourceLine":"ספורנו · Vocalized Edition · נחלת הכלל · ספריא","chapter":12,"verse":1,"dh":"אֶל הָאָרֶץ אֲשֶׁר אַרְאֶךָּ.","text":"אֶל הַמָּקוֹם מֵהָאָרֶץ אֲשֶׁר אַרְאֶךָ אוֹתָהּ בְּמַרְאוֹת אֱלֹהִים, לְפִיכָךְ עָבַר בָּאָרֶץ וְלֹא נָטַע אָהֳלוֹ עַד הַמָּקוֹם שֶׁנִּרְאָה אֵלָיו שָׁם הָאֵל יִתְבָּרַךְ, כְּאָמְרוֹ וַיַּעֲבֹר אַבְרָם בָּאָרֶץ עַד מְקוֹם שְׁכֶם וַיֵּרָא אֵלָיו ה' וַיֹּאמֶר לְזַרְעֲךָ נָתַתִּי אֶת הָאָרֶץ הַזֹּאת.","complete":true},{"workId":"Ramban_on_Genesis","unitId":"Ramban_on_Genesis.12.11","commentator":"רמב״ן","sourceLine":"רמב״ן · On Your Way · נחלת הכלל · ספריא","chapter":12,"verse":15,"dh":null,"text":"וטעם ויראו אותה שרי פרעה כי כאשר ראו אותה המצרים אמרו ראויה זאת לשרים הגדולים והנה הביאוה אליהם וגם הם יראו לנפשם מנגוע בה כי מפני היופי הגדול ידעו כי המלך יחפוץ בה מאד ויהללו אותה ביניהם לומר ראויה היא למלך לשון רש\"י (רש\"י על בראשית י״ב:ט״ו) וזה דעת אונקלוס (תרגום אונקלוס על בראשית י״ב:ט״ו) שאמר ושבחו יתה לות פרעה או שהללוה אל המלך עצמו ושלח ולקחה:","complete":true},{"workId":"Haamek_Davar_on_Genesis","unitId":"Haamek_Davar_on_Genesis.13.6","commentator":"העמק דבר","sourceLine":"העמק דבר · ספר תורת אלוהים, וילנא 1879 · נחלת הכלל · ספריא","chapter":13,"verse":5,"dh":"ההלך את אברם וגו׳.","text":"דכמו אברם הגיע לזה. בשביל חכמתו דכל אדם באו לשאול לו בעצה או בתפלה או דבר חכמה כמש״כ לעיל. כך היו נדרשים ללוט באשר הוא היה אמצעי בין אברם ובין הבאים לפניו להגיד להם דעת אברם ובשביל זה העניקוהו. וגם נתחכם יותר בזה האופן. והיינו דכתיב לעיל א׳ ולוט עמו דמשמעו מקורב יותר מלשון אתו דכתיב לעיל י״ב ד׳. וכמש״כ בספר במדבר י״א י״ז וכ״ב כ׳. והוא משום שעד כה היה לוט בתורת משרת פשוט. אבל במצרים הגיע לו להיות בתורת תלמיד המקבל:","complete":true},{"workId":"Rabbeinu_Bahya_on_Genesis","unitId":"Rabbeinu_Bahya_on_Genesis.14.1","commentator":"רבינו בחיי","sourceLine":"רבינו בחיי · Midrash Rabbeinu Bachya [ben Asher]. Warsaw, 1878 · נחלת הכלל · ספריא","chapter":14,"verse":1,"dh":"ויהי בימי אמרפל מלך שנער.","text":"אמרפל זה נמרוד שאמר לאברהם לפול לתוך כבשן האש, והוא הי' המלך הראשון מעשרה מלכים שמלכו בכפה עם מלך המשיח לעתיד שהוא העשירי, ותגיד לך הפרשה שהיה אברהם אבינו גבור ואיש מלחמה, כי ארבעה מלכים עשו מלחמה עם החמשה ונצחו הארבעה, ואברהם אבינו נצח את הארבעה והתגבר עליהם.","complete":true},{"workId":"Tur_HaArokh_on_Genesis","unitId":"Tur_HaArokh_on_Genesis.14.15","commentator":"טור הארוך","sourceLine":"טור הארוך · Perush al ha-Torah, Hanover, 1838 · נחלת הכלל · ספריא","chapter":14,"verse":23,"dh":"ועד שרוך נעל.","text":"שהוא מתכשיטי הרגל כמו מראשו ועד רגליו. ופי' אם אקח כמו כה יעשה לי אלהים אם אקח. ופי' הרמ\"בן הרימותי ידי להיות הקדש וחרם לפניו אם אקח מכל אשר לך כי ההקדש תרומת יד כדכתיב כל מרים תרומת כסף. ואמר כן בשביל שנתן ממנו מעשר כי כל אשר אקח מכל אשר לך יהיה תרומה לה' ולא יהנה ממנו:","complete":true},{"workId":"Kli_Yakar_on_Genesis","unitId":"Kli_Yakar_on_Genesis.15.2","commentator":"כלי יקר","sourceLine":"כלי יקר · Vocalized Edition · נחלת הכלל · ספריא","chapter":15,"verse":8,"dh":"בַּמָּה אֵדַע כִּי אִירָשֶׁנָּה.","text":"רז״ל אָמְרוּ (נְדָרִים לב) בַּעֲבוּר שֶׁאָמַר אַבְרָם ״בַּמָּה אֵדַע״ נֶעֱנַשׁ בְּ״יָדֹעַ תֵּדַע״, וְהַשֵּׂכֶל יְמָאֵן לְקַבֵּל דְּרוּשׁ זֶה שֶׁיִּסְבְּלוּ בָּנָיו עֹנֶשׁ גָּדוֹל כָּזֶה בַּעֲבוּר הָאוֹת שֶׁשָּׁאַל אַבְרָם, וְאַבְרָם עַצְמוֹ לֹא קִבֵּל שׁוּם עֹנֶשׁ וְשִׁנֵּי בָנָיו תִּקְהֶינָה. עַל כֵּן לִבִּי אוֹמֵר וְגוֹמֵר שֶׁגָּלוּת מִצְרַיִם הָיוּ לוֹ סִבּוֹת אֲחֵרוֹת וְנֶחְלְקוּ בּוֹ רז״ל, וְתִמְצָא כָּל הַדֵּעוֹת בַּמַהֲרִי״א כִּי יָדוֹ קִבְּצָם, הֵן קָצְרָה אֹרֶךְ הַיְרִיעָה הָאַחַת מֵהַעֲלוֹת עָלֶיהָ כָּל הַדֵּעוֹת הָהֵם. אַךְ שֶׁבַּעַל מִדְרָשׁ זֶה קָשֶׁה לוֹ:","complete":false}],"vayera":[{"workId":"Haamek_Davar_on_Genesis","unitId":"Haamek_Davar_on_Genesis.18.1","commentator":"העמק דבר","sourceLine":"העמק דבר · ספר תורת אלוהים, וילנא 1879 · נחלת הכלל · ספריא","chapter":18,"verse":1,"dh":"וירא אליו ה'.","text":"בלי שום מאמר ודרשו חז\"ל כדי לבקרו. אכן אם בשביל זה לחוד מאי סיפר הכתוב שהיה כחצות היום ומאי נ\"מ בזה. אלא הי' עוד סיבה לדבר והיינו דאיתא ביומא פ\"ג צלותא דא\"א מכי משחרי כותלי. היינו מחצות היום התפלל מנחה. והנראה שלמדו זה מהאי קרא דגלוי שכינה היה מחמת שאברהם הכין עצמו לכך כדרך חסידים ששוהין שעה א' לפני התפלה לדבקה בה' ומש\"ה השיג אז גלוי שכינה. וכבר ביארו חז\"ל בברכות דכ\"ז דכחם היום היינו חצות. וע' להלן בפסוק ואברהם עודנו עומד לפני ה' ובת\"א:","complete":true},{"workId":"Ramban_on_Genesis","unitId":"Ramban_on_Genesis.18.14","commentator":"רמב״ן","sourceLine":"רמב״ן · On Your Way · נחלת הכלל · ספריא","chapter":18,"verse":15,"dh":"ותכחש שרה לאמר","text":"אני תמה בנביאה הצדקת איך תכחש באשר אמר השם לנביא וגם למה לא האמינה לדברי מלאכי אלהים והנראה בעיני כי המלאכים האלה הנראים כאנשים באו אל אברהם והוא בחכמתו הכיר בהם ובשר אותו שוב אשוב אליך ולשרה בן ושרה שומעת ולא ידעה כי מלאכי עליון הם כענין באשת מנוח (שופטים יג ו) ואולי לא ראתה אותם כלל.","complete":false},{"workId":"Or_HaChaim_on_Genesis","unitId":"Or_HaChaim_on_Genesis.19.1","commentator":"אור החיים","sourceLine":"אור החיים · Vocalized Edition · נחלת הכלל · ספריא","chapter":19,"verse":1,"dh":"וַיָּבֹאוּ וְגוֹ׳ בָּעֶרֶב.","text":"טַעַם הַדָּבָר לִמְצֹא הֲכָנָה לְלוֹט לְהַכְנִיסָם וְלִזְכּוֹת בְּהַצָּלָתוֹ, וַהֲגַם שֶׁאָמְרוּ (בראשית רבה נ:יא) כִּי בִּזְכוּת אַבְרָהָם נִצּוֹל, אֲבָל צָרִיךְ לִמְצֹא לוֹ זְכוּת כָּל שֶׁהוּא, וְאִם הָיוּ בָּאִים בַּיּוֹם אֶפְשָׁר שֶׁלֹּא הָיוּ מַנִּיחִים אוֹתוֹ בְּנֵי הָעִיר לְהַכְנִיסָם כָּל עִקָּר:","complete":true},{"workId":"Tur_HaArokh_on_Genesis","unitId":"Tur_HaArokh_on_Genesis.21.2","commentator":"טור הארוך","sourceLine":"טור הארוך · Perush al ha-Torah, Hanover, 1838 · נחלת הכלל · ספריא","chapter":21,"verse":7,"dh":"מי מלל לאברהם.","text":"פירש\"י לשון שבח וחשיבות ראו מי הוא וכמה הוא גדול שומר הבטחתו שמבטיחו ועושה. וכתב הרמב\"ן שלעולם לא תבא מי לשבח אלא לגנאי מי אבימלך ומי שכם מי דוד ומי אנשיו. ופי' הוא כל השומע יצחק לי מרוב הפלא שנעשה עמי כי מי בכל השומעים שאמר לאברהם תחלה שתניק בנים שרה אין בעולם מי שיאמר לו כן אפי' לנחמו שלא עלה על לב זה לעולם:","complete":true},{"workId":"Rabbeinu_Bahya_on_Genesis","unitId":"Rabbeinu_Bahya_on_Genesis.21.16","commentator":"רבינו בחיי","sourceLine":"רבינו בחיי · Midrash Rabbeinu Bachya [ben Asher]. Warsaw, 1878 · נחלת הכלל · ספריא","chapter":21,"verse":23,"dh":"אם תשקור לי ולניני ולנכדי.","text":"ביקש אבימלך שתי בריתות. האחד שלא יגרש אברהם את בניו מארצם, והשנית שלא ישחיתו להם פירות הארץ, זהו שאמר ועם הארץ אשר גרתה בה. ואברהם הודה בדבר ואמר אנכי אשבע. והבן היטב כי זאת השבועה היא הראשונה הנזכרת בתורה, ומפני שלשון שבועה נגזר מן שבעה כידוע בקבלה, לכך הציב אברהם שבע כבשות הצאן, וקרא המקום על שם השבועה באר שבע, וכן ביצחק מצינו שקרא הבאר על שם השבועה.","complete":true},{"workId":"Rashbam_on_Genesis","unitId":"Rashbam_on_Genesis.22.1","commentator":"רשב״ם","sourceLine":"רשב״ם · דעת · נחלת הכלל · ספריא","chapter":22,"verse":1,"dh":null,"text":"ויהי אחר הדברים האלה - כל מקום שנאמר: אחר הדברים האלה מחובר אל הפרשה שלמעלה. אחר הדברים האלה שהרג אברם המלכים אמר לו הקב\"ה: אל תירא אברם מן האומות. ויהי אחר הדברים האלה, שנולד יצחק ויוגד לאברהם לאמר כו' ובתואל ילד את רבקה. וכן אחר הדברים האלה שהגיד מרדכי על בגתן ותרש גדל המלך אחשורוש את המן שרצה להרוג את מרדכי והועיל לו מה שהציל את המלך ונתלה המן. אף כאן אחר הדברים שכרת אברהם ברית לאבימלך לו ולנינו ולנכדו של אברהם ונתן לו שבע כבשות הצאן וחרה אפו של הקב\"ה על זאת, שהרי ארץ פלשתים ניתן לאברהם וגם ביהושע מטילים על ערי חמשת סרני פלשתים גורל בכלל גבול ישראל והקב\"ה ציוה עליהם לא תחיה כל נשמה לכן -","complete":true}],"chayei-sara":[{"workId":"Haamek_Davar_on_Genesis","unitId":"Haamek_Davar_on_Genesis.23.2","commentator":"העמק דבר","sourceLine":"העמק דבר · ספר תורת אלוהים, וילנא 1879 · נחלת הכלל · ספריא","chapter":23,"verse":1,"dh":"שני חיי שרה.","text":"מיותר ואין כן בכ״מ זה הלשון. והנה כבר פירשנו כ״פ פי׳ חיים בלשה״ק בשתי משמעות. אחת חיים ולא מות. ב׳ שמח ועלז ולא עצבון. כענין שאמרו ביומא ס״פ בא לו. שנות חיים ושלום שנים המתהפכות מרעה לטובה. וכן בארצות החיים מקום שוקים. תמן שובעא כו׳. וע׳ מש״כ דברים פ׳ ואתחנן עה״פ ואתם הדבקים וגו׳. ואחר כ״ז יש להתבונן במה שאמרו שאברהם היה טפל לשרה בנביאות. ואין זה אלא תימא. האדם הגדול אשר דבר עמו ה׳ כ״פ. יהיה טפל לשרה שלא דבר עמה ה׳ כ״א דבור א׳ לא כי צחקת. ומפרשים ברבה שהוא דבר ה׳. אלא הכונה הוא שהיה טפל ברוה״ק. שהרי שני דברים הם רוה״ק הוא מה שאדם מתבודד ומשרה עליו רוה״ק ויודע מה שרואה. אמנם לא דבר עמו ה׳.","complete":false},{"workId":"Tur_HaArokh_on_Genesis","unitId":"Tur_HaArokh_on_Genesis.23.14","commentator":"טור הארוך","sourceLine":"טור הארוך · Perush al ha-Torah, Hanover, 1838 · נחלת הכלל · ספריא","chapter":23,"verse":19,"dh":"ואחרי כן קבר.","text":"פי' ה\"ר מאיר בכל הפרשה אמר אברהם לשון יחיד תחלה ואקבר' מתי מלפני על מת אחד והשיבו לו דרך מוסר קבור מתיך אף אם הם רבים וכן אחר כך אם יש את נפשיכם לקבור את מתי מלפני ועפרון השיבו נתתיה לך קבור מתיך וכן ואקברה את מתי שמה לשון יחיד והוא השיבו ואת מתך קבור אף אם הם רבים:","complete":true},{"workId":"Rabbeinu_Bahya_on_Genesis","unitId":"Rabbeinu_Bahya_on_Genesis.24.15","commentator":"רבינו בחיי","sourceLine":"רבינו בחיי · Midrash Rabbeinu Bachya [ben Asher]. Warsaw, 1878 · נחלת הכלל · ספריא","chapter":24,"verse":10,"dh":"וכל טוב אדוניו בידו.","text":"היה הכ' ראוי לומר ומטוב אדוניו כמ\"ש מגמלי אדוניו כי עשר גמלים לא יכילו כל טוב אדוניו, אבל ע\"ד הפשט יעיד הכתוב על מעלת העבד ועל אמונתו ויגיד כי כל כבוד עשרו ונכסיו של אברהם הכל היה ברשותו, כי כבר הוחזק אצלו איש אמונים ונתן הכל בידו כלו' ברשותו כמו (במדבר כ״א:כ״ו) ויקח את כל ארצו מידו:","complete":true},{"workId":"Or_HaChaim_on_Genesis","unitId":"Or_HaChaim_on_Genesis.24.25","commentator":"אור החיים","sourceLine":"אור החיים · Vocalized Edition · נחלת הכלל · ספריא","chapter":24,"verse":29,"dh":"וּלְרִבְקָה אָח וּשְׁמוֹ לָבָן וְגוֹ׳.","text":"לְדִבְרֵיהֶם זִכְרוֹנָם לִבְרָכָה (במדבר רבה י; אסתר רבה ו,ג) שֶׁאָמְרוּ כִּי הַצַּדִּיקִים שְׁמָם קוֹדֵם לָהֶם, דִּכְתִיב (רות ב:א) ״וּשְׁמוֹ בּוֹעַז״, ״וְשֵׁם הָאִישׁ אֱלִימֶלֶךְ״ (רות א:ב), אֲבָל הָרְשָׁעִים הֵם קוֹדְמִים לִשְׁמָם, דִּכְתִיב (שמואל א כה:כה) ״נָבָל שְׁמוֹ״ וְגוֹ׳. אִם כֵּן לָמָּה לָקַח הַכָּתוּב סֵדֶר הַצַּדִּיקִים בְּלָבָן הָרָשָׁע? וְלָתֵת טַעַם לַדָּבָר יֵשׁ לְהָעִיר בַּכָּתוּב אָמְרוֹ וַיָּרָץ לָמָּה רָץ, וְרַבּוֹתֵינוּ זִכְרוֹנָם לִבְרָכָה (ילקוט שמעוני קט) אָמְרוּ לְפִי שֶׁרָאָה הַנֶּזֶם וְכוּ׳ נָתַן עֵינָיו בַּמָּמוֹן.","complete":false},{"workId":"Kli_Yakar_on_Genesis","unitId":"Kli_Yakar_on_Genesis.25.1","commentator":"כלי יקר","sourceLine":"כלי יקר · Vocalized Edition · נחלת הכלל · ספריא","chapter":25,"verse":1,"dh":"וַיֹּסֶף אַבְרָהָם וַיִּקַּח אִשָּׁה וּשְׁמָהּ קְטוּרָה.","text":"חָזַר וְנָשָׂא אֶת הָגָר וּקְרָאָהּ קְטוּרָה עַל שֵׁם שֶׁמַּעֲשֶׂיהָ נָאִים כִּקְטֹרֶת, וְכֵן מַשְׁמַע לְשׁוֹן ״וַיֹּסֶף״ שֶׁנְּשָׂאָהּ שֵׁנִית. וְיֵשׁ לָנוּ לִתֵּן טַעַם לָמָּה קְרָאָהּ עַכְשָׁיו קְטוּרָה עַל שֵׁם מַעֲשֶׂיהָ, וְעוֹד שֶׁזֶּה סוֹתֵר לְמַה שֶּׁפֵּרֵשׁ רַשִׁ״י פָּרָשַׁת וַיֵּרָא (בראשית כא, יד) ״וַתֵּלֶךְ וַתֵּתַע״ שֶׁחָזְרָה לְגִלּוּלֵי בֵית אָבִיהָ.","complete":false}],"toldot":[{"workId":"Rabbeinu_Bahya_on_Genesis","unitId":"Rabbeinu_Bahya_on_Genesis.25.9","commentator":"רבינו בחיי","sourceLine":"רבינו בחיי · Midrash Rabbeinu Bachya [ben Asher]. Warsaw, 1878 · נחלת הכלל · ספריא","chapter":25,"verse":19,"dh":"שלמה","text":"ע\"ה הודיענו בכתוב הזה (משלי יז) לפי פשוטו שהבנים הם עטרה וכבוד לאבות, שמצינו באברהם שנתעטר בו תרח אביו, זהו עטרת זקנים בני בנים, אבל האבות הם תפארת לבנים, כי כשהאבות צדיקים והבנים מתפארים באבותם זה להם לכבוד ולתפארת, ועל זה אמר תפארת ולא אמר עטרת שהרי עטרה גדולה מתפארת לפי הפשט ושבח גדול יותר, ואימתי האבות תפארת לבנים כשהבנים עושים מעשה אבותיהם אותה שעה הם להם לתפארת, אבל אם אין אוחזים מעשה אבותיהם בידיהם אין הדבר להם לתפארת כי אם לבושת וגם לחרפה וחסרון גדול, כענף המכחש את השורש.","complete":true},{"workId":"Tur_HaArokh_on_Genesis","unitId":"Tur_HaArokh_on_Genesis.26.7","commentator":"טור הארוך","sourceLine":"טור הארוך · Perush al ha-Torah, Hanover, 1838 · נחלת הכלל · ספריא","chapter":26,"verse":8,"dh":"והנה יצחק מצחק את רבקה אשתו.","text":"אע\"פ שאסור לשמש ביום וליכא למימר דבבית אפל היה שהרי ראה אותו. וי\"ל דתלמיד חכם מאפיל בטליתו ושרי. וי\"מ מפני שראה החלון סגור ביום הבין שעשאו כדי להאפיל ולשמש מטתו ומיהו תימה היאך שמש מטתו בשני רעבון וי\"ל כיון שהיה לו שובע ואין יהודי אחר בעולם שיצטער עליו שרי ומהאי מעמא נמי שמש לוי כדאמרינן שיוכבד נולדה בין החומות ויוסף לא שמש אע\"פ שהיה לו שובע שהיה מצטער על רעבון אחיו ובית אביו:","complete":true},{"workId":"Or_HaChaim_on_Genesis","unitId":"Or_HaChaim_on_Genesis.26.9","commentator":"אור החיים","sourceLine":"אור החיים · Vocalized Edition · נחלת הכלל · ספריא","chapter":26,"verse":15,"dh":"וְכָל הַבְּאֵרוֹת וְגוֹ׳.","text":"סָמַךְ הוֹדָעָה זוֹ לְ״וַיְקַנְאוּ״ וְגוֹ׳, לוֹמַר כִּי לֹא יָנוּחַ שֵׁבֶט הָרֶשַׁע עַל גּוֹרַל הַצַּדִּיקִים, וְהוֹדִיעַ שֶׁקִּנְאוּ מִמֶּנּוּ, וְהוֹסִיף לְהוֹדִיעַ שֶׁגַּם עִם אַבְרָהָם הָיָה לָהֶם קִנְאָה וְשִׂנְאָה ״וְכָל הַבְּאֵרוֹת אֲשֶׁר״ וְגוֹ׳.","complete":false},{"workId":"Haamek_Davar_on_Genesis","unitId":"Haamek_Davar_on_Genesis.26.48","commentator":"העמק דבר","sourceLine":"העמק דבר · ספר תורת אלוהים, וילנא 1879 · נחלת הכלל · ספריא","chapter":26,"verse":23,"dh":"ויעל משם באר שבע.","text":"קשה היה על יצחק לדור בשדה ובכפר אם כי בטבעו היה בן כרך. או מחמת שביקש לקרוא בשם ה׳ וזה מסוגל יותר בכרך. ע״כ כשנגרש מגרר ועבר עליו איזה משך בשדה נסה דבר לגור בבאר שבע שגם היא עיר גדולה אבל עדיין לא נכנס עם ביתו לשם שהיה ירא שלא יקנאו אותו שרי העיר ההיא ג״כ. ע״כ בא אליו מראה ה׳.","complete":true},{"workId":"Ramban_on_Genesis","unitId":"Ramban_on_Genesis.26.12","commentator":"רמב״ן","sourceLine":"רמב״ן · On Your Way · נחלת הכלל · ספריא","chapter":26,"verse":32,"dh":"ויבואו עבדי יצחק ויגידו לו על אודות הבאר אשר חפרו","text":"הוא האמור בו למעלה (בראשית כ״ו:כ״ה) ויכרו שם עבדי יצחק באר כי החלו לחפור אותו ובא אבימלך אליו בימים ההם וביום הברית בלכתם ממנו בשרוהו כי מצאו מים וקרוב לי שהוא הבאר שכרה אברהם ונתן לו שבע כבשות לעדה (בראשית כ״א:ל׳) כי סתמוהו פלשתים עם האחרים וישב יצחק ויחפור אותו ויקרא לו גם הוא שם כשם אשר קרא לו אביו ועל כן שם העיר באר שבע על שם הבאר אשר קראוהו כן האב והבן כי שם נשבעו שניהם והבאר הזאת להם תרמז על משכן שילה ופלשתים סתמוהו בהלקח הארון (שמואל א ד יא) וחזר וחפרו בו כי כן השיבו הארון עם הדורון לאלהים (שם ו יא):","complete":true},{"workId":"Kli_Yakar_on_Genesis","unitId":"Kli_Yakar_on_Genesis.27.11","commentator":"כלי יקר","sourceLine":"כלי יקר · Vocalized Edition · נחלת הכלל · ספריא","chapter":27,"verse":28,"dh":"וְיִתֶּן לְךָ הָאֱלֹהִים.","text":"וָי״ו שֶׁל ״וְיִתֶּן״ מְיֻתֶּרֶת, וְדָרְשׁוּ רז״ל (בראשית רבה סו, ג) יִתֵּן וְיַחֲזוֹר וְיִתֵּן. וּבֵאוּר הָעִנְיָן כָּךְ הוּא, לְפִי שֶׁיָּדוּעַ שֶׁבְּכָל הַמִּצְווֹת שֶׁהָאָדָם עוֹשֶׂה אֵין בָּהֶם דֵּי לְהָשִׁיב ״כְּעַל גְּמֻלוֹת כְּעַל יְשַׁלֵּם״ (ישעיהו נט, יח) אוֹתָן הַטּוֹבוֹת שֶׁעָשָׂה הַקָּדוֹשׁ בָּרוּךְ הוּא כְּבָר עִמּוֹ מִיּוֹם הִוָּלְדוֹ, וְכָל מַה שֶּׁהָאָדָם עוֹשֶׂה מִן הַמִּצְווֹת הוּא עוֹשֶׂה אוֹתָן דֶּרֶךְ תַּשְׁלוּמִין.","complete":false}],"vayetzei":[{"workId":"Tur_HaArokh_on_Genesis","unitId":"Tur_HaArokh_on_Genesis.28.4","commentator":"טור הארוך","sourceLine":"טור הארוך · Perush al ha-Torah, Hanover, 1838 · נחלת הכלל · ספריא","chapter":28,"verse":12,"dh":"ויחלום והנה סולם מוצב ארצה.","text":"מדרשי' רבים דרשו רבותינו בזה. וי\"מ סולם זה הר סיני ומלאכי אלקים עולים ויורדים בו זה משה ואהרן. וי\"מ שהוא המזבח והכהני' עולים ויורדים. והנכון שהראהו בחלום הנבואה שכל הנעשה בארץ נעשה ע\"י מלאכים והכל בגזירת עליון עליהם אע\"פ שהכל גלוי וידוע לפניו הראהו כאלו עולים לו לומר עשינו שליחותך ויורדים לעשות שליחותם והראהו שאע\"פ שהכל ביד מלאך עניינו לא יהיה ביד מלאך אלא יהיה חלק ה' ויהיה תמיד עמו לשמרו כענין שנא' והנה אנכי עמך ושמרתיך בכל אשר תלך ועוד איתא בב\"ר שהראהו ד' מלכיות עלייתן וירידתן:","complete":true},{"workId":"Kli_Yakar_on_Genesis","unitId":"Kli_Yakar_on_Genesis.29.1","commentator":"כלי יקר","sourceLine":"כלי יקר · Vocalized Edition · נחלת הכלל · ספריא","chapter":29,"verse":1,"dh":"וַיִּשָּׂא יַעֲקֹב רַגְלָיו וַיֵּלֶךְ.","text":"לְפִי שֶׁבַּהֲלִיכָה רִאשׁוֹנָה אָמְרוּ רז״ל (סנהדרין צה) שֶׁקָּפְצָה לוֹ הָאָרֶץ, וּלְפִי זֶה לֹא הָיְתָה הַהֲלִיכָה תְּלוּיָה בְּזֵרוּז רַגְלָיו כִּי אִם בְּנֵס, הֻצְרַךְ לוֹמַר שֶׁמִּכָּאן וָהָלְאָה לֹא הָלַךְ עַל יְדֵי קְפִיצַת הָאָרֶץ, כִּי אִם בְּרַגְלָיו כִּשְׁאָר אָדָם.","complete":true},{"workId":"Or_HaChaim_on_Genesis","unitId":"Or_HaChaim_on_Genesis.29.33","commentator":"אור החיים","sourceLine":"אור החיים · Vocalized Edition · נחלת הכלל · ספריא","chapter":29,"verse":18,"dh":"אוֹ","text":"יֹאמַר עַל דֶּרֶךְ אָמְרָם זִכְרוֹנָם לִבְרָכָה (שבת כה:) בְּדִין זִוּוּג תַּלְמִיד חָכָם שֶׁצָּרִיךְ שֶׁתִּהְיֶה לוֹ אִשָּׁה נָאָה כְּנֶגֶד יֵצֶר הָרַע, וַהֲגַם כִּי יִשְׁתַּנֶּה יַעֲקֹב לְמַעֲלִיּוּתָא שֶׁמּוּשְׁלָל מִיֵּצֶר הָרַע, עִם כָּל זֶה הַתּוֹרָה תְּלַמֵּד לְאָדָם דַּעַת.","complete":true},{"workId":"Sforno_on_Genesis","unitId":"Sforno_on_Genesis.30.16","commentator":"ספורנו","sourceLine":"ספורנו · Vocalized Edition · נחלת הכלל · ספריא","chapter":30,"verse":14,"dh":"וַיִּמְצָא דוּדָאִים.","text":"מִין עֵשֶׂב טוֹב הָרֵיחַ וּמֵכִין כְּלֵי הַזֶּרַע אֶל הַתּוֹלָדָה, כְּמוֹ שֶׁאָמְרוּ זִכְרוֹנָם לִבְרָכָה עַל הַשּׁוּם (בבא קמא פב.) וְשֶׁלְּכָךְ הָיוּ אוֹכְלִים אוֹתוֹ בְּעֶרֶב שַׁבָּת, וְכֵן הָיָה מִין הַדּוּדָאִים אוֹ טוֹב מִמֶּנּוּ עִם הוֹסִיפָם אַהֲבַת הַזִּוּוּג, כְּאָמְרוֹ (שיר השירים ז:יג-יד) \"שָׁם אֶתֵּן אֶת דּוֹדַי לָךְ, הַדּוּדָאִים נָתְנוּ רֵיחַ\". וּבָזֶה הוֹדִיעָנוּ צִדְקַת רְאוּבֵן וְחָכְמָתוֹ עִם הֱיוֹתוֹ אָז בֶּן אַרְבַּע אוֹ חָמֵשׁ שָׁנִים לְמַרְבֶּה.","complete":true},{"workId":"Ramban_on_Genesis","unitId":"Ramban_on_Genesis.30.10","commentator":"רמב״ן","sourceLine":"רמב״ן · On Your Way · נחלת הכלל · ספריא","chapter":30,"verse":29,"dh":"ואת אשר היה מקנך אתי","text":"את חשבון מיעוט מקנך שבא לידי כמה היה לשון רש\"י (רש\"י על בראשית ל׳:כ״ט) כלומר אתה ידעת כמה היה מקנך כשבאו אתי ויותר ראוי שיאמר ואת מקנך אשר היה אתי ידעת כי מעט אשר היה לך טרם בואי ויפרוץ לרוב או נפרש אתה ידעת את אשר עבדתיך כי בכל כחי עשיתי וידעת את אשר היה מקנך אתי כי ימים רבים הם וידעת כי מעט אשר היה לך לפני ויפרוץ לרוב שלא כדרך כל הארץ רק ברכת ה' היא אשר באה מעת בא רגלי בביתך והוא הנכון:","complete":true},{"workId":"Rabbeinu_Bahya_on_Genesis","unitId":"Rabbeinu_Bahya_on_Genesis.31.3","commentator":"רבינו בחיי","sourceLine":"רבינו בחיי · Midrash Rabbeinu Bachya [ben Asher]. Warsaw, 1878 · נחלת הכלל · ספריא","chapter":31,"verse":19,"dh":"ותגנב רחל את התרפים.","text":"דעת הרמב\"ן בתרפים כי היו כלים לקבל השעות ויקסמו לדעת העתידות. והמלה נגזרה מלשון נרפים ויקראו להם תרפים לרמוז עליהם כי דבריהם כמו נבואה רפה, תבא ברוב ותכזב לעתים רחוקות. והיו מדברים מדרך חכמת השעות והוא שכתוב (זכריה י ב) כי התרפים דברו און. ולמה גנבה אותם כדי שלא יגלו לאביה אם ישאל בהם כי בורח יעקב. ומה שאמר לבן ליעקב למה גנבת את אלהי לאות ולעד כי התרפים היו אלהיו.","complete":true}],"vayishlach":[{"workId":"Tur_HaArokh_on_Genesis","unitId":"Tur_HaArokh_on_Genesis.32.5","commentator":"טור הארוך","sourceLine":"טור הארוך · Perush al ha-Torah, Hanover, 1838 · נחלת הכלל · ספריא","chapter":32,"verse":4,"dh":"ארצה שעיר שדה אדום.","text":"שהעובר מחרן לארץ ישראל עובר דרך ארץ שעיר אע\"ג דלקמן אומר שעיקר ישיבתו בארץ כנען דכתיב ויקח עשו את נשיו וגו' אשר רכשו בארץ כנען וישב שם עד שהלך מפני יעקב צ\"ל כיון שנשיו היו משעיר חשב יעקב שימצאהו אצל נשיו. ודרשו עליו מאחז באזני כלב שיעקב התעורר לעשו שיצא לקראתו והוא רמז לתחלת נפילתו ביד אדום כי מלכי בית שני באו בברית עם הר' ומהם הלכו לר' והיא היתה סבת נפילתם בידם:","complete":true},{"workId":"Kli_Yakar_on_Genesis","unitId":"Kli_Yakar_on_Genesis.32.18","commentator":"כלי יקר","sourceLine":"כלי יקר · Vocalized Edition · נחלת הכלל · ספריא","chapter":32,"verse":14,"dh":"וַיִּקַּח מִן הַבָּא בְיָדוֹ וְגוֹ׳.","text":"לְמַעְלָה פֵּרַשְׁתִּי שֶׁנֶּאֱמַר זֶה כְּפִי מַה שֶׁהֶרְאָה בַּנִּגְלֶה לְעֵשָׂו, כִּי כָל זֶה אֵינוֹ לֹא מִן הַשָּׁמַיִם וְלֹא מִן הָאָרֶץ, כִּי אִם מִן הַבָּא בְּיָדוֹ מֵעֲמָלוֹ וְכֹחוֹ וְעֹצֶם יָדוֹ. אַךְ כְּפִי הָאֱמֶת הוֹדָה יַעֲקֹב כִּי ה׳ הוּא הַנּוֹתֵן לוֹ כֹּחַ לַעֲשׂוֹת חָיִל, וְזֶה הַמְעַט אֲשֶׁר בָּא בְּיָדוֹ מֵעֲמַל יָדוֹ יִפְרֹץ לָרֹב וּבִרְכַּת ה׳ הִיא תַעֲשִׁיר, וְעָמָל הוּא בְּעֵינֵי יַעֲקֹב לָתֵת מִבִּרְכַּת ה׳ לְרָשָׁע זֶה, כִּי תּוֹסֶפֶת שֶׁפַע זֶה מִמָּקוֹם קָדוֹשׁ מִתְהַלֵּךְ וְאֵין רָשָׁע זֶה כְּדַאי לְהִשְׁתַּמֵּשׁ בּוֹ.","complete":false},{"workId":"Or_HaChaim_on_Genesis","unitId":"Or_HaChaim_on_Genesis.32.35","commentator":"אור החיים","sourceLine":"אור החיים · Vocalized Edition · נחלת הכלל · ספריא","chapter":32,"verse":33,"dh":"עַל כֵּן לֹא יֹאכְלוּ וְגוֹ׳.","text":"פֵּרוּשׁ: לְצַד שֶׁנִּזְדַּעְזַע הַגִּיד מִמְּקוֹר הַקְּדֻשָּׁה וְשָׁלַט בּוֹ הַקְּלִפָּה, בְּחִינָה זוֹ בְּכָל מָקוֹם שֶׁהִיא נִטְמְאָה, וַאֲסָרָהּ הַבּוֹרֵא כִּי הוּא הַיּוֹדֵעַ. וְתִמְצָא סוֹד בָּזֶה כִּי גִּיד זֶה אֵין בּוֹ טַעַם, וְהוּא סִימָן לִבְחִינַת הַקְּלִפָּה, כִּי אֵין בָּהּ טַעַם כֵּיוָן שֶׁנֶּעֶקְרָה קְדֻשָּׁה מִמֶּנּוּ. וְיֵשׁ בָּזֶה פְּשָׁטִים לוֹמַר, אֶלָּא שֶׁהָעִקָּר כְּמוֹ שֶׁכָּתַבְתִּי.","complete":true},{"workId":"Ramban_on_Genesis","unitId":"Ramban_on_Genesis.33.2","commentator":"רמב״ן","sourceLine":"רמב״ן · On Your Way · נחלת הכלל · ספריא","chapter":33,"verse":8,"dh":"מי לך כל המחנה הזה אשר פגשתי","text":"הנה עבדי יעקב עשו כאשר צוה אותם ולא רצה לקבל מהם או שהוא בגאותו ועברתו לא דבר עמם ולא שאלם למי אתה ואנה תלך והם יראו מגשת אליו ואמר עתה מי לך כל המחנה הזה כי חשב שהם ליעקב מדברי המלאכים הראשונים או שאלה השלוחים הגידו כן במחנה עשו או שאין אדם אחד בדרך ההוא להיות לו כן וטעם מי לך כל המחנה הזה כלומר מי זה לך שתשלח לו כל אלה כלומר מי הוא הגדול אצלך שתשלח לו כל אלה והוא ענהו למצוא חן בעיני אדוני כי אתה הגדול והאדון בעיני:","complete":true},{"workId":"Haamek_Davar_on_Genesis","unitId":"Haamek_Davar_on_Genesis.34.1","commentator":"העמק דבר","sourceLine":"העמק דבר · ספר תורת אלוהים, וילנא 1879 · נחלת הכלל · ספריא","chapter":34,"verse":1,"dh":"ותצא דינה.","text":"ותבא מיבעי שהרי דירת יעקב היתה חוץ לעיר והיא באה העיר לראות בבנות הארץ. אלא משמעות ותצא מחין ערכה וכבודה שנכנסה לראות במחול ובשמחת בנות הארץ ויציאת חוץ מגדר הראוי מיקרי יציאה. והיינו דאית׳ ריש שבת תנא הכנסה הוצאה קרי לה. והטעם ע״ז משום דבשבת אסור להביא מרה״ר לרה״י. א״כ כשמביא מרה״ר נקרא הוצאה ממקומו הראוי לו:","complete":true},{"workId":"Sforno_on_Genesis","unitId":"Sforno_on_Genesis.35.21","commentator":"ספורנו","sourceLine":"ספורנו · Vocalized Edition · נחלת הכלל · ספריא","chapter":35,"verse":14,"dh":"וַיַּסֵּךְ עָלֶיהָ נֶסֶךְ.","text":"וְהִשְׁלִים נִדְרוֹ שֶׁנָּדַר בְּאָמְרוֹ \"וְהָאֶבֶן הַזֹּאת אֲשֶׁר שַׂמְתִּי מַצֵּבָה יִהְיֶה בֵּית אֱלֹהִים\" (בראשית כח:כב). כִּי בָּזֶה הֵכִין אֶת הַמָּקוֹם שֶׁרָאוּי שֶׁיְּקִימֶנָּה שָׁם, כְּעִנְיַן דָּוִד בְּהֵרָאוֹת אֵלָיו הַמַּלְאָךְ בְּגֹרֶן אֲרַוְנָה הַיְבוּסִי:","complete":true}],"vayeshev":[{"workId":"Kli_Yakar_on_Genesis","unitId":"Kli_Yakar_on_Genesis.37.1","commentator":"כלי יקר","sourceLine":"כלי יקר · Vocalized Edition · נחלת הכלל · ספריא","chapter":37,"verse":1,"dh":"וַיֵּשֶׁב יַעֲקֹב בְּאֶרֶץ מְגוּרֵי אָבִיו בְּאֶרֶץ כְּנָעַן.","text":"הָיָה לוֹ לוֹמַר ״וַיֵּשֶׁב יַעֲקֹב בְּאֶרֶץ יְשִׁיבַת אָבִיו״, אוֹ ״וַיָּגָר יַעֲקֹב בְּאֶרֶץ מְגוּרֵי אָבִיו״, וְעוֹד ״בְּאֶרֶץ כְּנָעַן״ לָמָּה לִי? אֶלָּא לְפִי שֶׁמַּאֲשִׁים אֶת יַעֲקֹב עַל שֶׁבִּקֵּשׁ לֵישֵׁב בָּעוֹלָם הַזֶּה יְשִׁיבָה שֶׁל קֶבַע, לִהְיוֹת כְּתוֹשָׁב בָּעוֹלָם הַזֶּה בִּמְקוֹם מְגוּרֵי אָבִיו, כִּי אָבִיו לֹא כֵן עָשָׂה, אֶלָּא הָיָה בָּעוֹלָם הַזֶּה כְּגֵר וּכְאוֹרֵחַ נָטָה לָלוּן, לְפִי שֶׁאָמַר לוֹ הַקָּדוֹשׁ בָּרוּךְ הוּא ״גּוּר בָּאָרֶץ הַזֹּאת״ (בראשית כו, ג). הִזְכִּיר לְשׁוֹן ״גּוּר״, כִּי רָצָה ה׳ שֶׁלֹּא יְבַקֵּשׁ יְשִׁיבָה שֶׁל קֶבַע בָּעוֹלָם הַזֶּה.","complete":false},{"workId":"Or_HaChaim_on_Genesis","unitId":"Or_HaChaim_on_Genesis.37.36","commentator":"אור החיים","sourceLine":"אור החיים · Vocalized Edition · נחלת הכלל · ספריא","chapter":37,"verse":14,"dh":"לֶךְ נָא רְאֵה וְגוֹ׳.","text":"עַתָּה הוּא מְפָרֵשׁ שְׁלִיחוּת הַמִּצְוָה שֶׁעוֹשֶׂה, וְאָמַר וַהֲשִׁיבֵנִי דָּבָר – עֲשָׂאוֹ שָׁלִיחַ לְהַחְזִיר לוֹ תְּשׁוּבָה, שֶׁבָּזֶה אֲפִלּוּ לְמַאן דְּאָמַר (פסחים ח:) שְׁלוּחֵי מִצְוָה אֵינָם נִזּוֹקִים דַּוְקָא בַּהֲלִיכָתָן אֲבָל לֹא בַּחֲזָרָתָן, בִּמְצִיאוּת זֶה עֲשָׂאוֹ שָׁלִיחַ גַּם בַּחֲזָרָתוֹ, וּמֵעַתָּה הֲרֵי הוּא בָּטוּחַ שֶׁיָּשׁוּב בְּשָׁלוֹם אֵצֶל אָבִיו.","complete":true},{"workId":"Sforno_on_Genesis","unitId":"Sforno_on_Genesis.37.34","commentator":"ספורנו","sourceLine":"ספורנו · Vocalized Edition · נחלת הכלל · ספריא","chapter":37,"verse":25,"dh":"וַיֵּשְׁבוּ לֶאֱכָל לֶחֶם.","text":"שֶׁלֹּא הָיָה כָּל זֶה בְּעֵינֵיהֶם תַּקָּלָה אוֹ מִכְשׁוֹל שֶׁיִּמְנָעֵם מִלִּקְבֹּעַ סְעוּדָתָם, כְּמוֹ שֶׁהָיָה רָאוּי לְצַדִּיקִים כְּמוֹתָם כְּשֶׁאֵרְעָה תַּקָּלָה עַל יָדָם, כְּמוֹ שֶׁעָשׂוּ יִשְׂרָאֵל אַחַר שֶׁהָרְגוּ אֶת שֵׁבֶט בִּנְיָמִין, כְּאָמְרוֹ: \"וַיֵּשְׁבוּ עַד הָעֶרֶב לִפְנֵי הָאֱלֹהִים וַיִּשְׂאוּ קוֹלָם וַיִּבְכּוּ בְּכִי גָדוֹל וַיֹּאמְרוּ לָמָה ה' אֱלֹהֵי יִשְׂרָאֵל הָיְתָה זֹאת בְּיִשְׂרָאֵל\" (שופטים כא:ב-ג). וְכֵן דָּרְיָוֶשׁ כְּשֶׁהִשְׁלִיךְ אֶת דָּנִיֵּאל בְּגוֹב אֲרָיוֹת, דִּכְתִיב: \"וּבָת טְוָת וְדַחֲוָן לָא הַנְעֵל קָדָמוֹהִי\" (דניאל ו:יט).","complete":false},{"workId":"Haamek_Davar_on_Genesis","unitId":"Haamek_Davar_on_Genesis.38.1","commentator":"העמק דבר","sourceLine":"העמק דבר · ספר תורת אלוהים, וילנא 1879 · נחלת הכלל · ספריא","chapter":38,"verse":1,"dh":"ויהי בעת ההיא.","text":"יבואר שהעת גרם לענין הבא לפנים. ופרש״י שהורידוהו מגדולתו. ולפ״ז לא שייך סמיכות הפרשה אלא למש״כ וירד יהודה. ולא לכל הענין. אבל ברבה איתא בטרם תחיל ילדה. קודם שנולד משעבד הראשון נולד גואל האחרון ויהי בעת ההיא מה כתיב למעלה מן הענין והמדנים מכרו אותו אל מצרים הרי מבואר סמיכות כל הענין :","complete":true},{"workId":"Rabbeinu_Bahya_on_Genesis","unitId":"Rabbeinu_Bahya_on_Genesis.39.1","commentator":"רבינו בחיי","sourceLine":"רבינו בחיי · Midrash Rabbeinu Bachya [ben Asher]. Warsaw, 1878 · נחלת הכלל · ספריא","chapter":39,"verse":1,"dh":"ויוסף הורד מצרימה.","text":"דרשו רז\"ל בן אמה מוכר בן חורים, ועבד קונה אותו. שהרי המדינים מכרו אותו שהיו בני האמה בני הגר, ופוטיפר היה עבד, ונתקיים הכתוב (קהלת י) ראיתי עבדים על סוסים. ושר הטבחים זה ממונה היה להרוג כל חייבי ההריגה בגזרת המלך והיה גבור חיל ובעל זרוע כמו נבוזארדן שהיה שר גדול, כענין שכתוב (ירמיה לט) וישלח נבוזראדן רב טבחים, וכתיב (מ\"ב כה) ואת יתר ההמון הגלה נבוזראדן רב טבחים. וכן מצינו באריוך כתיב (דניאל ב) באדין דניאל התיב עיטה וטעם לאריוך רב טבחיא די מלכא.","complete":true},{"workId":"Ramban_on_Genesis","unitId":"Ramban_on_Genesis.39.6","commentator":"רמב״ן","sourceLine":"רמב״ן · On Your Way · נחלת הכלל · ספריא","chapter":39,"verse":9,"dh":"וחטאתי לאלהים","text":"בני נח נצטוו על העריות לשון רש\"י (רש\"י על בראשית ל״ט:ט׳) ונכון הוא רק בעבור חסרון דעת הנשים הקדים אליה כי הדבר בגידה באדוניו אשר בוטח בו ואחרי כן אמר כי יש בענין עוד חטא לאלהים ויתכן לפרש עוד וחטאתי לאלהים בבגידה הזאת כי רעה גדולה היא שיהיה בה לי חטא לפני האלהים כי עיניו בנאמני ארץ (תהלים קא ו) ולא לפניו בוגד יבא ודברו אמת רק לא הזכיר אסור הערוה כי דבר עמה כדרך הנשים:","complete":true}],"miketz":[{"workId":"Or_HaChaim_on_Genesis","unitId":"Or_HaChaim_on_Genesis.41.1","commentator":"אור החיים","sourceLine":"אור החיים · Vocalized Edition · נחלת הכלל · ספריא","chapter":41,"verse":1,"dh":"וַיְהִי מִקֵּץ.","text":"טַעַם אָמְרוֹ לְשׁוֹן צַעַר, כִּי עַתָּה יַתְחִיל לְסוֹבֵב סִבַּת גָּלוּת מִצְרַיִם. וַהֲגַם שֶׁהַגָּלוּת כְּבָר נִגְזְרָה גְּזֵרָתוֹ מִשָּׁנִים קַדְמוֹנִיּוֹת, הֲלֹא אָמְרוּ רַבּוֹתֵינוּ כִּי לֹא נִגְזַר שֶׁיִּהְיֶה בְּמִצְרַיִם שֶׁהוּא כּוּר הַבַּרְזֶל, וּכְמוֹ שֶׁכָּתְבוּ הַתּוֹסָפוֹת בְּמַסֶּכֶת שַׁבָּת (י:) וּכְמוֹ שֶׁכָּתַב הָרַאבַ״ד (הִלְכוֹת תְּשׁוּבָה פֶּרֶק ו) כִּי הַמִּצְרִים הוֹסִיפוּ לְצַעֵר יוֹתֵר מִמַּה שֶׁאָמַר הַכָּתוּב ״וַעֲבָדוּם וְעִנּוּ״ וְגוֹ׳ (בראשית טו:יג).","complete":true},{"workId":"Haamek_Davar_on_Genesis","unitId":"Haamek_Davar_on_Genesis.41.15","commentator":"העמק דבר","sourceLine":"העמק דבר · ספר תורת אלוהים, וילנא 1879 · נחלת הכלל · ספריא","chapter":41,"verse":16,"dh":"בלעדי אלהים וגו׳.","text":"כמו שאמר דניאל לנ״נ. ואנא לא בחכמה די איתי בי מן כל חייא רזא דנא גלי לי להן על דברת די פשרא למלכא יהודעון. פי׳ לא בשביל מעלתי שאני ראוי לדעת עתידות נגלה לי אלא בשביל המלך נגלה לי. כך אמר יוסף בלעדי לא מכחי ומעלתי אלא כדי שיגיע מזה שלום פרעה. יענה אלהים ע״י לכוין הפשרון:","complete":true},{"workId":"Rabbeinu_Bahya_on_Genesis","unitId":"Rabbeinu_Bahya_on_Genesis.41.56","commentator":"רבינו בחיי","sourceLine":"רבינו בחיי · Midrash Rabbeinu Bachya [ben Asher]. Warsaw, 1878 · נחלת הכלל · ספריא","chapter":41,"verse":55,"dh":"ותרעב כל ארץ מצרים.","text":"בשנה השנית. למד שקרא הקב\"ה לרעב, כענין שכתוב (מלכים ב ח׳:א׳) כי קרא ה' לרעב. וכתיב (תהילים ק״ה:ט״ז-י״ז) ויקרא רעב על הארץ, כל מטה לחם שבר. ומפני הרעב ויצעק העם אל פרעה ללחם, כן דרך הרעבים לקרוא ולצעוק אל מי שבידו להשביעם, כענין שכתוב (תהילים ק״ז:ה׳-ו׳) רעבים גם צמאים נפשם בהם תתעטף. וכתיב ויצעקו אל ה' בצר להם.","complete":true},{"workId":"Tur_HaArokh_on_Genesis","unitId":"Tur_HaArokh_on_Genesis.42.12","commentator":"טור הארוך","sourceLine":"טור הארוך · Perush al ha-Torah, Hanover, 1838 · נחלת הכלל · ספריא","chapter":42,"verse":21,"dh":"ולא שמענו.","text":"חשבו להם האכזריות לעונש גדול יותר מן המכירה וראובן אמר להם כבר אמרתי לכם אל תחטאו בו כי ילד הוא ומפני נערותו חטא לכם וראוי לכם להעביר על חטאת נעוריו ועתה גם דמו הנה נדרש פי' דמו עם האכזריות או יהי' פי' גם דמו אע\"פ שלא הרגתם אותו השם דורש דמו ונחשב לכם כאלו שפכתם דמו בהיותו נמכר עבד עולם כי יתכן שמת בעבור היותו ילד שעשועים ולא ניסה לעבוד:","complete":true},{"workId":"Ramban_on_Genesis","unitId":"Ramban_on_Genesis.43.4","commentator":"רמב״ן","sourceLine":"רמב״ן · On Your Way · נחלת הכלל · ספריא","chapter":43,"verse":18,"dh":"ולהתנפל עלינו","text":"כאדם שיתנפל ברצונו על חבירו מלוא קומתו ואונקלוס (תרגום אונקלוס על בראשית מ״ג:י״ח) תרגם להתגולל לאתרברבא עלנא שינשא עלינו כשוא הים לגליו ולהתנפל לאיסתקפא לשים עלינו דברים שלא היו כי הדבר שאינו יקרא נופל כמו לא נפל דבר אחד (יהושע כג יד) ותרגום עלילות דברים (דברים כב יד) תסקופי מלין וכן תרגם יונתן תואנה (שופטים יד ד) תוסקפא:","complete":true},{"workId":"Rashbam_on_Genesis","unitId":"Rashbam_on_Genesis.43.7","commentator":"רשב״ם","sourceLine":"רשב״ם · דעת · נחלת הכלל · ספריא","chapter":43,"verse":32,"dh":null,"text":"כי תועבה - וכיחוי ובזוי היא למצרים לאכול עם אנשי עבר הנהר כי נבזים היו בעיניהם ואנשי מצרים גסי רוח היו, כדכתיב: קראתי לזאת [רהב] הם שבת. וכן: כי תועבת מצרים כל רועה צאן. מבזים היו בעיניהם הרועים. כי הצאן היה מאוס בעיניהם. כדכתיב: הן נזבח את תועבת מצרים לעיניהם ולא יסקלונו. דבר המשוקץ למצרים ומאוס נזבח לעיניהם לצורינו ולא יבזו אותנו לסוקלנו באבנים, דרך בזיון כמו שמצינו בשמעי בן גרה יצא יצוא [ומקלל] ויסקל. קילל דוד וסיקל בעפר דרך בזיון.","complete":true}],"vayigash":[{"workId":"Haamek_Davar_on_Genesis","unitId":"Haamek_Davar_on_Genesis.44.24","commentator":"העמק דבר","sourceLine":"העמק דבר · ספר תורת אלוהים, וילנא 1879 · נחלת הכלל · ספריא","chapter":44,"verse":18,"dh":"ידבר נא עבדך דבר.","text":"האי דבר מיותר ומה הי׳ חסר אם הי׳ כתוב במקרא ידבר נא עבדך באזני אדני. אכן מתחלה יש לבאר משמעות באזני. והראשונים ז״ל פירשו מענין שיכנסו הדברים באזניך. ובאמת כך מתפרש לשון המקרא בס׳ דברים ל״א נגד כל ישראל באזניהם. וידבר משה באזני כל קהל ישראל. אבל יש משמעות אחר לזה הלשון כמו במדבר י״א ויהי העם כמתאוננים רע באזני ה׳ והפי׳ שם סמוך לשכינתו ית׳ כמבואר שם דמש״ה נענשו מיד. וכן המדבר בלחש שלא ישמעו רבים אלא הוא מיקרי מדבר באזניו ולפ״ז הכא נמי משמעות באזני אדני בלחישה שלא ישמעו כל הנצבים. והענין של המבוקש. דהאחים אמרו מתחלה אשר ימצא אתו ומת כדין ומשפט הגונב מבית המלך. והמושל אמר הוא יהיה לי עבד.","complete":false},{"workId":"Rabbeinu_Bahya_on_Genesis","unitId":"Rabbeinu_Bahya_on_Genesis.44.37","commentator":"רבינו בחיי","sourceLine":"רבינו בחיי · Midrash Rabbeinu Bachya [ben Asher]. Warsaw, 1878 · נחלת הכלל · ספריא","chapter":44,"verse":32,"dh":"ונראה","text":"כי כיון שהזכיר לשון אליך היה ראוי לומר וחטאתי לך, ועוד כי כן אמר לו (בראשית מג) אם לא הביאתיו אליך והצגתיו לפניך וחטאתי לך כל הימים, אבל אמר וחטאתי לאבי, כאלו אמר וחטאתי לאלהים, ויכלול יעקב אביו ואביו שבשמים, כי מפני שכבר הזכיר להם את האלהים אני ירא לכך יודיענו יהודה כי נקשר בזה בקשר חזק ואמיץ להיות גוזל אבותיו וחוטא לשניהם בשני עולמות, וזהו שאמר כל הימים כלומר בכל הימים.","complete":true},{"workId":"Or_HaChaim_on_Genesis","unitId":"Or_HaChaim_on_Genesis.45.8","commentator":"אור החיים","sourceLine":"אור החיים · Vocalized Edition · נחלת הכלל · ספריא","chapter":45,"verse":8,"dh":"וְעַתָּה לֹא אַתֶּם וְגוֹ׳.","text":"פֵּרוּשׁ, לָתֵת טַעַם לְהָסִיר מִלִּבָּם חֲשַׁשׁ הַשִּׂנְאָה, לְבַל יַחְשְׁבוּ כִּי יוֹסֵף יִשְׂטֹם אוֹתָם וְיִשְׂנָאֵם עַל אֲשֶׁר נִתְאַכְזְרוּ עָלָיו, וְיִהְיֶה בְּעֵינֵיהֶם דָּבָר רָחוֹק שֶׁיִּהְיֶה לֵב יוֹסֵף נָכוֹן עִמָּם, לָזֶה אָמַר לָהֶם: הֵן אֱמֶת כִּי בִּשְׁעַת מַעֲשֶׂה אֲשֶׁר מְכָרוּהוּ הָיוּ הַדְּבָרִים זָרִים בְּעֵינָיו, אֵיךְ יִהְיֶה כָּל הָאַכְזָרִיּוּת בְּלֵב אַחִים עַל אֲחִיהֶם, וּרְאוּיִים הֵם לִהְיוֹת שְׂנוּאִים אֶצְלוֹ.","complete":true},{"workId":"Kli_Yakar_on_Genesis","unitId":"Kli_Yakar_on_Genesis.45.14","commentator":"כלי יקר","sourceLine":"כלי יקר · Vocalized Edition · נחלת הכלל · ספריא","chapter":45,"verse":28,"dh":"רַב, עוֹד יוֹסֵף בְּנִי חָי.","text":"לְפִי שֶׁהִבְטִיחוֹ הַקָּדוֹשׁ בָּרוּךְ הוּא שֶׁאִם לֹא יָמוּת אֶחָד מִן בָּנָיו בְּחַיָּיו לֹא יִרְאֶה פְּנֵי גֵּהִנֹּם וְיִזְכֶּה לְמַה שֶּׁנֶּאֱמַר (תהלים לא כ) ״מָה רַב טוּבְךָ אֲשֶׁר צָפַנְתָּ לִּירֵאֶיךָ״, עַל כֵּן אָמַר כָּאן ״רַב״, מֵעַתָּה אֶזְכֶּה לִשְׂכַר הָעוֹלָם הַבָּא הַנִּקְרָא ״רַב״, כִּי הוּא עוֹלָם שֶׁכֻּלּוֹ אָרוֹךְ, מַה שֶּׁאֵין כֵּן בְּחַיֵּי הָעוֹלָם הַזֶּה שֶׁהֵם מְעַט וְרָעִים, כִּי לֹא הַרְבֵּה יִזְכֹּר יְמֵי חַיָּיו. וְעוֹד, שֶׁכְּבָר קִבֵּל עֹנֶשׁ שֶׁל בִּטּוּל מִצְוַת כִּבּוּד אָבִיו בָּעוֹלָם הַזֶּה, וּמֵעַתָּה יְקַבֵּל שְׂכָרוֹ מֻשְׁלָם לָעוֹלָם הַבָּא.","complete":false},{"workId":"Tur_HaArokh_on_Genesis","unitId":"Tur_HaArokh_on_Genesis.46.10","commentator":"טור הארוך","sourceLine":"טור הארוך · Perush al ha-Torah, Hanover, 1838 · נחלת הכלל · ספריא","chapter":46,"verse":29,"dh":"ויעל לקראת ישראל אביו גושנה.","text":"י\"מ כי זו הוא גושן האמורה בספר יהושע ולפי שארץ ישראל גבוהה מכל ארצות אמר ויעל. ויותר נכון לפרש כי הוא מארץ מצרים כפשטיה דקרא והיתה גבוהה מארץ מצרים ומה שאמר כשיצא מאביו אעלה ואגידה לפרעה אולי כשראה ליעקב ירד ממרכבתו ועל כן אמר אעלה על המרכבה ואגידה לפרעה. או יהיה פירושו אלך למצרים ואעלה ואגידה לפרעה כי בית פרעה היה בגובה מצרים כדרך המלכים שבונים בירניהם בגובה העיר או שמא ארץ מצרים גבוהה מארץ גושן ופי' ויעל לקראת ישראל ויעל על מרכבתו והלך לקראתו ובא להודיע כשם שאסר מרכבתו לכבודו כך עלה על המרכב' לבדו בלא סיוע לכבו' אביו ולא כדרך מלכי' שעבדיה' מכתפי' אותם להעלות' על מרכבת':","complete":true},{"workId":"Sforno_on_Genesis","unitId":"Sforno_on_Genesis.47.6","commentator":"ספורנו","sourceLine":"ספורנו · Vocalized Edition · נחלת הכלל · ספריא","chapter":47,"verse":12,"dh":"לֶחֶם לְפִי הַטָּף.","text":"אַף עַל פִּי שֶׁהָיָה בְּיָדוֹ לְהַרְבּוֹת לָהֶם מָזוֹן, נָתַן לָהֶם בְּמִדָּה מַסְפֶּקֶת, כְּאָמְרוּ רַבּוֹתֵינוּ זִכְרוֹנָם לִבְרָכָה (תַּעֲנִית יא.) בִּזְמַן שֶׁהַצִּבּוּר שָׁרוּי בְּצַעַר אַל יֹאמַר אָדָם אֵלֵךְ לְבֵיתִי וְאֹכַל וְאֶשְׁתֶּה וְשָׁלוֹם עָלֵיךְ נַפְשִׁי:","complete":true}],"vayechi":[{"workId":"Haamek_Davar_on_Genesis","unitId":"Haamek_Davar_on_Genesis.47.53","commentator":"העמק דבר","sourceLine":"העמק דבר · ספר תורת אלוהים, וילנא 1879 · נחלת הכלל · ספריא","chapter":47,"verse":28,"dh":"ויהי ימי יעקב שני חייו.","text":"אין הלשון מדוקדק. והכי מיבעי. ויהי ימי שני חיי יעקב. אלא משמעות ימי כאן חליפות הזמנים שנשתנה הרבה על יעקב ונתהפך מטובה לרעה ומרעה לטובה כ״פ. וכך משמעות המקרא ובימי אקרא היינו בחליפות הזמנים עלי. וע׳ בס׳ דברים ל״ג כ״ה עה״פ וכימיך דבאך. וסיפר הכתוב שכל חליפות הזמנים הי׳ בשני חייו וגו׳ בזה המשך עברו עליו כמה חליפות מה שעובר על אנשים אחרים רוב חליפות כאלה במשך הרבה שנים יותר מזה הסך של קמ״ז שנה והיינו משום שהיה בהשגחה ונעשה פתגם ההשגחה מהרה דבר בעתו:","complete":true},{"workId":"Or_HaChaim_on_Genesis","unitId":"Or_HaChaim_on_Genesis.48.18","commentator":"אור החיים","sourceLine":"אור החיים · Vocalized Edition · נחלת הכלל · ספריא","chapter":48,"verse":10,"dh":"וְעֵינֵי יִשְׂרָאֵל וְגוֹ׳.","text":"צָרִיךְ לָדַעַת לָמָּה כְּתִיב הוֹדָעָה זוֹ בְּמָקוֹם זֶה, וּמַה קֶשֶׁר וְשַׁיָּכוּת לְדָבָר זֶה עִם הַסָּמוּךְ לוֹ ״וַיִּשַּׁק לָהֶם וַיְחַבֵּק לָהֶם״. עוֹד צָרִיךְ לָדַעַת אָמְרוֹ לָהֶם, שֶׁהָיָה לוֹ לוֹמַר ״וַיִּשַּׁק אוֹתָם״. וְאוּלַי שֶׁשְּׁנֵי דִקְדּוּקִים אֵלּוּ כָּל אַחַת מְתָרֶצֶת חֲבֶרְתָּהּ, כִּי לְצַד שֶׁכָּבְדוּ עֵינָיו מִזּוֹקֶן הָיָה מְחַבֵּק שֶׁלֹּא בִּמְקוֹם הַחִבּוּק וּמְנַשֵּׁק שֶׁלֹּא בִּמְקוֹם הַנִּשּׁוּק, וְלָזֶה אָמַר ״לָהֶם״ וְלֹא אָמַר ״אוֹתָם״, וְהָבֵן:","complete":true},{"workId":"Rabbeinu_Bahya_on_Genesis","unitId":"Rabbeinu_Bahya_on_Genesis.48.16","commentator":"רבינו בחיי","sourceLine":"רבינו בחיי · Midrash Rabbeinu Bachya [ben Asher]. Warsaw, 1878 · נחלת הכלל · ספריא","chapter":48,"verse":19,"dh":"וגם הוא יגדל ואולם אחיו הקטן יגדל ממנו.","text":"הזכיר בהם גדול וקטן כלשון האמור בשני המאורות (בראשית א׳:ט״ז) את המאור הגדול ואת המאור הקטן. והזכיר וזרעו יהיה מלא הגוים על יהושע שהיה עתיד לצאת משבט אפרים שכל הגוים ראו האות שנעשה על ידו הוא שנאמר (יהושע י׳:י״ב-י״ג) שמש בגבעון דום וירח בעמק אילון. וכתיב (שם) וידום השמש וירח עמד עד יקום גוי אויביו הלא היא כתובה על ספר הישר, ואמרו ז\"ל זה ספר בראשית, שהוא ספר האבות אברהם יצחק ויעקב שנקראו ישרים וכתיב ביה (יהושע ו׳:כ״ז) ויהי ה' את יהושע ויהי שמעו בכל הארץ.","complete":true},{"workId":"Ramban_on_Genesis","unitId":"Ramban_on_Genesis.49.2","commentator":"רמב״ן","sourceLine":"רמב״ן · On Your Way · נחלת הכלל · ספריא","chapter":49,"verse":3,"dh":"ראובן בכורי אתה","text":"שיעור הפסוק הזה ראובן אתה בכורי וכחי וראשית אוני יתר שאתי ויתר עוזי וענינו אתה בכור כחי וראשית אוני בהיותי ביתרון שאת ומעלה כלשון הלא שאתו תבעת אתכם (איוב יג יא) משאתו יגורו אלים (שם מא יז) רוממות וגדולה ובהיותי יתרון עז למלחמה כמו ויתן עז למלכו (שמואל א ב י) ועזוז מלחמה (ישעיהו מב כה):","complete":true},{"workId":"Tur_HaArokh_on_Genesis","unitId":"Tur_HaArokh_on_Genesis.49.33","commentator":"טור הארוך","sourceLine":"טור הארוך · Perush al ha-Torah, Hanover, 1838 · נחלת הכלל · ספריא","chapter":49,"verse":21,"dh":"נפתלי אילה שלוחה.","text":"דרך המלכים לשלוח איילות זה לזה כי האיילות שנולדו בארץ מלך הצפון יגדלום בהיכלי מלך ארץ הנגב ויקשרו כתב הבשורה על קרני' ותשוב אל מעונה ויתבשרו בהם וזהו פי' אמרי שפר כלומר אילה שלוחה מבשרת בשורות טובות ודימה לזה נפתלי שארצו מלאה כל טוב וממנו תבא בשורה טובה לישראל:","complete":true},{"workId":"Kli_Yakar_on_Genesis","unitId":"Kli_Yakar_on_Genesis.49.23","commentator":"כלי יקר","sourceLine":"כלי יקר · Vocalized Edition · נחלת הכלל · ספריא","chapter":49,"verse":27,"dh":"בִּנְיָמִין זְאֵב יִטְרָף, בַּבֹּקֶר יֹאכַל עַד וְלָעֶרֶב יְחַלֵּק שָׁלָל.","text":"צָרִיךְ עִיּוּן, מַה זֶּה עִנְיַן מַרְאֵה הָעֶרֶב וְהַבֹּקֶר, וְלָמָּה קְרָאוֹ פַּעַם שָׁלָל וּפַעַם עַד, וְכָאן נֶאֱמַר לְשׁוֹן ״יֹאכַל״ וְאַחַר כָּךְ ״יְחַלֵּק״? וְזֶה, כִּי מֵהַיָּדוּעַ שֶׁכָּל דָּבָר שֶׁהָאָדָם שׁוֹאֵל כַּהוֹגֶן נִתָּן לוֹ בְּפָנִים מְאִירוֹת, דְּהַיְנוּ בַּבֹּקֶר, וְכָל דָּבָר שֶׁהָאָדָם שׁוֹאֵל שֶׁלֹּא כַּהוֹגֶן נִתָּן לוֹ בָּעֶרֶב בְּפָנִים חֲשׁוּכוֹת, כְּמוֹ שֶׁפֵּרֵשׁ רַשִׁ״י עַל פָּסוּק ״בְּתֵת ה׳ לָכֶם בָּעֶרֶב בָּשָׂר לֶאֱכֹל וְלֶחֶם בַּבֹּקֶר לִשְׂבֹּעַ״ (שמות טז ח).","complete":false}],"shemot":[{"workId":"Haamek_Davar_on_Exodus","unitId":"Haamek_Davar_on_Exodus.1.1","commentator":"העמק דבר","sourceLine":"העמק דבר · ספר תורת אלוהים, וילנא 1879 · נחלת הכלל · ספריא","chapter":1,"verse":1,"dh":"ואלה שמות בני ישראל הבאים מצרימה את יעקב.","text":"אם נפרש בני ישראל האומה הישראלית. כלשון ובני ישראל פרו וגו׳ וכמו בכה״ת. אין מדוקדק מה שמונה המקרא אח״ז ראובן שמעון וגו׳. ואם נפרש בני ישראל בנים שהוליד ישראל סבא. וכמו לשון המקרא (בראשית מ״ב ה׳) ויבאו בני ישראל לשבור וגו׳ אין מדוקדק לשון את יעקב. שהרי מדבר בו והכי מיבעי הבאים אתו מצרימה. ונראה לפי פשוטו דב״י היינו אומה הישראלית. ומה שמונה ראובן וגו׳ משמעו בית ראובן. בית שמעון. וכדכתיב תחלה איש וביתו באו. וע״ז מפרש דבתי הבנים האלו הן המה כלל ב״י הבאים מצרימה :","complete":true},{"workId":"Or_HaChaim_on_Exodus","unitId":"Or_HaChaim_on_Exodus.1.45","commentator":"אור החיים","sourceLine":"אור החיים · Vocalized Edition · נחלת הכלל · ספריא","chapter":1,"verse":18,"dh":"מַדּוּעַ וְגוֹ׳ וַתְּחַיֶּיןָ וְגוֹ׳.","text":"צָרִיךְ לְדַקְדֵּק מַה הוּא הַמַּעֲשֶׂה שֶׁעָשׂוּ, שֶׁעָלָיו הוּא אוֹמֵר מַדּוּעַ עֲשִׂיתֶן, וְאִם שֶׁלֹּא הֵמִיתוּ אֶת הַיְלָדִים, זֶה יִקָּרֵא שְׁלִילַת הַמַּעֲשֶׂה וְהָיָה צָרִיךְ לוֹמַר מַדּוּעַ לֹא עֲשִׂיתֶן. עוֹד צָרִיךְ לְדַקְדֵּק אָמְרוֹ וַתְּחַיֶּיןָ, וְאִם עַל סִפּוּק הַמָּזוֹן לַיְּלָדִים הוּא אוֹמֵר כְּמוֹ שֶׁפֵּרַשְׁנוּ בְּאָמְרוֹ ״וַתִּירֶאןָ הַמְיַלְּדוֹת וְגוֹ׳ וַתְּחַיֶּיןָ״ וְגוֹ׳, אִם לָזֶה נִתְכַּוֵּן מַה מַעֲנֶה בִּלְשׁוֹן הַמְיַלְּדוֹת עַל זֶה, וַהֲרֵי הֵן מוֹרְדוֹת בַּמֶּלֶךְ.","complete":true},{"workId":"Rabbeinu_Bahya_on_Exodus","unitId":"Rabbeinu_Bahya_on_Exodus.2.17","commentator":"רבינו בחיי","sourceLine":"רבינו בחיי · Midrash Rabbeinu Bachya [ben Asher]. Warsaw, 1878 · נחלת הכלל · ספריא","chapter":2,"verse":12,"dh":"ויפן כה וכה.","text":"ראה מה עשה לו בבית ומה עשה לו בשדה. וירא כי אין איש אין איש עתיד לעמוד ממנו שיתגייר. ויך את המצרי. ראוי היה משה מששת ימי בראשית לעשות המעשה הזה להרוג את המצרי כי כחו של מצרי הוא כחו של קין שהוא מצד הטומאה ומזה אמרו רז\"ל שחיטת נכרי נבלה ומטמאה במשא כי הטומאה מצד כחו והבן זה.","complete":true},{"workId":"Tur_HaArokh_on_Exodus","unitId":"Tur_HaArokh_on_Exodus.3.3","commentator":"טור הארוך","sourceLine":"טור הארוך · Perush al ha-Torah, Hanover, 1838 · נחלת הכלל · ספריא","chapter":3,"verse":2,"dh":"וירא מלאך ה'.","text":"תחלה אמר וירא מלאך ה' ואחר כך אמר וירא ה' כי סר לראות ויקרא אליו אלהים ועל כן אמר ר' אברהם כי האלהים הוא המלאך הנזכר כמו כי ראיתי אלהים פנים אל פנים אע\"ג דכתיב אלהי אביך כי ידבר השליח בשם השולח. וכתב הרמב\"ן ואינו נכון שמשה גדול הנבואה לא יסתיר פניו ממלאך וכתב הוא כי רבותינו אמרו בב\"ר שהוא מיכאל ר' יוסי הארוך בכל מקום שהיו רואין אותו היו אומרים שם רבינו הקדוש כך כל מקום שמיכאל נראה שם כבוד השכינה נתכוונו לומר מתחלה נראה אליו מיכאל ושם כבוד השכינה והוא לא ראה הכבוד כי לא הכין דעתו בנבואה וכאשר כיון לבו וסר לראות נתגלה אליו כבוד השכינה:","complete":true}],"vaera":[{"workId":"Tur_HaArokh_on_Exodus","unitId":"Tur_HaArokh_on_Exodus.6.2","commentator":"טור הארוך","sourceLine":"טור הארוך · Perush al ha-Torah, Hanover, 1838 · נחלת הכלל · ספריא","chapter":6,"verse":2,"dh":"וידבר אלהים וגו' וארא אל אברהם וגו' ושמי ה' לא נודעתי להם.","text":"פירש\"י לא הודעתי אין כתיב כאן אלא לא נודעתי פי' לא נודעתי להם במדה זו של אמיתית שלי שעלי' נקרא שמי ה' ורוצה לומר מדה אמיתית שלי דהיינו קיום הבטחה לא נודעתי להם בה שהרי עדיין לא קיימתי להם ההבטחה אע\"ג דעדיין לא הגיע זמן לקיים הבטחה מ\"מ עדיין לא נודע להם בקיום ההבטחה.","complete":false},{"workId":"Rabbeinu_Bahya_on_Exodus","unitId":"Rabbeinu_Bahya_on_Exodus.6.16","commentator":"רבינו בחיי","sourceLine":"רבינו בחיי · Midrash Rabbeinu Bachya [ben Asher]. Warsaw, 1878 · נחלת הכלל · ספריא","chapter":6,"verse":14,"dh":"אלה ראשי בית אבותם.","text":"לפי שהגיע קצן של ישראל להגאל ובאו עתה להבדל מתוך המצריים יחס אותם הכתוב והזכיר בהם אלה כדי לפסול את המצריים. והתחיל בראובן שהיה הבכור וייחס אותם עד לוי, והכונה בזה כדי שיזכיר שני הגואלים משה ואהרן שהם משבט לוי, ואלו התחיל אלה שמות בני לוי היה נראה שיהיה לוי בכור היחס ולכבוד משה עשה כן ולכך התחיל מראובן ומזכיר והולך עד לוי השלישי.","complete":true},{"workId":"Haamek_Davar_on_Exodus","unitId":"Haamek_Davar_on_Exodus.6.39","commentator":"העמק דבר","sourceLine":"העמק דבר · ספר תורת אלוהים, וילנא 1879 · נחלת הכלל · ספריא","chapter":6,"verse":29,"dh":"את כל אשר אני דובר.","text":"דיוק אני ולא אמר אשר הנני מדבר. או אשר אדבר. אלא מדקדק לומר אני בכל כבודי. וכיב״ז דקדקנו להלן כ״ג כ׳. והכוונה כמש״כ שהיו שני אופני דברות ה׳ עם משה. היינו הפרשה כאשר הוא והבאור שהוא במקום תורה שבע״פ. וביארנו בפסוק י״ג שהועיל משה בטענתו שיהא כל ההסברים ורבוי דברים הן לפרעה הן לישראל ע״י אהרן. עתה אמר ה׳ למשה שעכ״פ הדבור אשר אני בכל כבודי שהוא המאמר עצמו תדבר בעצמך לפרעה. ואהרן יבארם ויסבירם לפרעה. ולזה לא שייך טענת משה שהוא ערל שפתים. שהרי אז שכינה מדברת מתוך גרונו. והיו הדברים יוצאים מזוקקים. וזהו שהקדים ה׳ לומר אני ה׳. לומר אני בכבודי. וזהו כבודי שתהא אתה מדבר מה שאני דובר:","complete":true},{"workId":"Kli_Yakar_on_Exodus","unitId":"Kli_Yakar_on_Exodus.7.1","commentator":"כלי יקר","sourceLine":"כלי יקר · Vocalized Edition · נחלת הכלל · ספריא","chapter":7,"verse":9,"dh":"קַח אֶת מַטְּךָ וְהַשְׁלֵךְ לִפְנֵי פַרְעֹה יְהִי לְתַנִּין.","text":"כָּאן נֶאֱמַר שֶׁיִּקַּח מַטֵּה אַהֲרֹן וִיהִי לְתַנִּין, וּלְמַעְלָה פָּרָשַׁת שְׁמוֹת (שמות ד, ב) צִוָּה שֶׁיִּקַּח מֹשֶׁה מַטֵּה שֶׁלּוֹ וִיהִי לְנָחָשׁ, וְנֶחְלְקוּ הַמְפָרְשִׁים בָּזֶה, כִּי יֵשׁ אוֹמְרִים שֶׁתַּנִּין הַיְינוּ דָּג גָּדוֹל, כְּמוֹ שֶׁפֵּרַשׁ רַשִׁ״י עַל פָּסוּק ״הַתַּנִּינִם הַגְּדֹלִים״ (בראשית א, כא), וְיֵשׁ אוֹמְרִים שֶׁתַּנִּין הַיְינוּ נָחָשׁ, וְכֵן פֵּרַשׁ רַשִׁ״י כָּאן.","complete":true},{"workId":"Or_HaChaim_on_Exodus","unitId":"Or_HaChaim_on_Exodus.8.20","commentator":"אור החיים","sourceLine":"אור החיים · Vocalized Edition · נחלת הכלל · ספריא","chapter":8,"verse":19,"dh":"וְשַׂמְתִּי פְדֻת.","text":"פֵּרוּשׁ, מִלְּבַד שֶׁלֹּא יִכָּנְסוּ לְאֶרֶץ גּוֹשֶׁן, עוֹד יַעֲשֶׂה פְדוּת אֲפִלּוּ לְיִשְׂרָאֵל שֶׁהֵם חוּץ מֵאֶרֶץ גּוֹשֶׁן, לְבַל קְרוֹב לָהֶם הֶעָרוֹב. וְדִקְדֵּק לוֹמַר בֵּין עַמִּי וּבֵין עַמֶּךָ, פֵּרוּשׁ, כְּשֶׁיִּהְיוּ עַמִּי וְעַמְּךָ עוֹמְדִים בְּשָׁוֶה, יַעֲשֶׂה ה׳ פְּדוּת לָזֶה מִבֵּין זֶה, וְלַנָּכְרִי יַשִּׁיךְ וּלְאִישׁ יִשְׂרָאֵל לֹא יַשִּׁיךְ.","complete":true},{"workId":"Rashbam_on_Exodus","unitId":"Rashbam_on_Exodus.9.7","commentator":"רשב״ם","sourceLine":"רשב״ם · Rashbam on Torah -- Daat · נחלת הכלל · ספריא","chapter":9,"verse":17,"dh":null,"text":"מסתלל - מתפעל מן (ישעיה סב) סולו סולו המסילה כובש אותם לעבדים, כדכתיב: (ירמיה ל\"ד) ויכבשם לעבדים ולשפחות. ולהודיעך שיטת המתפעלים כי כל תיבות המתפעלים באה תוספת תי\"ו בראש חוץ מאותן שאוציא מן הכלל לבסוף. מן אמר יאמר: (תהלים צד) יתאמרו כל פועלי און. יתברך. יתגדל. (יחזקאל ל\"ח) והתגדלתי, והתקדשתי יתהלל המתהלל. יתווכח. ויתחבא. לשוא תתיפי (ישעיהו כ״ח:כ׳) והמסכה צרה כהתכנס. יתלכדו. ויתמודד. מתנשא ויתלקטו התעללתי. מתפלל מתרושש והון רב. הרי לך כל האלפ\"א בית\"א תי\"ו בראשם חוץ משבעת אותיות אלו דז\"ט ס\"ץ ש\"ת. השי\"ן והסמ\"ך באה התי\"ו אחריהם במתפעל שלהם: מן סל מסתולל. מן שר תשתרר עלינו.","complete":false}],"bo":[{"workId":"Tur_HaArokh_on_Exodus","unitId":"Tur_HaArokh_on_Exodus.10.3","commentator":"טור הארוך","sourceLine":"טור הארוך · Perush al ha-Torah, Hanover, 1838 · נחלת הכלל · ספריא","chapter":10,"verse":2,"dh":"ולמען תספר.","text":"דבר למשה בשביל כל ישראל פי' תספר אתה וכל ישראל והזכיר כובד לב עבדיו בשביל שכתוב למעלה ויכבד לבו הוא ועבדיו ובזה המעמד הודיע הקב\"ה למשה מכת הארבה ושיתרה בה לפרעה כי למה אמר לו בא אל פרעה אם לא שיאמר לו כלום ולא סיפר הכתוב אלא דברי משה לפרעה וקיצר בדיבור השם למשה וכן דרך המקראות פעמים מקצר בזה ופעמים בזה. ובמדרש אלה שמות רבה דורש שהודיעו ברמז מדכתיב למען תספר באזני בנך ובן בנך זאת מכת הארבה כמה דתימא עלי' לבניכם ספרו ובניכם לבניהם:","complete":true},{"workId":"Haamek_Davar_on_Exodus","unitId":"Haamek_Davar_on_Exodus.10.22","commentator":"העמק דבר","sourceLine":"העמק דבר · ספר תורת אלוהים, וילנא 1879 · נחלת הכלל · ספריא","chapter":10,"verse":12,"dh":"את כל אשר השאיר הברד.","text":"אינו עשב הארץ שלפניו דא״כ הכי מיבעי את כל עשב הארץ אשר השאיר הברד כמו להלן ואת כל פרי העץ אשר הותיר הברד. ותו הרי היה עשב הארץ שצמחו אחרי הברד כמו אילנות שצמחו אח״כ כמש״כ לעיל ה׳ את כל העץ הצומח לכם מן השדה. אלא דבר בפ״ע הוא שיאכל גם את כל אשר השאיר הברד היינו החטה והכסמת. וע״ע להלן ט״ו בדיוק לשון המקרא:","complete":true},{"workId":"Kli_Yakar_on_Exodus","unitId":"Kli_Yakar_on_Exodus.10.18","commentator":"כלי יקר","sourceLine":"כלי יקר · Vocalized Edition · נחלת הכלל · ספריא","chapter":10,"verse":24,"dh":"וַיִּקְרָא פַרְעֹה אֶל מֹשֶׁה.","text":"אַף עַל פִּי שֶׁבְּכָל הַמַּכּוֹת קָרָא לְמֹשֶׁה וּלְאַהֲרֹן, מִכָּל מָקוֹם לֹא קָרָא עַכְשָׁיו כִּי אִם אֶת מֹשֶׁה, כִּי יָדַע שֶׁכַּאֲשֶׁר נוֹלַד מֹשֶׁה נִתְמַלֵּא כָּל הַבַּיִת אוֹרָה, וְחָשַׁב שֶׁאוּלַי זֶה הָיָה סִימָן עַל הֶעָתִיד שֶׁיִּהְיֶה לוֹ סְגֻלָּה לְהָבִיא הָאוֹרָה בִּמְקוֹם הַחֹשֶׁךְ.","complete":true},{"workId":"Rashbam_on_Exodus","unitId":"Rashbam_on_Exodus.11.4","commentator":"רשב״ם","sourceLine":"רשב״ם · Rashbam on Torah -- Daat · נחלת הכלל · ספריא","chapter":11,"verse":4,"dh":null,"text":"ויאמר משה לפרעה כה אמר ה' כחצות - כחצות מן חצה כמו כעשות מן עשה. כעלות המנחה מן עלה. כלומר: כשיגיע זמן יציאת ישראל כשיחצה הלילה אני יוצא בתוך מצרים. ובשעת מעשה ראוי לכתוב ויהי בחצי הלילה בבי\"ת זהו לפי פשוטו. כי כשאמר למשה לפני הזמן של מכת בכורות אז ראוי לומר כחצות כלומר: כשיגיע אותו זמן שיחצה הלילה.","complete":true},{"workId":"Or_HaChaim_on_Exodus","unitId":"Or_HaChaim_on_Exodus.12.38","commentator":"אור החיים","sourceLine":"אור החיים · Vocalized Edition · נחלת הכלל · ספריא","chapter":12,"verse":21,"dh":"וַיִּקְרָא מֹשֶׁה לְכָל זִקְנֵי יִשְׂרָאֵל.","text":"וַהֲגַם כִּי ה׳ אָמַר אֵלָיו ״דַּבְּרוּ אֶל כָּל עֲדַת יִשְׂרָאֵל״, יִהְיֶה פֵּרוּשׁוֹ כְּמַאֲמַר (ויקרא ד:יג) ״וְאִם כָּל עֲדַת יִשְׂרָאֵל יִשְׁגּוּ״ שֶׁיֵּאָמֵר עַל הַזְּקֵנִים כְּמוֹ שֶׁמְּפֹרָשׁ בִּמְקוֹמוֹ (תורת כהנים), ״וַיֹּאמֶר אֲלֵיהֶם״ יְכַוֵּן לִשְׁאָר הָעָם, כְּמִשְׁפַּט כָּל מִצְווֹת ה׳ לְיִשְׂרָאֵל שֶׁהָיוּ מִפִּי מֹשֶׁה (עירובין נד,א).","complete":true},{"workId":"Rabbeinu_Bahya_on_Exodus","unitId":"Rabbeinu_Bahya_on_Exodus.12.35","commentator":"רבינו בחיי","sourceLine":"רבינו בחיי · Midrash Rabbeinu Bachya [ben Asher]. Warsaw, 1878 · נחלת הכלל · ספריא","chapter":12,"verse":29,"dh":"וה' הכה כל בכור בארץ מצרים.","text":"שלם להם הקב\"ה בי' מכות הללו מדה כנגד מדה וע\"כ היו המכות דצ\"ך עד\"ש באח\"ב. עקר בטחונם היה היאור שהיה משקה שדותיהם וכרמיהם ושעבדו לישראל לשאוב את מימיהם לפיכך היו מימי היאור לדם. והיו מעוררים ישראל משנתם ומקימים אותם ממטותם בלילה לעבוד עבודת פרך והיו מקרקרין מתוך הסבל מכאב לב הביא עליהם צפרדעים בחדריהם ועל מטותיהם שנאמר ובחדר משכבך ועל מטתך, והיו הצפרדעים מקרקרין במעיהם. מנעו מישראל מרחצאות והיו הכנים מצערים אותם לפיכך הרחישה אדמתם כנים. היו מצוים להם צודו לנו חיות כגון אריות ודובים לכך הביא עליהם ערוב. היו משתעבדים בהם לרעות מקניהם לכך שלח בהם דבר היו משתעבדים בהם להחם להם חמין הביא עליהם שחין.","complete":false}],"beshalach":[{"workId":"Tur_HaArokh_on_Exodus","unitId":"Tur_HaArokh_on_Exodus.13.12","commentator":"טור הארוך","sourceLine":"טור הארוך · Perush al ha-Torah, Hanover, 1838 · נחלת הכלל · ספריא","chapter":13,"verse":17,"dh":"ויהי בשלח וגו' כי קרוב הוא.","text":"פירש\"י ונוח לשוב למצרי' ויתנו לב לשוב אם יראו מלחמ'. וכתב הרמב\"ן א\"כ היה לו לפסוק להקדים כי אמר אלהים ולכתוב ולא נחם אלהים דרך ארץ פלשתים כי אמר אלהים כי קרוב הוא לכן פי' כי קרוב הוא וטוב לנחותם הדרך ההוא כי אמר אלהים פן ינחם וגומ' ולפי זה כי קרוב פי' אף כי קרוב הוא כמו רפאה נפשי כי חטאתי לך. וי\"מ כי קרובה היא השבועה שנשבע אברהם לאבימלך אם תשקר לי ולניני ולנכדי. וי\"מ כי קרוב הוא שלא הגיע עדיין מה שנאמר ודור רביעי ישובו הנה. וי\"מ כי קרוב הוא שפלשתים קרוב למצרים שנאמר ומצרים ילד את לודים ואת ענמים וגומר וכיון שיראו פלשתים שיברחו ממצרים יעזרו פלשתים ויחזירום.","complete":false},{"workId":"Or_HaChaim_on_Exodus","unitId":"Or_HaChaim_on_Exodus.14.13","commentator":"אור החיים","sourceLine":"אור החיים · Vocalized Edition · נחלת הכלל · ספריא","chapter":14,"verse":10,"dh":"וּפַרְעֹה הִקְרִיב וְגוֹ׳ וְהִנֵּה מִצְרַיִם וְגוֹ׳.","text":"צָרִיךְ לְדַקְדֵּק לָמָּה הֻצְרַךְ לוֹמַר זֶה וְלֹא הִסְפִּיק מַה שֶׁקָּדַם לוֹמַר ״וַיַּשִּׂיגוּ אוֹתָם״ וְגוֹ׳? וְאָמַר עוֹד ״וְהִנֵּה מִצְרַיִם נוֹסֵעַ״ וְגוֹ׳, גַּם לָמָּה הִתְחִיל הַסִּבָּה בְּפַרְעֹה וְגָמַר אוֹמֶר בְּמִצְרַיִם, דִּכְתִיב ״וְהִנֵּה מִצְרַיִם״, שֶׁהָיָה לוֹ לוֹמַר ״וְהִנֵּה פַּרְעֹה״ וְגוֹ׳? עוֹד צָרִיךְ לְדַקְדֵּק אָמְרוֹ נוֹסֵעַ לְשׁוֹן יָחִיד וְגוֹ׳ עַל מִצְרַיִם שֶׁהֵם רַבִּים.","complete":true},{"workId":"Kli_Yakar_on_Exodus","unitId":"Kli_Yakar_on_Exodus.14.5","commentator":"כלי יקר","sourceLine":"כלי יקר · Vocalized Edition · נחלת הכלל · ספריא","chapter":14,"verse":16,"dh":"וְאַתָּה הָרֵם אֶת מַטְּךָ וּנְטֵה אֶת יָדְךָ עַל הַיָּם.","text":"בַּמִּדְרָשׁ (שמות רבה כא, ט) אָמְרוּ, לְפִי שֶׁהָיוּ אוֹמְרִים הַמִּצְרִים ״לוּלֵא הַמַּטֶּה לֹא הָיָה יָכוֹל לַעֲשׂוֹת אֶת כָּל הַנִּסִּים״, עַל כֵּן אָמַר הַקָּדוֹשׁ בָּרוּךְ הוּא ״סַלֵּק אֶת מַטְּךָ וּנְטֵה אֶת יָדְךָ״, כִּי ״הָרֵם״ לְשׁוֹן סִלּוּק הוּא. וְהִנְנִי נוֹתֵן טַעַם בַּדָּבָר לָמָּה דַּוְקָא בִּקְרִיעַת יַם סוּף צִוָּה הַקָּדוֹשׁ בָּרוּךְ הוּא לְהָסִיר הַמַּטֶּה, וְזֶה לְפִי שֶׁרָצָה הַקָּדוֹשׁ בָּרוּךְ הוּא שֶׁיַּעֲשֶׂה מֹשֶׁה לְמַטָּה דּוּגְמָא אֶל כָּל דָּבָר הַנַּעֲשֶׂה לְמַעְלָה.","complete":false},{"workId":"Sforno_on_Exodus","unitId":"Sforno_on_Exodus.14.33","commentator":"ספורנו","sourceLine":"ספורנו · Vocalized Edition · נחלת הכלל · ספריא","chapter":14,"verse":27,"dh":"וּמִצְרַיִם נָסִים לִקְרָאתוֹ.","text":"שֶׁמִּתְּחִלַּת אַשְׁמוֹרֶת הַבֹּקֶר יַד ה' הָיְתָה בָם לְהֻמָּם, וְאָז אָמְרוּ אָנוּסָה וְנָסוּ עַד פְּנוֹת הַבֹּקֶר דֶּרֶךְ הַבְּקִיעָה. וּבְעֵת פְּנוֹת בֹּקֶר שָׁב הַיָּם לְאֵיתָנוֹ לָשֵׂאת גַּלָּיו בִּמְקוֹם הַבְּקִיעָה, אֲשֶׁר הִגִּיעוּ שָׁם מִצְרַיִם בְּאוֹתָהּ שָׁעָה, וְנִמְצְאוּ נָסִים לִקְרַאת הַיָּם.","complete":true},{"workId":"Haamek_Davar_on_Exodus","unitId":"Haamek_Davar_on_Exodus.15.57","commentator":"העמק דבר","sourceLine":"העמק דבר · ספר תורת אלוהים, וילנא 1879 · נחלת הכלל · ספריא","chapter":15,"verse":27,"dh":"ושם שתים עשרה וגו׳.","text":"הודיע הכתוב זה הענין שהכין הקב״ה תחלה אותו מקום כדתניא במכילתא והובא ברמב״ן ר״א המודעי א׳ כיון שברא הקב״ה את עולמו ברא י״ב מבועין נגד י״ב שבטים ושבעים תמרים נגד שבעים זקנים ומה ת״ל ויחנו שם על המים מלמד שהיו עסוקים בדברי תורה שניתן להם במרה. ובלי ספק שבא לכונה דוקא בזה המקום אחר עסק שהיה במרה. ללמדנו ענין שנוגע לדבר שניתן לדעת במרה. והיינו דכמו שהודיע משה אשר זהו דרכה ש״ת להסתפק בצמצום. אבל זה אינו אלא בתחלת בואו לכח התורה המכונה דרכה ש״ת. אבל אחר שזכה והשיג מעלת התורה זוכה להתפרנס בריוח ובדברים המרחיבים דעת להוסיף לקח בתורה.","complete":false},{"workId":"Rabbeinu_Bahya_on_Exodus","unitId":"Rabbeinu_Bahya_on_Exodus.16.23","commentator":"רבינו בחיי","sourceLine":"רבינו בחיי · Midrash Rabbeinu Bachya [ben Asher]. Warsaw, 1878 · נחלת הכלל · ספריא","chapter":16,"verse":13,"dh":"ויהי בערב ותעל השלו וגו', ובבקר היתה שכבת הטל.","text":"השלו והמן התחילו לבא באחד בשבת ועמד להם השלו ארבעים שנה כשם שעמד המן ומה שכתוב ובני ישראל אכלו את המן ארבעים שנה הוא הדין בשלו שאכלו אותו ארבעים שנה זה בא ביום וזה בא בלילה, אבל מפני שהיה הפלא גדול במן יותר מאד שנוצרה להם יצירה חדשה בשמים לכך הזכיר הפלא הזה לבדו כי עמד להם ארבעים שנה אבל השלו שהיה בא להם כאלו בענין הטבע והמקרה כענין הרוח כענין שבאר במקום אחר (במדבר י״א:ל״א) ורוח נסע מאת ה' ויגז שלוים מן הים, לא חשש להזכירו.","complete":true}],"yitro":[{"workId":"Kli_Yakar_on_Exodus","unitId":"Kli_Yakar_on_Exodus.18.1","commentator":"כלי יקר","sourceLine":"כלי יקר · Vocalized Edition · נחלת הכלל · ספריא","chapter":18,"verse":1,"dh":"וַיִּשְׁמַע יִתְרוֹ כֹהֵן מִדְיָן חֹתֵן מֹשֶׁה וְגוֹ׳.","text":"בַּיַּלְקוּט מַסִּיק: מַה שְּׁמוּעָה שָׁמַע וּבָא? רַבִּי יְהוֹשֻׁעַ אוֹמֵר: מִלְחֶמֶת עֲמָלֵק שָׁמַע וּבָא. רַבִּי אֶלְעָזָר הַמּוֹדָעִי אוֹמֵר: מַתַּן תּוֹרָה שָׁמַע וּבָא. רַבִּי אֱלִיעֶזֶר אוֹמֵר: קְרִיעַת יַם סוּף שָׁמַע וּבָא.","complete":false},{"workId":"Or_HaChaim_on_Exodus","unitId":"Or_HaChaim_on_Exodus.18.26","commentator":"אור החיים","sourceLine":"אור החיים · Vocalized Edition · נחלת הכלל · ספריא","chapter":18,"verse":15,"dh":"כִּי יָבֹא אֵלַי הָעָם וְגוֹ׳.","text":"קָשֶׁה, מַה תְּשׁוּבָה זוֹ עוֹשָׂה, וַהֲלֹא רָאָה יִתְרוֹ כִּי בָא אֵלָיו הָעָם לִדְרֹשׁ, וְכַוָּנַת קֻשְׁיָתוֹ הוּא לָמָּה יִתְנַהֵג בְּמִנְהָג זֶה כִּי יֵשׁ טֹרַח לָעָם. וּדְבָרָיו בָּרוּר מִלֵּלוּ ״אַתָּה יוֹשֵׁב לְבַדֶּךָ״, פֵּרוּשׁ, וְאֵין שׁוֹפְטִים אֲחֵרִים לָדוּן הָעָם, וְלוּ יִהְיֶה שֶׁלֹּא הֵבִין מֹשֶׁה דְּבָרָיו, הָיָה לוֹ לִשְׁאֹל גְּזֵרַת הַדִּבּוּר, לֹא שֶׁיֹּאמַר לוֹ דְּבָרִים שֶׁעֲלֵיהֶם הוּא מַקְשֶׁה.","complete":true},{"workId":"Sforno_on_Exodus","unitId":"Sforno_on_Exodus.18.33","commentator":"ספורנו","sourceLine":"ספורנו · Vocalized Edition · נחלת הכלל · ספריא","chapter":18,"verse":25,"dh":"וַיִּבְחַר מֹשֶׁה אַנְשֵׁי חַיִל.","text":"אַחַר שֶׁבִּקֵּשׁ וְלֹא מָצָא אֲנָשִׁים שֶׁיִּהְיוּ בָּהֶם כָּל הַמַּעֲלוֹת שֶׁהִזְכִּיר יִתְרוֹ, בָּחַר בְּאַנְשֵׁי חַיִל בְּקִיאִים וַחֲרוּצִים לְבָרֵר וּלְלַבֵּן אֲמִתּוֹת דָּבָר וּלְהָבִיאוֹ אֶל תַּכְלִית, יוֹתֵר מִיִּרְאֵי אֱלֹהִים בִּלְתִּי אַנְשֵׁי חַיִל, כְּאָמְרָם זִכְרוֹנָם לִבְרָכָה (שבת סג.) \"אִם תַּלְמִיד חָכָם כְּנָחָשׁ, חֲגֹרֵהוּ עַל מָתְנֶיךָ, וְאִם עַם הָאָרֶץ הוּא חָסִיד, אַל תָּדוּר בִּשְׁכוּנָתוֹ\".","complete":true},{"workId":"Haamek_Davar_on_Exodus","unitId":"Haamek_Davar_on_Exodus.19.1","commentator":"העמק דבר","sourceLine":"העמק דבר · ספר תורת אלוהים, וילנא 1879 · נחלת הכלל · ספריא","chapter":19,"verse":1,"dh":"בחדש השלישי.","text":"כבר ביארו הראשונים טעם שנוי לשון כאן מכל המסעות. הוא משום שמתחלת י״מ היה היעוד לבא לתכלית היציאה שהוא ביאה להר האלהים לקבל התורה. מש״ה הודיע הכתוב דבחודש השלישי זכו לזה התכלית. ועדיין יש להבין אריכות הלשון בחודש השלישי וגו׳ ביום הזה. שהכונה בר״ח כדאיתא פר״ע. ויותר היה מובן הלשון בראש חודש השלישי לצאת בני ישראל מארץ מצרים באו מדבר סיני. אלא בא ללמדנו דשם חודש השלישי גרם להם לזה. והיינו דאיתא שם דרש ההוא גלילאה בריך רחמנא דיהיב לן אורייתא תליתאה בירחא תליתאה כו׳. העמיק הדרשן דיוק הכתוב דוקא בחודש השלישי הוא שגרם לזה. ומעתה ממילא מובן ביום הזה שהוא בר״ח.","complete":false},{"workId":"Rabbeinu_Bahya_on_Exodus","unitId":"Rabbeinu_Bahya_on_Exodus.19.13","commentator":"רבינו בחיי","sourceLine":"רבינו בחיי · Midrash Rabbeinu Bachya [ben Asher]. Warsaw, 1878 · נחלת הכלל · ספריא","chapter":19,"verse":8,"dh":"כל אשר דבר ה' נעשה.","text":"הודו וקבלו עליהם עול התורה והמצות ועשו כן ברצונם. ומה שדרשו רז\"ל כפה עליהם ההר כגיגית ואמר להם אם אתם מקבלים את התורה מוטב ואם לאו שם תהא קבורתכם על התורה שבעל פה היה שיש בה אזהרות ועונשים וכמה סייגים וגדרים אבל התורה שבכתב הכל הודו מדעתם בחפץ גדול בשמחה ובטוב לבב ולא הוצרכו כפיה אלא בתורה שבעל פה.","complete":true}],"mishpatim":[{"workId":"Or_HaChaim_on_Exodus","unitId":"Or_HaChaim_on_Exodus.21.1","commentator":"אור החיים","sourceLine":"אור החיים · Vocalized Edition · נחלת הכלל · ספריא","chapter":21,"verse":1,"dh":"וְאֵלֶּה הַמִּשְׁפָּטִים.","text":"צָרִיךְ לָדַעַת טַעַם אָמְרוֹ וְאֵלֶּה, וְהִנֵּה נֶחְלְקוּ בַּמְּכִילְתָּא רַבִּי יִשְׁמָעֵאל וְרַבִּי עֲקִיבָא. רַבִּי יִשְׁמָעֵאל אוֹמֵר: לוֹמַר לְךָ מָה עֶלְיוֹנִים מִסִּינַי אַף תַּחְתּוֹנִים מִסִּינַי, רַבִּי עֲקִיבָא אוֹמֵר: וְאֵלֶּה יָכוֹל שׁוֹנִין וְלֹא יוֹדְעִים, תַּלְמוּד לוֹמַר ״וְאֵלֶּה״ וְגוֹ׳, עָרְכָן לִפְנֵיהֶם כְּשֻׁלְחָן הֶעָרוּךְ, עַד כָּאן.","complete":false},{"workId":"Haamek_Davar_on_Exodus","unitId":"Haamek_Davar_on_Exodus.21.30","commentator":"העמק דבר","sourceLine":"העמק דבר · ספר תורת אלוהים, וילנא 1879 · נחלת הכלל · ספריא","chapter":21,"verse":20,"dh":"בשבט ומת תחת ידו נקם ינקם.","text":"לפי הקבלה שבא ללמדנו שהורג עבדו במיתת סייף כמו רוצח א״כ אינו מבואר דיוק הכתוב בשבט. וגם לשון נקם ינקם משמעו לפי הפשט עוד כונה לבד קבלת חז״ל. והיינו שאם הכהו בשבט ומת. אזי לבד עונש רציחה שחייב מיתה כקבלת חז״ל יש ע״ז עון אכזריות נוראה הרבה יותר מאלו הרגו בסייף וכדומה דבשבט הוציא נפשו ביסורים כמה שעות ע״כ נקום ינקם מן השמים. וע׳ בס׳ בראשית מ״ב כ״א:","complete":true},{"workId":"Rashbam_on_Exodus","unitId":"Rashbam_on_Exodus.22.9","commentator":"רשב״ם","sourceLine":"רשב״ם · Rashbam on Torah -- Daat · נחלת הכלל · ספריא","chapter":22,"verse":6,"dh":null,"text":"כי יתן איש אל רעהו כסף או כלים לשמור - בפרשה זו פוטר את השומר מגנבה ואבדה ובפרשה שניה מחייבו בגנבה ואבדה. ופירשו רבותינו: ראשונה בשומר חנם, שניה בשומר שכר. ולפי פשוטו של מקרא: פרשה ראשונה שכתוב בה: כי יתן איש אל רעהו כסף או כלים לשמר - מטלטלין הם ולשומרם בתוך ביתו כשאר חפציו נתנן לו, לפיכך אם נגנבו בביתו פטור, כי שמרן כשמירת חפציו. אבל פרשה שניה שכתוב בה: כי יתן איש אל רעהו חמור או שור או שה וכל בהמה לשמור - ודרך בהמות לרעות בשדה ודאי כשהפקידם על מנת לשומרם מגנבים הפקידם לו ואם נגנבו חייב.","complete":true},{"workId":"Rabbeinu_Bahya_on_Exodus","unitId":"Rabbeinu_Bahya_on_Exodus.22.26","commentator":"רבינו בחיי","sourceLine":"רבינו בחיי · Midrash Rabbeinu Bachya [ben Asher]. Warsaw, 1878 · נחלת הכלל · ספריא","chapter":22,"verse":27,"dh":"ונשיא בעמך.","text":"הוא המלך שהוא הנשיא על העם והזהיר הכתוב שאם יחייבנו המלך בדינו שלא יאור אותו. וכן הזהיר שלמה ע\"ה (קהלת י׳:כ׳) גם במדעך מלך אל תקלל ובחדרי משכבך אל תקלל עשיר כי עוף השמים יוליך את הקול, והקדים השופט שהוא חכם למלך, וכן אמרו ז\"ל בסדר המעלות חכם קודם למלך, ודרשו רז\"ל שהכתוב הזה אזהרה על ברכת השם ואפילו בכנוי, והזהיר תחלה על המלך העליון יתברך ואח\"כ על המלך המולך בארץ וכן אמר שלמה (משלי כ״ד:כ״א) ירא את ה' בני ומלך.","complete":true},{"workId":"Tur_HaArokh_on_Exodus","unitId":"Tur_HaArokh_on_Exodus.23.7","commentator":"טור הארוך","sourceLine":"טור הארוך · Perush al ha-Torah, Hanover, 1838 · נחלת הכלל · ספריא","chapter":23,"verse":20,"dh":"הנה אנכי שולח מלאך.","text":"פירש\"י כאן נתבשרו שעתידין לחטוא ושכינה אומרת לא אעלה בקרבך. אע\"פ שלא נתקיימה הגזרה הזאת כי משה בקש עליה רחמים ואמר אם אין פניך הולכים אל תעלנו מזה ונתרצה לו הקב\"ה ואמר לו גם את הדבר הזה אשר דברת אעשה מ\"מ לאחר מיתתו נתקיימה ששלח להם מלאך וזהו שאמר הכתוב ויהי בהיות יהושע ביריחו וישא עיניו וירא והנה איש עומד לנגדו ושאל לו יהושע מה אדוני מדבר אל עבדו ולא צוה אותו דבר שנגלה בעבורו רק אמר לו של נעלך ולא אמר לו למה בא אבל היתה המראה להודיעו כי מעתה יהיה מלאך שלוח לפניהם בצבא בבואם למלחמה וזהו שאמר לו עתה באתי אני הוא שבאתי בימי משה רבך ודחני ולא רצה שאלך עמו:","complete":true},{"workId":"Sforno_on_Exodus","unitId":"Sforno_on_Exodus.23.36","commentator":"ספורנו","sourceLine":"ספורנו · Vocalized Edition · נחלת הכלל · ספריא","chapter":23,"verse":26,"dh":"אֶת מִסְפַּר יָמֶיךָ אֲמַלֵּא.","text":"שֶׁתִּחְיוּ כְּמִדַּת הַשֶּׁמֶן אֲשֶׁר בְּנֵר אֱלֹהִים, וְהוּא הַלַּחוּת הַשָּׁרְשִׁי בַּתּוֹלָדָה. וְהֵפֶךְ זֶה יִקְרֶה עַל הָרֹב שֶׁיָּמוּת הָאָדָם קֹדֶם שֶׁיִּכְלֶה הַלַּחוּת הַשָּׁרְשִׁי בָּחֳלָאִים, יִקְרוּ מֵרֹעַ בְּחִירָה אוֹ מִצַּד הַמַּעֲרֶכֶת וְהַיְסוֹדוֹת. וְהִנֵּה בִּמְלֹאת לְאָדָם מִסְפַּר יָמָיו יִרְאֶה עַל הָרֹב בָּנִים לְבָנָיו וְיוּכַל לְלַמְּדָם, כַּאֲמָרוֹ (דברים ד:ט) \"וְהוֹדַעְתָּם לְבָנֶיךָ וְלִבְנֵי בָנֶיךָ\". וִיתֻקַּן בְּחַיֵּי הַזְּקֵנִים עִנְיְנֵי הַדּוֹרוֹת, כְּמוֹ שֶׁסִּפֵּר שֶׁקָּרָה בְּעִנְיַן לֵוִי, קְהָת וְעַמְרָם.","complete":true}],"terumah":[{"workId":"Sforno_on_Exodus","unitId":"Sforno_on_Exodus.25.1","commentator":"ספורנו","sourceLine":"ספורנו · Vocalized Edition · נחלת הכלל · ספריא","chapter":25,"verse":2,"dh":"דַּבֵּר אֶל בְּנֵי יִשְׂרָאֵל וְיִקְחוּ לִי תְּרוּמָה.","text":"אֱמֹר לְיִשְׂרָאֵל שֶׁחָפַצְתִּי שֶׁגַּבָּאִים יִגְבּוּ בַּעֲדִי תְּרוּמָה, וְכֵן עָשָׂה מֹשֶׁה בְּרִדְתּוֹ מִן הָהָר, כַּאֲמֹרוֹ \"וְאַחֲרֵי כֵן נִגְּשׁוּ כָּל בְּנֵי יִשְׂרָאֵל, וַיְצַוֵּם אֵת כָּל אֲשֶׁר דִּבֶּר ה' אִתּוֹ בְּהַר סִינָי\" (שמות לד:לב), וְאַחַר כָּךְ \"וַיֹּאמֶר מֹשֶׁה אֶל כָּל עֲדַת בְּנֵי יִשְׂרָאֵל\" (שמות לה:ד) שֶׁהֵם הַסַּנְהֶדְרִין, \"קְחוּ מֵאִתְּכֶם תְּרוּמָה\" (שמות לה:ה), וּבָזֶה צִוָּה לָהֶם שֶׁיִּגְבּוּ.","complete":false},{"workId":"Haamek_Davar_on_Exodus","unitId":"Haamek_Davar_on_Exodus.25.17","commentator":"העמק דבר","sourceLine":"העמק דבר · ספר תורת אלוהים, וילנא 1879 · נחלת הכלל · ספריא","chapter":25,"verse":18,"dh":"שנים.","text":"שני מיבעי. וכ״כ בפרשת ויקהל שני כרובים. והנה לפי הכלל ריש פרק שני שעירי. דבכל מקום דכתיב שני והוא מיותר דסתם רבים שנים והכא נמי סתם כרובים שנים. אלא שני שיהיו שוין זה כזה. ודאי הכי הוי. מיהו בדבר אחד לא היו שוין. דלחדא היה צורת זכר ולחדא צורת נקבה כדמוכח ביומא דנ״ד א׳. והיינו דכתיב שנים. דמשמע זוג כרובים א׳ זכר וא׳ נקבה (אח״כ מצאתי שרבינו בחיי כ״כ) ללמדנו דאהבה שבין ישראל לאביהם שבשמים שיבואר במקרא הסמוך הוא אהבת המשפיע והמושפע. שטבע היצירה מחייבם שכך הוטבע הבריאה שיהא המשפיע משתוקק להשפיע באהבה על המושפע ממנו. והמושפע עיניו תלויות תמיד להמשפיע. כך תשוקת של הקב״ה להשפיע תמיד ברכה באהבה על ישראל.","complete":false},{"workId":"Rabbeinu_Bahya_on_Exodus","unitId":"Rabbeinu_Bahya_on_Exodus.26.2","commentator":"רבינו בחיי","sourceLine":"רבינו בחיי · Midrash Rabbeinu Bachya [ben Asher]. Warsaw, 1878 · נחלת הכלל · ספריא","chapter":26,"verse":2,"dh":"אורך היריעה האחת שמונה ועשרים באמה.","text":"ידוע כי מעשה המשכן הכל ציורין כנגד מעשה שמים, ומפני שהמאורות קבועים בשמים וכל הפעולות באות משם בעולם השפל בעתים נגזרים לכך הזכיר לשון יריעה על שם הכתוב (תהילים ק״ד:ב׳) נוטה שמים כיריעה, והיו עשר יריעות כנגד עשר גלגלים, ואמר שמונה ועשרים כנגד שמונה ועשרים עתים שבספר קהלת ועליהם נאמר (דברי הימים א י״ב:ל״ג) ומבני יששכר יודעי בינה לעתים, ועליהם אמר דוד (תהילים ל״ד:ב׳) אברכה את ה' בכל עת והזכיר עוד (שם לא) בידך עתותי, או יהיה כנגד ימי יתרון הלבנה ופחיתותה,","complete":true},{"workId":"Tur_HaArokh_on_Exodus","unitId":"Tur_HaArokh_on_Exodus.26.1","commentator":"טור הארוך","sourceLine":"טור הארוך · Perush al ha-Torah, Hanover, 1838 · נחלת הכלל · ספריא","chapter":26,"verse":17,"dh":"שתי ידות לקרש האחד.","text":"כ' הרמב\"ן הברייתא שהביא רש\"י וחורץ הקרש מלמטה רביע מכאן ורביע מכאן והחריץ חציו באמצע אי אפשר לפרש הברייתא כמשמעה שאם הי' חורץ באמצע חצי הקרש שהוא ד' טפחים וחצי ורביע מכל צד א\"כ הי' חורץ כולו ולא נשאר ממנו יד ליכנס באדן אלא אין שעור לחריץ שלא נתנה תורה שיעור לרוחב עובי שפת האדן ולפיכך אמרו שהי' חורץ את הקרש רביע חריץ מכאן לכסות שפה אחת של האדן ורביע חורצו מצד האחר ובאמצעיתו של קרש הי' חורץ חציו של כל החריץ שבאותו הקרש לכסות עובי שפת שני האדנים.","complete":false},{"workId":"Or_HaChaim_on_Exodus","unitId":"Or_HaChaim_on_Exodus.26.10","commentator":"אור החיים","sourceLine":"אור החיים · Vocalized Edition · נחלת הכלל · ספריא","chapter":26,"verse":33,"dh":"וְנָתַתָּה אֶת הַפָּרֹכֶת וְגוֹ׳ וְהֵבֵאתָ שָׁמָּה.","text":"מִכָּאן מַשְׁמַע כִּי יַקְדִּים לִתְלוֹת הַפָּרֹכֶת בִּמְקוֹמוֹ, וְאַחַר כָּךְ יָבִיא הָאָרוֹן לִפְנִים מֵהַפָּרֹכֶת, וּבְפָרָשַׁת פְּקוּדֵי (שמות מ:ג) אָמַר ה׳ אֵלָיו ״וְשַׂמְתָּ שָׁם אֶת אֲרוֹן הָעֵדוּת וְסַכֹּתָ עַל הָאָרוֹן אֶת הַפָּרֹכֶת״, מַשְׁמַע כִּי יַקְדִּים הָאָרוֹן, וְכֵן עָשָׂה מֹשֶׁה שֶׁהִקְדִּים הָאָרוֹן תְּחִלָּה כַּמְבֹאָר שָׁם (שמות מ:כ).","complete":true},{"workId":"Kli_Yakar_on_Exodus","unitId":"Kli_Yakar_on_Exodus.27.1","commentator":"כלי יקר","sourceLine":"כלי יקר · Vocalized Edition · נחלת הכלל · ספריא","chapter":27,"verse":1,"dh":"וְעָשִׂיתָ אֶת הַמִּזְבֵּחַ עֲצֵי שִׁטִּים.","text":"בְּתַנְחוּמָא (י) מַסִּיק: הֵם עָשׂוּ שְׁטוּת וְהִכְעִיסוּנִי בָּעֵגֶל, יָבוֹאוּ עֲצֵי שִׁטִּים וִיכַפְּרוּ עַל שְׁטוּתָן. וְזֶה כִּי כָל חוֹטֵא נִכְנָס בּוֹ רוּחַ שְׁטוּת (סוטה ג.), כִּי מִטַּעַם זֶה שְׁלֹמֹה מְכַנֶּה אֶת הָרְשָׁעִים בִּכְסִילִים. וְעַל כֵּן נֶאֱמַר בַּמִּזְבֵּחַ ״נְבוּב לוּחֹת תַּעֲשֶׂה אֹתוֹ״ (שמות כז:ח), כִּי כָּל מִי שֶׁהוּא בְּלֹא דַּעַת וּתְבוּנָה נִקְרָא אִיש נָבוּב, שֶׁנֶּאֱמַר (איוב יא:יב) ״וְאִישׁ נָבוּב יִלָּבֵב״. פֵּרֵשׁ רַשִׁ״י שָׁם שֶׁכָּל מִי שֶׁהוּא חָלוּל וְנָבוּב בְּלֹא דַּעַת וּתְבוּנָה, צָרִיךְ שֶׁיִּקַּח לוֹ לֵב לָשׁוּב בִּתְשׁוּבָה.","complete":false}],"tetzaveh":[{"workId":"Haamek_Davar_on_Exodus","unitId":"Haamek_Davar_on_Exodus.27.21","commentator":"העמק דבר","sourceLine":"העמק דבר · ספר תורת אלוהים, וילנא 1879 · נחלת הכלל · ספריא","chapter":27,"verse":20,"dh":"ואתה תצוה וגו׳.","text":"כלל פרשה זו נפלאה. לבד לשון ואתה תצוה שכבר עמדו הראשונים ע״ז עוד עיקר הפ׳ אין כאן מקומה בתוך מעשה המשכן ויותר היה מקומה אחר מעשה המנורה עכ״פ. גם לשון ויקחו אליך. אינו מבואר מה זה. והרמב״ן כ׳ שהזהיר שיביאוהו לפניו ומשה יראה אם הוא זך וכתית כראוי. ואינו אלא פלא. וכי לא נאמנו פקידי המשכן ע״ז ומה יהיה אחרי מות משה. עוד יש להעיר על מאמר חז״ל בויקרא רבה ס״פ אמור פל״א עה״פ צו את בני ישראל ויקחו אליך שמן זית זך. הד״ד ראשך עליך ככרמל וגו׳ מלך אסור ברהטים. ומפרשי מלך זה משה כו׳. ומסיים אמר הקב״ה למשה. משה מלך עשיתיך ואין דרך מלך לעשות בעצמו צו לאחרים לעשות בשבילך.","complete":false},{"workId":"Rabbeinu_Bahya_on_Exodus","unitId":"Rabbeinu_Bahya_on_Exodus.28.13","commentator":"רבינו בחיי","sourceLine":"רבינו בחיי · Midrash Rabbeinu Bachya [ben Asher]. Warsaw, 1878 · נחלת הכלל · ספריא","chapter":28,"verse":15,"dh":"ועשית חשן משפט מעשה חושב.","text":"כך היה מעשה החושן אורג בגד מעשה חושב מן התכלת ומן הארגמן ותולעת שני ושש, והיה לוקח חוט א' של זהב ונותנו על ו' חוטין של תכלת וכופל הז' חוטין כאחד וכן היה עושה חוט א' של זהב עם ו' של ארגמן וחוט אחד של זהב עם ששה של פשתן, וזהו שכתוב תכלת וארגמן ותולעת שני ושש כ\"ח חוטין שכתוב (שמות לט) וירקעו את פחי הזהב וקצץ פתילם לעשות בתוך התכלת ובתוך הארגמן ובתוך תולעת השני ובתוך השש מלמד שחוט של זהב כפול בתוכם. ארכו של חושן שתי זרתות ורחבו זרת וכופלו לשנים נמצא זרת על זרת מרובע וקבועים בו ארבעה טורים אבן וכל אבן ואבן היה מרובע, ומפתח שמות י\"ב שבטים על י\"ב אבנים, ראובן היה מפותח על אבן אודם, שמעון על פטדה, וכן כולם.","complete":false},{"workId":"Tur_HaArokh_on_Exodus","unitId":"Tur_HaArokh_on_Exodus.28.7","commentator":"טור הארוך","sourceLine":"טור הארוך · Perush al ha-Torah, Hanover, 1838 · נחלת הכלל · ספריא","chapter":28,"verse":31,"dh":"ועשית את מעיל האפוד.","text":"פירש\"י מעיל כעין חלוק והקשה הרמב\"ן מהא דכתיב והוא עוטה מעיל ולא שייך עיטוף בחלוק אלא הוא כסות מקיף הגוף כולו ולמטה עד רגלי האדם ואין לו בית יד כלל ובשאר מעילין יש לו בית צוואר כנגד כל הצואר תפור בו ואותו בית הצואר נקרא פי המעיל ובזה המעיל צוה הכתוב שיהי' ארוג עמו וכולו חלוק מלפניו עד למטה ומכניס ראשו בנקבי פיו ולפניו שתי כנפים מגלה בו ומכסה בו כרצונו והיינו דכתיב ויחזק בכנף מעילו אלמא יש לו כנפים:","complete":true},{"workId":"Or_HaChaim_on_Exodus","unitId":"Or_HaChaim_on_Exodus.29.1","commentator":"אור החיים","sourceLine":"אור החיים · Vocalized Edition · נחלת הכלל · ספריא","chapter":29,"verse":1,"dh":"וְזֶה הַדָּבָר אֲשֶׁר תַּעֲשֶׂה וְגוֹ׳.","text":"הַכַּוָּנָה לֶהֱיוֹת שֶׁקָּדַם אֵלָיו מְנִיעַת הַמַּעֲשֶׂה כְּמוֹ שֶׁפֵּרַשְׁתִּי (שמות כז:כ) שֶׁאֵין עָלָיו אֶלָּא מִצְוַת הַדִּבּוּר לָעוֹשִׂים, לָזֶה וְזֶה הַדָּבָר זֶה יָצָא מֵהַכְּלָל הַמֻּשְׁלָל וְיֵשׁ לוֹ לַעֲשׂוֹתוֹ לְהַקְרִיב קָרְבְּנוֹתָיו שִׁבְעָה יָמִים, וְאָמְרוֹ וְזֶה לְצַד שֶׁקָּדַם וְצִוָּה שֶׁיַּלְבִּישֶׁנּוּ לְאַהֲרֹן וּלְבָנָיו, וְגָמַר אוֹמֶר וְזֶה גַּם כֵּן תַּעֲשֶׂה. וְאִם לֹא אָמַר אֲשֶׁר תַּעֲשֶׂה אֶלָּא ״לְקַח פַּר״ וְגוֹ׳, יֵשׁ מָקוֹם לוֹמַר כִּי יְצַוֶּה לְאַהֲרֹן אוֹ לְבָנָיו לַעֲשׂוֹת, לָזֶה אָמַר ״אֲשֶׁר תַּעֲשֶׂה״ כִּי הוּא הָעוֹשֶׂה.","complete":false},{"workId":"Kli_Yakar_on_Exodus","unitId":"Kli_Yakar_on_Exodus.30.1","commentator":"כלי יקר","sourceLine":"כלי יקר · Vocalized Edition · נחלת הכלל · ספריא","chapter":30,"verse":1,"dh":"וְעָשִׂיתָ מִזְבֵּחַ מִקְטַר קְטֹרֶת.","text":"כְּפִי הַנִּרְאֶה שֶׁשְּׁנֵי מִזְבְּחוֹת אֵלּוּ נֶעֶרְכוּ שְׁנֵיהֶם לְכַפֵּר עַל הַנֶּפֶשׁ הַחוֹטֵאת, כִּי מִזְבַּח הַנְּחֹשֶׁת בָּא לְכַפֵּר עַל חֶלְקֵי הַחֹמֶר וְהַגּוּף הַנָּגוּף בְּאֶבֶן הַחֵטְא, וְעָלָיו מַקְרִיבִים הַבַּעֲלֵי חַיִּים הַבָּאִים תְּמוּרָתוֹ, כִּי יֵשׁ לָהֶם דִּמְיוֹן אֶל חֹמֶר הָאָדָם. וּתְמוּנַת הַמִּזְבֵּחַ יוֹכִיחַ, כִּי זֹאת קוֹמָתוֹ דָּמְתָה לְקוֹמַת אָדָם בֵּינוֹנִי שָׁלֹשׁ אַמּוֹת, וְכֵן הַבְּהֵמוֹת הַנִּקְרָבִים דּוֹמִים אֶל נֶפֶשׁ הַבַּהֲמִית שֶׁבָּאָדָם, נֶפֶשׁ תְּמוּרַת נֶפֶשׁ.","complete":false}],"ki-tisa":[{"workId":"Haamek_Davar_on_Exodus","unitId":"Haamek_Davar_on_Exodus.30.10","commentator":"העמק דבר","sourceLine":"העמק דבר · ספר תורת אלוהים, וילנא 1879 · נחלת הכלל · ספריא","chapter":30,"verse":12,"dh":"ונתנו איש כפר נפשו.","text":"לפי הנראה פי׳ ראשונים אם ימנו תהיה הנתינה כופר נפשו. ואם לא היה המנין לא היה הכופר. וקשה טובא א״כ מנלן עיקר דין מצות שקלים בכל שנה. אבל באמת אאל״כ דהנתינה שייך להמנין דבפ׳ זו כתיב שתי תרומות. תרומות אדנים. ותרומת הלשכה. תדע דפליגי במס׳ שקלים אם לוים חייבים בתה״ל. ומפרש בירושל׳ דפליגי בפי׳ הכתוב כל העבר על הפקודים. אי משמעו דעבר על ימא או על המנין וקשה הא בפי׳ כתיב בפסוק י״ד כל העובר על הפקודים מבן עשרים שנה ומעלה. אלא ודאי שתי תרומות כתיב כאן ופסוק י״ד מיירי בתרומת אדנים. אבל בתרומה ראשונה דלא כתיב הכי מש״ה מפרשי רבנן כל דעבר על ימא. ואחר שבברור משמעות הפ׳ הכי. קשה אי בשביל מנין שלא יהי׳ נגף תרי מתנות למ״ל.","complete":false},{"workId":"Rabbeinu_Bahya_on_Exodus","unitId":"Rabbeinu_Bahya_on_Exodus.31.23","commentator":"רבינו בחיי","sourceLine":"רבינו בחיי · Midrash Rabbeinu Bachya [ben Asher]. Warsaw, 1878 · נחלת הכלל · ספריא","chapter":31,"verse":18,"dh":"וכבר","text":"ידעת כי כל שם אלהים הנזכר במעשה בראשית היא התשובה, ומה שהזכיר אחרי כן (בראשית ב) בהבראם בה' בראם היא הה\"א האחרונה הזאת כי הה\"א ברא בכח התשובה, וכדי שלא תחשוב שהיא העיקר והסבה שאין למעלה ממנה על כן היא זעירא, ולפיכך סמך מיד ביום עשות ה' אלהים סמך העשיה לשם המיוחד שהוא העקר וכן הזכיר דוד ע\"ה (תהילים קמ״ה:ט׳) טוב ה' לכל ורחמיו על כל מעשיו, אמר זה על השם המיוחד ולכך דבר בנסתר ואח\"כ הזכיר יודוך ה' כל מעשיך אמר כן על מדת הדין ולכך דבר לנכח וזה טעם וחסידיך יברכוכה מלא בה\"א וסמיך ליה כבוד מלכותך כי שם י\"ה הוא מדת הדין כלשון (שמות ט״ו:ב׳) עזי וזמרת יה וכמו שהזכרתי שם.","complete":true},{"workId":"Rashbam_on_Exodus","unitId":"Rashbam_on_Exodus.33.9","commentator":"רשב״ם","sourceLine":"רשב״ם · Rashbam on Torah -- Daat · נחלת הכלל · ספריא","chapter":33,"verse":14,"dh":null,"text":"והניחותי לך - אלך עמך לכבוש את הארץ, עד שאניח לך מכל אויביך מסביב כדכתיב: עד אשר יניח ה' לאחיכם ככם. והיה בהניח ה' אלהיך לך מכל אויבך וגו'. והמפרש והניחותי לך - הנחת רוח אעשה, כמו שאעשה בקשתך, שטות הוא וכי כל דברים שהיה הקב\"ה מתרצה לבקשת משה יאמר לו והניחותי לך, והלא ייתור לשון הוא בלא צורך כלל ואינו לשון חכמה.","complete":true},{"workId":"Kli_Yakar_on_Exodus","unitId":"Kli_Yakar_on_Exodus.33.9","commentator":"כלי יקר","sourceLine":"כלי יקר · Vocalized Edition · נחלת הכלל · ספריא","chapter":33,"verse":17,"dh":"וַיֹּאמֶר ה׳ אֶל מֹשֶׁה גַּם אֶת הַדָּבָר הַזֶּה אֲשֶׁר דִּבַּרְתָּ אֶעֱשֶׂה.","text":"אַף עַל פִּי שֶׁכִּמְעַט הָיִיתָ מִתְיָאֵשׁ מִן יְעוּד ״יְדַעְתִּיךָ בְשֵׁם״, מִכָּל מָקוֹם אֲנִי חוֹזֵר מִן הַכַּעַס וּמַבְטִיחֲךָ גַּם הַדָּבָר הַגָּדוֹל הַזֶּה, ״וָאֵדָעֲךָ בְּשֵׁם״ בִּזְכוּת מְצִיאַת הַחֵן, אַף עַל פִּי שֶׁלֹּא בִּקַּשְׁתָּ מִצַּד מְצִיאַת הַחֵן כִּי אִם ״הוֹדִיעֵנִי נָא אֶת דְּרָכֶךָ״, מִכָּל מָקוֹם מֵאַחַר שֶׁיָּצָא מִפִּיךָ דְּבַר ״יְדַעְתִּיךָ בְשֵׁם״, אֶעֱשֶׂה גַּם אֶת הַדָּבָר הַזֶּה בַּעֲבוּר מְצִיאַת הַחֵן, וְאֵדָעֲךָ בְּשֵׁם כְּבָרִאשׁוֹנָה.","complete":true},{"workId":"Tur_HaArokh_on_Exodus","unitId":"Tur_HaArokh_on_Exodus.34.3","commentator":"טור הארוך","sourceLine":"טור הארוך · Perush al ha-Torah, Hanover, 1838 · נחלת הכלל · ספריא","chapter":34,"verse":3,"dh":"גם הצאן והבקר אל ירעו אל מול ההר ההוא.","text":"מנגד כי בראשונה לא הוזהרו רק שלא תגע בו יד אם בהמה אם איש ועדיין היו עומדין באזהרה ההיא כי הכבוד היה תמיד בהר עד שנתנו הלוחות האחרונות אלא החמיר עתה בשעת מתן לוחות האחרונות מבלוחות הראשונות והטעם מפני שבמעמד הראשונות היה בעבור כל ישראל וזה היה בעבור משה לבדו בזכותו ובתפלתו וגדול יהיה הכבוד הנגלה בהר האחרון מן הראשון:","complete":true},{"workId":"Or_HaChaim_on_Exodus","unitId":"Or_HaChaim_on_Exodus.34.8","commentator":"אור החיים","sourceLine":"אור החיים · Vocalized Edition · נחלת הכלל · ספריא","chapter":34,"verse":11,"dh":"שְׁמָר לְךָ.","text":"צָרִיךְ לָדַעַת מַה יִשְׁמֹר בָּזֶה, וְאִם יִשְׁמֹר הַדְּבָרִים כְּדִבְרֵי רַבִּי אַבְרָהָם אִבְּן עֶזְרָא, לֹא הָיָה צָרִיךְ לְהַזְהִירוֹ עַל מִצְוָה בִּפְרָטוּת מִכָּל מִצְוֹת הַתּוֹרָה, וּפְשִׁיטָא שֶׁלֹּא יִכְבּוֹשׁ הַנֶּאֱמַר לוֹ בִּנְבוּאָה. וְאוּלַי כִּי לְצַד שֶׁעָבְדוּ יִשְׂרָאֵל אֶת עֲבוֹדָה זָרָה, לָזֶה מִתְחַכֵּם ה׳ לְרַפֵּא שִׁבְרָם בְּמַה שֶׁיְּצוֹרְרוּ אֶת עוֹבְדֵי עֲבוֹדָה זָרָה וִיקַוּוּ לְאַבְּדָם וּלְהַרְחִיקָם בַּל קְרוֹב אֲלֵיהֶם, עַל יְדֵי זֶה יִתְכַּפֵּר עֲוֹנָם וְתִתְרַצֶּה תְּשׁוּבָתָם. וַהֲגַם שֶׁעֲדַיִן לֹא הִגִּיעוּ לָאָרֶץ, יוֹעִיל הַחֵפֶץ וְהָרָצוֹן בָּזֶה לְכַפָּרָה עַל הַדָּבָר.","complete":false}],"vayakhel":[{"workId":"Rabbeinu_Bahya_on_Exodus","unitId":"Rabbeinu_Bahya_on_Exodus.35.2","commentator":"רבינו בחיי","sourceLine":"רבינו בחיי · Midrash Rabbeinu Bachya [ben Asher]. Warsaw, 1878 · נחלת הכלל · ספריא","chapter":35,"verse":1,"dh":"שלמה","text":"המלך ע\"ה המשיל החכמה שהיא תענוג שכלי לדבש שהוא תענוג גופני וכן הוא תמיד נוהג ברוב דבריו בספר משלי לדבר ע\"י משלים כדי שיזהיר האדם שיוכיח שכלו לטבעו, לפי שהאדם כלול משני דברים שכל וטבע וא\"א לו שיוכיח שכלו לטבעו כי אם ע\"י משל מעין הדברים המורגשים אשר הטבע שקוע בהם, וידוע כי חלקי הנבראים השפלים ארבעה זה למעלה מזה והם הדומם והצומח והחי והמדבר, הדומם הם ההרים והגבעות ואין לחלק זה נפש כלל לא צומחת ולא נפש התנועה אף כי נפש שכלית. למעלה ממנו הצומח יש לו יתרון מעלה על הדומם לפי שיש בו נפש צומחת.","complete":false},{"workId":"Tur_HaArokh_on_Exodus","unitId":"Tur_HaArokh_on_Exodus.35.9","commentator":"טור הארוך","sourceLine":"טור הארוך · Perush al ha-Torah, Hanover, 1838 · נחלת הכלל · ספריא","chapter":35,"verse":23,"dh":"וכל איש אשר נמצא אתו תכלת וארגמן.","text":"כי לא ימצאו אלה רק למקצתו וחזר ואמר אשר נמצא אתו עצי שטים כי היו יותר מעטים שבידם עצי שטים. ואומר כל מרים תרומת כסף ונחשת כי לרוב אנשים הי' כסף ונחושת כמטבעות וכלים אבל לא הזכיר זה למעלה עם כלי הזהב לפי שהזכיר שם הנשים ואין להם כסף או נחשת רק זהב בתכשיטי' כאשר אמר נזמי הזהב אשר באזני נשיכם. ואמר וכל איש אשר הניף תנופת זהב כי לא היו רבים כמרימי כסף ונחושת ולא היתה הבאת הזהב מרובה כהבאת כסף ונחשת על כן זה תנופה וזה תרומה כי המביא זהב ינופף ידו לחשיבות הנדבה או הלוקחים יניפו הזהב להראותו לשבח המביא על נדבתו. ובפרשת אלה פקודי קורא זהב וגם הנחשת תנופה לפי שלא הזכיר שם כסף (תרומה.","complete":false},{"workId":"Or_HaChaim_on_Exodus","unitId":"Or_HaChaim_on_Exodus.36.6","commentator":"אור החיים","sourceLine":"אור החיים · Vocalized Edition · נחלת הכלל · ספריא","chapter":36,"verse":8,"dh":"וַיַּעֲשׂוּ כָל חֲכַם לֵב.","text":"פֵּרוּשׁ, הֲגַם שֶׁהָעוֹשִׂים רַבִּים הֵם, אַף עַל פִּי כֵן הָיְתָה הַמְּלָאכָה נַעֲשֵׂית כְּאִלּוּ עֲשָׂאָהּ אָדָם אֶחָד. וְהַכַּוָּנָה בָּזֶה, כִּי כְּשֶׁיַּעֲשׂוּ הַמְּלָאכָה רַבִּים, עַל כָּל פָּנִים יִשְׁתַּנֶּה תֹּאַר מְלֶאכֶת זֶה מִזֶּה, וְלֹא תִּדְמֶה לִמְלָאכָה שֶׁיַּעֲשֶׂנָּה כֻּלָּהּ אוּמָּן אֶחָד. וְהִשְׁמִיעָנוּ הַכָּתוּב כִּי מְלֶאכֶת הַמִּשְׁכָּן שְׁלֵמָה הָיְתָה גַּם בִּבְחִינָה זוֹ, כִּי הַנּוֹתֵן חָכְמָה בָּהֵמָּה הִשְׁוָה אוֹתָם בְּהִתְבּוֹנְנוּת הַחָכְמָה שָׁוָה, וְדוֹמִים כֻּלָּם לְאִישׁ אֶחָד.","complete":false},{"workId":"Haamek_Davar_on_Exodus","unitId":"Haamek_Davar_on_Exodus.37.6","commentator":"העמק דבר","sourceLine":"העמק דבר · ספר תורת אלוהים, וילנא 1879 · נחלת הכלל · ספריא","chapter":37,"verse":19,"dh":"בקנה אחד.","text":"תיבה זו הכתובה בשנוי מהכתוב בכל המקומות בקנה האחד. ממשיך את הדעת להשכיל על ענין הגביעים המשוקדים כפתור ופרח. והנה ראינו ברבה פ׳ מקץ דרבי טרפון בשעה שהיה אחד אומר לפניו דבר הגון בתורה היה אומר כפתור ופרח. ושיחת רבן של ישראל מלמדנו שהבין אשר בכפתורים ופרחים של המנורה רמוז חידושי תורה שיש בהם שכל טוב לעושיהם. ומש״ה אמר למי שחידש דבר טוב שהוא כו״פ שעל המנורה. וכבר נתבאר ר״פ תצוה שהמנורה בכלל מרומז להאיר על חכמת התורה בפלפולה ש״ת והחקירה והעיון. והנה ששה קני מנורה עם הנר האמצעי הן המה שבע חכמות חיצוניות הטפלים לתורה. ושהתורה צריכה להם להתפרש בכל פרטי שיעורין וכדומה המגיע לבאור התורה. וע״ז מצויר.","complete":false}],"pekudei":[{"workId":"Tur_HaArokh_on_Exodus","unitId":"Tur_HaArokh_on_Exodus.38.2","commentator":"טור הארוך","sourceLine":"טור הארוך · Perush al ha-Torah, Hanover, 1838 · נחלת הכלל · ספריא","chapter":38,"verse":21,"dh":"אלה פקודי המשכן משכן העדות.","text":"משכן סתם הוא היריעות התחתונות לכן אמר משכן העדות שכולל הכל ופי' המשכן שנעשה ללוחות העדות. וכתב הרמב\"ן רבים מפרשים שאלה פקודי חוזר על של מעלה פי' המשכן וכליו שהוא הבית והחצר פקודי עבודת הלוים שפקדם משה ביד איתמר ואין כלי הקודש הארון והשלחן והמנורה והמזבחות בכלל המשכן כי הם ביד אלעזר. ואין דעתי כן כי למה יזכיר פקודת איתמר ולא יזכיר פקודת אלעזר אלא אלה פקודי קאי על מה שמזכיר למטה ובא לומר כי כסף פקודי העדה מאת ככר שנעשה בו האדנים והווים לעמודים וציפוים וחשוקיהם ונחשת התנופה שהוא ע' ככר שעשה בו מזבח הנחשת והמכבר וכל כליו ואדנים ויתדות הכל נתן במספר במשקל ביד איתמר ולכך לא הזכיר כאן פקודת איתמר (אלעזר.","complete":false},{"workId":"Haamek_Davar_on_Exodus","unitId":"Haamek_Davar_on_Exodus.39.2","commentator":"העמק דבר","sourceLine":"העמק דבר · ספר תורת אלוהים, וילנא 1879 · נחלת הכלל · ספריא","chapter":39,"verse":2,"dh":"ויעש.","text":"באפוד וחשן ומעיל התחלת הפרשיות בלשון יחיד ואח״כ בל״ר. (זולת אבני שוהם וכתונת וציץ ויבואר שם) משום דכל התחלת המלאכה והסדר היה ע״י בצלאל. ונגמר ע״י שארי אומנים וכדי שלא לקפח שכר האומנים שהמה בעמלם עשו עיקר המלאכה. וגם כל דבר מצוה נקרא ע״ש הגומרה מש״ה כתיב להלן בל״ר. וע״ע להלן כ״א ול׳:","complete":true},{"workId":"Or_HaChaim_on_Exodus","unitId":"Or_HaChaim_on_Exodus.39.4","commentator":"אור החיים","sourceLine":"אור החיים · Vocalized Edition · נחלת הכלל · ספריא","chapter":39,"verse":24,"dh":"עַל שׁוּלֵי וְגוֹ׳.","text":"מִכָּאן אֲנִי מְדַיֵּק שֶׁהָאֱמֶת הוּא כְּהַסּוֹבְרִים שֶׁהַפַּעֲמוֹנִים הֵם בְּשׁוּרָה עִם הָרִמּוֹנִים וְלֹא בְתוֹכָם מַמָּשׁ, שֶׁהֲרֵי הִקְדִּים הַכָּתוּב נְתִינַת הָרִמּוֹנִים עַל שׁוּלֵי הַמְּעִיל, וְאַחַר כָּךְ אָמַר מַעֲשֵׂה הַפַּעֲמוֹנִים בִּפְנֵי עַצְמָן ״וַיִּתְּנוּ אוֹתָם תּוֹךְ הָרִמּוֹנִים״. וּמֵעַתָּה אִם הַפַּעֲמוֹן תּוֹךְ הָרִמּוֹן מַמָּשׁ, לָמָּה הֻצְרַךְ הַכָּתוּב לוֹמַר ״עַל שׁוּלֵי״ אַחַר שֶׁכְּבָר קָדַם וְאָמַר שֶׁהָרִמּוֹנִים הֵם עַל שׁוּלֵי הַמְּעִיל? זֶה בָּזֶה תָּלוּי.","complete":false},{"workId":"Kli_Yakar_on_Exodus","unitId":"Kli_Yakar_on_Exodus.40.1","commentator":"כלי יקר","sourceLine":"כלי יקר · Vocalized Edition · נחלת הכלל · ספריא","chapter":40,"verse":2,"dh":"בְּיוֹם הַחֹדֶשׁ הָרִאשׁוֹן בְּאֶחָד לַחֹדֶשׁ תָּקִים אֶת מִשְׁכַּן אֹהֶל מוֹעֵד.","text":"כְּתִיב בַּפָּרָשָׁה שְׁלֹשָׁה פְעָמִים לְשׁוֹן הֲקָמָה, א׳ ״תָּקִים אֶת הַמִּשְׁכָּן״, ב׳ ״הוּקַם הַמִּשְׁכָּן״, ג׳ ״וַיָּקֶם מֹשֶׁה״, וְאָמְרוּ רז״ל (ויקרא רבה נב ד) שֶׁהָיוּ יִשְׂרָאֵל וְכָל חַכְמֵי לֵב מְקִימִים אֶת הַמִּשְׁכָּן וְלֹא יָכְלוּ לַהֲקִימוֹ, אָמַר הַקָּדוֹשׁ בָּרוּךְ הוּא: עֲסוֹק אַתָּה בַּהֲקָמָתוֹ וְהוּא עוֹמֵד מֵאֵלָיו, שֶׁנֶּאֱמַר ״הוּקַם״ – מֵאֵלָיו מַשְׁמָע. וְיֵשׁ בָּזֶה רֶמֶז לְכָל הַמַּעֲשִׂים אֲשֶׁר הָאָדָם עוֹשֶׂה, כִּי קָצְרָה יַד הָאָדָם לְהַשְׁלִימָם מֵהַתְחֵל וְגָמוֹר, אֶלָּא הָאָדָם הוּא הַמַּתְחִיל וַה׳ יִגְמוֹר עַל יָדוֹ. וְכֵן אָמְרוּ רז״ל (קידושין ל:) כְּנֶגֶד הַיֵּצֶר הָרָע:","complete":false},{"workId":"Sforno_on_Exodus","unitId":"Sforno_on_Exodus.40.1","commentator":"ספורנו","sourceLine":"ספורנו · Vocalized Edition · נחלת הכלל · ספריא","chapter":40,"verse":18,"dh":"וַיָּקֶם מֹשֶׁה אֶת הַמִּשְׁכָּן.","text":"עֶשֶׂר הַיְרִיעוֹת מַעֲשֵׂה חוֹשֵׁב שֶׁנִּקְרְאוּ מִשְׁכָּן הוּקְמוּ קֹדֶם הֲקָמַת הַקְּרָשִׁים, אִם בִּידֵי אָדָם מַחֲזִיקִין בּוֹ, וְאִם עַל דֶּרֶךְ נֵס כְּדִבְרֵיהֶם זִכְרוֹנָם לִבְרָכָה, וְעַל זֶה הַסֵּדֶר נַעֲשָׂה וְהוּבָא אֶל מֹשֶׁה. כִּי אָמְנָם אוֹתָן עֶשֶׂר יְרִיעוֹת הֵן הָיוּ עִקַּר בִּנְיַן הַמִּשְׁכָּן, וּשְׁאָר הַנִּכְנָס בְּאוֹתוֹ הַבִּנְיָן וְהֵם הָאֲדָנִים וְהַקְּרָשִׁים וְהַבְּרִיחִים וְהָעַמּוּדִים וְהָאֹהֶל, הָיוּ לְהַעֲמִיד הַמִּשְׁכָּן וּלְכַסּוֹתוֹ.","complete":true}],"vayikra":[{"workId":"Tur_HaArokh_on_Leviticus","unitId":"Tur_HaArokh_on_Leviticus.1.1","commentator":"טור הארוך","sourceLine":"טור הארוך · Perush al ha-Torah, Hanover, 1838 · נחלת הכלל · ספריא","chapter":1,"verse":1,"dh":"ויקרא אל משה.","text":"כתב הרמב\"ן לאחר שסיים בענין אהל מועד וכבוד ד' מלא את המשכן צוהו בקרבנות ובשמירת המשכן שיהיו הקרבנות כפרה להם ולא יגרמו העוונות לסלוק השכינה וציום בכהנים שיתקדשו ויזהרו בטומאת מקדש וקדשיו ולא יהרסו לעלות אל ה' כמו שנאמר דבר אל אהרן ואל יבא בכל עת וגו' ואחר כן הגביל המשכן בהגבלת הר סיני בעת היות שם כבוד ה'.","complete":false},{"workId":"Haamek_Davar_on_Leviticus","unitId":"Haamek_Davar_on_Leviticus.1.24","commentator":"העמק דבר","sourceLine":"העמק דבר · ספר תורת אלוהים, וילנא 1879 · נחלת הכלל · ספריא","chapter":1,"verse":16,"dh":"והסיר את מראתו בנצתה.","text":"נחלקו רש״י ורמב״ן בפי׳ הא דתניא בת״כ אבא יוסי בן חנן אומר נוטל את הקרקבן עמה. רש״י ס״ל דמפרש נוצתה אוכל שכבר נאכל ונעשה צואה כדכתיב וכסית את צאתך ונו״ן נוצה הוא שמוש. ומוראה הוא הזפק שהמאכל שבו אינו נאכל אלא מאוס. ופרש״י הא דכתיב בירמיה כי נצו גם נעו שנעשה מנו״ן השמוש אות שרשית. ומשום שדבר מאוס עומד להוציא חוץ המשיל הנביא אותם לכך. וכן הפי׳ בירמיה מ״ח גבי מואב כי נצא תצא. שנמאסה מש״ה תצא. אבל הרמב״ן פי׳ דאבא יוסי ס״ל דבמוראה נכלל גם הקרקבן. ולא שהיא נוצתה. ונוצתה הוא כמשמעו בלשון משנה חולין פ״ג ניטל הנוצה:","complete":true},{"workId":"Ramban_on_Leviticus","unitId":"Ramban_on_Leviticus.3.1","commentator":"רמב״ן","sourceLine":"רמב״ן · On Your Way New · נחלת הכלל · ספריא","chapter":3,"verse":1,"dh":"ואם זבח שלמים קרבנו וגו' אם זכר אם נקבה","text":"הטעם בעולה שיהיה זכר ובשלמים שיהיו אם זכר אם נקבה ובחטאת שתהיה נקבה דבר ברור הוא כי העולה כשמה והשלמים מלשון וכל חפצי ישלים (ישעיהו מד כח) אבנים שלימות (דברים כז ו) והחטאת לכפר פניו במנחה ההולכת לפניו וכבר כתבתי זה (בראשית מו א) והאשם זכר בעבור כי החטאת בחייבי כריתות שתשוב הנפש אל האלהים אשר נתנה והאשם לא יבא על חיוב כרת וכאלו הוא לריח ניחוח כעולה ושעיר הנשיא בעבור כי הוא המולך אשר לו המשפט והלוחם מלחמות השם ועל חרבו יחיה כדרך שעירי עבודה זרה:","complete":true},{"workId":"Kli_Yakar_on_Leviticus","unitId":"Kli_Yakar_on_Leviticus.4.1","commentator":"כלי יקר","sourceLine":"כלי יקר · Vocalized Edition · נחלת הכלל · ספריא","chapter":4,"verse":2,"dh":"נֶפֶשׁ כִּי תֶחֱטָא.","text":"מָצִינוּ שְׁלֹשָׁה לְשׁוֹנוֹת בַּחוֹטְאִים: כִּי, אִם, אֲשֶׁר. בְּיָחִיד הַחוֹטֵא כְּתִיב ״נֶפֶשׁ כִּי תֶחֱטָא״, וּבְרַבִּים הַחוֹטְאִים נֶאֱמַר (ד יג) ״וְאִם כָּל עֲדַת יִשְׂרָאֵל יִשְׁגּוּ״, וּבְנָשִׂיא כְּתִיב (ד כב) ״אֲשֶׁר נָשִׂיא יֶחֱטָא״. וְאָמְרוּ הַמְפָרְשִׁים שֶׁלְּשׁוֹן ״כִּי״ מוֹרֶה יוֹתֵר עַל וַדָּאוּת מִן לְשׁוֹן אִם, וּלְשׁוֹן אֲשֶׁר מוֹרֶה יוֹתֵר עַל וַדָּאוּת מִן לְשׁוֹן כִּי. לְפִיכָךְ בְּחֵטְא הָרַבִּים שֶׁהוּא דָּבָר שֶׁאֵינוֹ מָצוּי שֶׁרַבִּים יַסְכִּימוּ עַל הַחֵטְא, לְכָךְ נֶאֱמַר ״אִם כָּל עֲדַת יִשְׂרָאֵל יִשְׁגּוּ״, שֶׁהוּא מוֹרֶה עַל הַסָּפֵק.","complete":false},{"workId":"Or_HaChaim_on_Leviticus","unitId":"Or_HaChaim_on_Leviticus.4.20","commentator":"אור החיים","sourceLine":"אור החיים · Vocalized Edition · נחלת הכלל · ספריא","chapter":4,"verse":27,"dh":"מֵעַם הָאָרֶץ.","text":"דָּרְשׁוּ רַזַ״ל (הוריות יא.) לְמַעֵט כֹּהֵן מָשִׁיחַ בְּשִׁגְגָתוֹ בְּלֹא הֶעְלֵם דָּבָר שֶׁלֹּא יָבִיא אֲפִלּוּ שְׂעִירָה. גַּם מ״ם שֶׁל ״מֵעַם״ אָמְרוּ לְמַעֵט נָשִׂיא בְּהֵיכָא שֶׁאָכַל חֲצִי זַיִת וְהוּא הֶדְיוֹט וַחֲצִי זַיִת וְהוּא מֶלֶךְ שֶׁאֵינוֹ מֵבִיא כִּשְׂבָּה. פֵּרוּשׁ, מִתְּחִלָּה דּוֹרֵשׁ ״עַם הָאָרֶץ״ שֶׁהוּא לְאַפּוֹקֵי הַגָּדוֹל וּמְיֻחָד שֶׁבָּהֶם שֶׁהוּא כֹּהֵן הַמָּשִׁיחַ, וּדְרָשָׁא זוֹ הָיְתָה נִדְרֶשֶׁת הֲגַם שֶׁהָיָה אוֹמֵר ״בְּעַם הָאָרֶץ״, וּמֵאָמְרוֹ ״מֵעַם״ חָזַר וְחִלֵּק גַּם חֵלֶק מֵהַהֶדְיוֹט, וּכְגוֹן הֶדְיוֹט שֶׁאָכַל חֲצִי זַיִת וְנִתְמַנָּה וְהִשְׁלִימוֹ, שֶׁאֵינוֹ מֵבִיא.","complete":true}],"tzav":[{"workId":"Kli_Yakar_on_Leviticus","unitId":"Kli_Yakar_on_Leviticus.6.1","commentator":"כלי יקר","sourceLine":"כלי יקר · Vocalized Edition · נחלת הכלל · ספריא","chapter":6,"verse":2,"dh":"צַו אֶת אַהֲרֹן וְאֶת בָּנָיו לֵאמֹר.","text":"אֵין צַו אֶלָּא זֵרוּז מִיָּד וּלְדוֹרוֹת. אָמַר רַבִּי שִׁמְעוֹן, בְּיוֹתֵר צָרִיךְ הַכָּתוּב לְזָרֵז בִּמְקוֹם שֶׁיֵּשׁ בּוֹ חֶסְרוֹן כִּיס. אֵין זֵרוּז כִּי אִם בִּמְקוֹם עַצְלָה, וּכְתִיב (משלי יט טו) ״עַצְלָה תַּפִּיל תַּרְדֵּמָה״, וּכְתִיב (שם ו ט) ״עַד מָתַי עָצֵל תִּשְׁכָּב״. וְכָאן הוּא מְצַוֶּה שֶׁיִּתְעַסֵּק בִּיקִידַת אֵשׁ כָּל הַלַּיְלָה עַד הַבֹּקֶר, וְיֵשׁ לָחוּשׁ שֶׁמִּצַּד הָעַצְלָה הַמְּצוּיָה בָּאָדָם יָבֹא לִידֵי תַּרְדֵּמָה וִיקַלְקֵל הַקָּרְבָּן, עַל כֵּן הוּא צָרִיךְ זֵרוּז.","complete":false},{"workId":"Haamek_Davar_on_Leviticus","unitId":"Haamek_Davar_on_Leviticus.6.17","commentator":"העמק דבר","sourceLine":"העמק דבר · ספר תורת אלוהים, וילנא 1879 · נחלת הכלל · ספריא","chapter":6,"verse":13,"dh":"זה קרבן אהרן ובניו וגו׳.","text":"כבר דקדקו חז״ל ברבה על זה הלשון. ונראה דמצינו דבמנחת חביתין נכלל כל ד׳ מנחות של יחיד. מתחלה היה עשרון סלת. ואח״כ היא מורבכת ואח״כ היא מעשה מאפה תנור ואח״כ היא מעשה מחבת. ואמר הכתוב אחר פ׳ וזאת תורת המנחה שכולל כל הד׳ מנחות וזה מעשה מנחות כולם היא קרבן אהרן ובניו ובדרך דרוש יש להבין טעם שצוה הקב״ה על הכהנים להביא בכל יום מעין ד׳ מנחות. דכבר ביארנו ענין ד׳ מנחות הללו בא לכפר על השחתת מדות ב״א בקלקול א׳ מד׳ מרות. והנה עבודת הכהנים בישראל להיות על פיהם כל ריב היינו שעליהם לראות שלא יהא ריב בין אדם לחבירו ולתקן כל משחתם של ישראל כמו שביארנו לשון המקרא בפ׳ שופטים.","complete":false},{"workId":"Sforno_on_Leviticus","unitId":"Sforno_on_Leviticus.7.2","commentator":"ספורנו","sourceLine":"ספורנו · ובלכתך בדרך · נחלת הכלל · ספריא","chapter":7,"verse":11,"dh":null,"text":"ואמר וזאת תורת זבח השלמים. והודיע שאף על פי שכל השלמים קדשים קלים, מכל מקום יש חלוק ביניהם שאם הם על אודות הודאה, יהיה עמהם לתת בתוכו מין חמץ. כי אמנם סבת הסכנה אשר עליה ההודאה הוא שאור שבעיסה, מכל מקום מיני המצות רבות עליו, וברבות הלחם יתפרסם הנס לאוכלים רבים, וכלם נאכלים בזמן קדשי קדשים שהם ליום ולילה.","complete":true},{"workId":"Or_HaChaim_on_Leviticus","unitId":"Or_HaChaim_on_Leviticus.8.1","commentator":"אור החיים","sourceLine":"אור החיים · Vocalized Edition · נחלת הכלל · ספריא","chapter":8,"verse":2,"dh":"קַח אֶת אַהֲרֹן וְגוֹ׳.","text":"פָּרָשָׁה זוֹ נֶאֶמְרָה קוֹדֶם הֲקָמַת הַמִּשְׁכָּן, וְטַעַם שֶׁנֶּאֶמְרָה כָּאן, לוֹמַר לְךָ שֶׁקָּדְמוּ כָּל מִשְׁפְּטֵי הַקָּרְבָּנוֹת וּפְרָטֵיהֶן וְדִקְדּוּקֵיהֶן קוֹדֶם מִלּוּאָיו, כִּי לַעֲשׂוֹת כֻּלָּן נִתְכַּהֲנוּ הוּא וּבָנָיו, וְלֹא נִתְכַּהֵן עַד שֶׁלִּמְּדוֹ מֹשֶׁה כָּל פְּרָטֵי דִּינֵי כָּל הַקָּרְבָּנוֹת וְקִיֵּם וְקִבֵּל עָלָיו לַעֲשׂוֹת כְּכָל הַכָּתוּב, וְאָז אָמַר לוֹ ״קַח אֶת אַהֲרֹן״ שֶׁעַל מְנָת כֵּן נִתְכַּהֵן, וְעוֹד שֶׁזּוּלַת זֶה מַשְׁכַּחַת שֶׁיָּבִיא אָדָם מִיִּשְׂרָאֵל קָרְבָּן מִיָּד בְּקָרְבָתוֹ לִפְנֵי ה׳ וְלֹא יֵדַע מַה לַעֲשׂוֹת.","complete":true},{"workId":"Tur_HaArokh_on_Leviticus","unitId":"Tur_HaArokh_on_Leviticus.8.12","commentator":"טור הארוך","sourceLine":"טור הארוך · Perush al ha-Torah, Hanover, 1838 · נחלת הכלל · ספריא","chapter":8,"verse":22,"dh":"את האיל השני איל המלואים.","text":"כתב הרמב\"ן כל הקרבנות האלו באים למלא את ידם כדכתיב וזה הדבר אשר תעשה להם לכהן לי לקח פר אחד בן בקר ואילים שנים אלא נקרא השני איל המלואים בעבור שהוא סוף הקרבנות הללו ובו תמלא ידם וכהנו לפניו ויתכן ? כי כולם מעכבין בענין. ויתכן כי החטאת לכפר על המזבח ולקדשו כי כן כתיב ועולה להרצאה על הכהנים ככפרת כל עולת נדבה והשלמים תודה לשם שנתן להם בביתו יד ושם והנה השלמי' לבדם באים על מילוי הידים ולכך קורא אותם מילואים:","complete":true}],"shmini":[{"workId":"Or_HaChaim_on_Leviticus","unitId":"Or_HaChaim_on_Leviticus.9.1","commentator":"אור החיים","sourceLine":"אור החיים · Vocalized Edition · נחלת הכלל · ספריא","chapter":9,"verse":1,"dh":"וַיְהִי בַּיּוֹם הַשְּׁמִינִי.","text":"צָרִיךְ לָדַעַת מָה טַעַם אָמַר ״וַיְהִי״, וּבְמַסֶּכֶת מְגִלָּה (מגילה י.) אָמַר רַבִּי לֵוִי: דָּבָר זֶה מָסֹרֶת בְּיָדֵינוּ מֵאַנְשֵׁי כְּנֶסֶת הַגְּדוֹלָה – כָּל מָקוֹם שֶׁנֶּאֱמַר ״וַיְהִי״ אֵינוֹ אֶלָּא לְשׁוֹן צַעַר. וּמַקְשֶׁה: וְהַכְּתִיב ״וַיְהִי בַּיּוֹם הַשְּׁמִינִי״, וְתַנְיָא: אוֹתוֹ הַיּוֹם הָיְתָה שִׂמְחָה לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא כְּיוֹם בְּרִיאַת שָׁמַיִם וָאָרֶץ, כְּתִיב הָכָא ״וַיְהִי״ וְגוֹ׳ וּכְתִיב הָתָם (בראשית א:ה) ״וַיְהִי עֶרֶב וַיְהִי בֹקֶר״ וְגוֹ׳. וּמְתָרֵץ: הָא מֵתוּ נָדָב וַאֲבִיהוּא. וּמַקְשֶׁה עוֹד:","complete":false},{"workId":"Haamek_Davar_on_Leviticus","unitId":"Haamek_Davar_on_Leviticus.9.18","commentator":"העמק דבר","sourceLine":"העמק דבר · ספר תורת אלוהים, וילנא 1879 · נחלת הכלל · ספריא","chapter":9,"verse":17,"dh":"וימלא כפו ממנה.","text":"היא קמיצה. מכ״מ צריך טעם למה כתב כאן לשון משונה. אלא נכלל כאן עוד כונה שניה. דבאמת עשה כאן אהרן שלא כדין לדורות. דשלמים קודמין למנחה כדתנן בזבחים פ׳ כל התדיר. ומקרא מלא כתיב גם כאן ושור ואיל לשלמים וגו׳ ומנחה בלולה בשמן. אלא משום שבכל הקרבנות שעשה אהרן באותו יום נתמלאו ידיו בזה לעבודת המזבח. ועדיין לא נתמלא אלא אצבעותיו שהם כלי המעשה ולא הכף. והשלמים טעונין תנופה על הכף ועדיין לא נתמלא הכף בעבודה. דתנופה עצמה אינה עבודה שמעכבת. ע״כ הקדי׳ אהרן את המנחה ובקמיצה מלא גם כפו ממנה:","complete":true},{"workId":"Rabbeinu_Bahya_on_Leviticus","unitId":"Rabbeinu_Bahya_on_Leviticus.9.21","commentator":"רבינו בחיי","sourceLine":"רבינו בחיי · Midrash Rabbeinu Bachya [ben Asher]. Warsaw, 1878 · נחלת הכלל · ספריא","chapter":9,"verse":24,"dh":"ותצא אש מלפני ה' ותאכל על המזבח.","text":"הנה עתה ביום השמיני שנתחנך המשכן בקרבנות הנזכרים המובאים לכפר על מעשה העגל, ירדה אש מן השמים לקבל אותם, והאש הזאת היא שעמדה עד דורו של שלמה שבנה הבית, כל ימי הבית היתה האש קיימת לא כבתה עד שחרב, ועל זה רמז הכתוב (ויקרא ו׳:ו׳) אש תמיד תוקד על המזבח לא תכבה. וכן מצינו י\"ב אשות שנפלו מן השמים בדורות ובזמנים חלוקים, שש מהן היו לקבלת הקרבנות ודרך רצוי ורחמנות, והשש הנותרים דרך כעס ונקמה.","complete":false},{"workId":"Ramban_on_Leviticus","unitId":"Ramban_on_Leviticus.10.10","commentator":"רמב״ן","sourceLine":"רמב״ן · On Your Way New · נחלת הכלל · ספריא","chapter":10,"verse":16,"dh":"שעיר החטאת","text":"שעיר מוספי ראש חודש ושלשה שעירים קרבו בו ביום קחו שעיר עזים לחטאת (ויקרא ט׳:ג׳) ושעיר נחשון (במדבר ז' טז) (ושעיר ראש חודש (שם כח טו) ומכולם לא נשרף אלא זה ונחלקו בדבר חכמי ישראל יש אומרים מפני טומאה שנגעה בו נשרף ויש אומרים מפני אנינות נשרף לשון רש\"י (רש\"י על ויקרא י׳:ט״ז) ועל דעת האומר מפני טומאה נשרף כתב הרב בפסוק ואכלתי חטאת היום (ויקרא י׳:י״ט) היום אסור אבל אנינות לילה מותר שאין אונן אלא יום קבורה כי לפי זה אם מפני אנינות היה להם לאכלו בערב אלא קסבר אנינות לילה דאורייתא:","complete":true},{"workId":"Sforno_on_Leviticus","unitId":"Sforno_on_Leviticus.11.1","commentator":"ספורנו","sourceLine":"ספורנו · ובלכתך בדרך · נחלת הכלל · ספריא","chapter":11,"verse":2,"dh":"זאת החיה אשר תאכלו.","text":"הנה אחר שהתנצלו ישראל את עדים הרוחני שקנו במתן תורה, אשר בו היו ראוים לשרות שכינה עליהם בלתי אמצעי, כאמרו בכל המקום אשר אזכיר את שמי, אבא אליך וברכתיך כמו שיהיה הענין לעתיד לבא, כאמרו ונתתי משכני בתוככם, ולא תגעל נפשי אתכם מאס האל יתברך אחר כך מהשרות עוד שכינתו ביניהם כלל, כאמרו כי לא אעלה בקרבך, והשיג משה רבינו בתפלתו איזה תיקון, שתשרה השכינה בתוכם באמצעות משכן וכליו ומשרתיו וזבחיו, עד שהשיגו וזכו אל וירא כבוד ה' אל כל העם ואל ירידת אש מן השמים ובכן ראה לתקן מזגם שיהיה מוכן לאור באור החיים הנצחיים, וזה בתקון המזונות והתולדה.","complete":false},{"workId":"Tur_HaArokh_on_Leviticus","unitId":"Tur_HaArokh_on_Leviticus.11.17","commentator":"טור הארוך","sourceLine":"טור הארוך · Perush al ha-Torah, Hanover, 1838 · נחלת הכלל · ספריא","chapter":11,"verse":35,"dh":"תנור וכירים יותץ.","text":"בא ללמד שאע\"פ שהם מחוברים דינן לענין קבלת טומאה ככלי חרס התלושין ואמר יותץ ולא אמר ישבר לומר שאין צריך לשברים קטנים אלא שיהרסם בענין שלא יהו ראויין למלאכתם הראשונה ובא ללמד עוד שהם מקבלים טומאה במחובר שפיר' יותץ הבנין אשר בנה כענין נתיצה הריסת בנין כמו ונתץ את הבית. ואמר:","complete":true}],"tazria":[{"workId":"Haamek_Davar_on_Leviticus","unitId":"Haamek_Davar_on_Leviticus.12.1","commentator":"העמק דבר","sourceLine":"העמק דבר · ספר תורת אלוהים, וילנא 1879 · נחלת הכלל · ספריא","chapter":12,"verse":2,"dh":"כי תזריע וילדה זכר.","text":"כי תזריע מיותר. ויש דרשות כידוע. אמנם יש להוסיף ע״פ האגדה בנדה דל״א תניא היה ר״מ אומר מפני מה אמרה תורה נדה לשבעה מפני שרגיל בה וקץ בה א״ת תהא טמאה שבעת ימים כדי שתהיה חביבה על בעלה כשעת כניסתה לחופה. ולמדו זה הטעם ממקרא זה שהפסוק הקדים דמש״ה היא טמאה באשר כי תזריע והיינו מעוברת ומסולקת מדמים ומותרת לבעלה מש״ה נתן הכתוב לה שבעת ימי יולדת להיות אסורה לבעלה כמו נדה. ומש״ה אם ילדה זכר שהולד מחבבה על בעלה די בפרישה ז׳ ימים. ונקבה שאינה כן ה״ז מפרשה ממנו שבועים:","complete":true},{"workId":"Kli_Yakar_on_Leviticus","unitId":"Kli_Yakar_on_Leviticus.13.7","commentator":"כלי יקר","sourceLine":"כלי יקר · Vocalized Edition · נחלת הכלל · ספריא","chapter":13,"verse":7,"dh":"וְאִם פָּשֹׂה תִפְשֶׂה וְגוֹ׳.","text":"זֶה סִימָן שֶׁאֵין כֹּחַ בְּיַד הַטֶּבַע לִדְחוֹת מֵעָלָיו כָּל הַפְּסוֹלֶת כִּי רַב הוּא. וְזֶה גַּם כֵּן מוֹפֵת שֶׁלֹּא נִטְהַר מֵחֶטְאוֹ עוֹד טֻמְאָתוֹ בוֹ. וְאִם לֹא פָּשְׂתָה הַנֶּגַע, כְּבָר דָּחָה מֵעָלָיו הַטֶּבַע כָּל עִפּוּשׁ וּפְסוֹלֶת, זֶה מוֹפֵת כִּי כְּבָר גָּמַר בְּלִבּוֹ לָשׁוּב בִּתְשׁוּבָה שְׁלֵמָה. וְאִם כִּסְּתָה הַצָּרַעַת אֶת כָּל עוֹר הַנֶּגַע מֵרֹאשׁוֹ וְעַד רַגְלָיו, כְּבָר דָּחָה הַטֶּבַע כָּל הַחֹלִי לַחוּץ, וְאָז בְּלִי סָפֵק יִתְרַפֵּא, לְפִיכָךְ טָהוֹר הוּא.","complete":false},{"workId":"Or_HaChaim_on_Leviticus","unitId":"Or_HaChaim_on_Leviticus.13.23","commentator":"אור החיים","sourceLine":"אור החיים · Vocalized Edition · נחלת הכלל · ספריא","chapter":13,"verse":19,"dh":"שְׂאֵת לְבָנָה אוֹ וְגוֹ׳.","text":"בְּתוֹרַת כֹּהֲנִים אָמְרוּ טַעַם אָמְרוֹ ״לְבָנָה״, לוֹמַר שֶׁאֵינָהּ אֲדַמְדֶּמֶת, וּבַהֶרֶת לְבָנָה אֲדַמְדֶּמֶת. וּמִנַּיִן לִתֵּן בַּשְׂאֵת אֲדַמְדֶּמֶת וּבַבַּהֶרֶת לְבָנָה חֲלָקָה? תַּלְמוּד לוֹמַר ״נֶגַע צָרַעַת״ (ויקרא יג:כ), פֵּרוּשׁ, בְּסוֹף הָעִנְיָן.","complete":false},{"workId":"Sforno_on_Leviticus","unitId":"Sforno_on_Leviticus.13.8","commentator":"ספורנו","sourceLine":"ספורנו · ובלכתך בדרך · נחלת הכלל · ספריא","chapter":13,"verse":30,"dh":"נתק הוא.","text":"שיש בתוך מקום שער איזה מקום שנתק ממנו השער בכח החולי, לא בכח אדם ולא בכוח סם, ואף על פי שאין שם שום מראה כמו שקבלו רבותינו ז\"ל. וכן הוא מין צרעת אצל הרופאים. אמר אם כן שאף על פי שתהיינה במקום הנתק מראות טמאות ופסיון המחליטין שלא במקום שער, הנה השער השחור מציל במקום שער מן המראה ומן הפסיון:","complete":true}],"metzora":[{"workId":"Ramban_on_Leviticus","unitId":"Ramban_on_Leviticus.14.1","commentator":"רמב״ן","sourceLine":"רמב״ן · On Your Way New · נחלת הכלל · ספריא","chapter":14,"verse":2,"dh":"והובא אל הכהן","text":"יאמר שתהיה זאת תורת המצורע ביום שירצה להטהר שיובא אל הכהן כי אין לו טהרה לעולם אלא על פיו ואח\"כ פירש כי הכהן יצא אל מקום מושבו מחוץ למחנה והוא לא יבא אליו אע\"פ שנתרפא ומדרשו בתורת כהנים (פרשה א ג) והובא אל הכהן שלא ישהה ואם כן יאמר כי ביום שיטהר שיתרפא מנגעו יובא על כרחו אל הכהן וכן וכי יטהר הזב מזובו (ויקרא ט״ו:י״ג) ואם טהרה מזובה (שם טו כח) כשיפסקו ויהיו מנוקים ממנו כאשר פירשתי (רמב\"ן על ויקרא ט״ו:י״א) והוא הנכון:","complete":true},{"workId":"Haamek_Davar_on_Leviticus","unitId":"Haamek_Davar_on_Leviticus.14.18","commentator":"העמק דבר","sourceLine":"העמק דבר · ספר תורת אלוהים, וילנא 1879 · נחלת הכלל · ספריא","chapter":14,"verse":21,"dh":"ואין ידו משגת.","text":"בקרבן עו״י כתיב בלשון עתיד ואם לא תגיע ידו ואם לא תשיג ידו. וכן ביולדת כתיב ואם לא תמצא ידה וגו׳ וכאן כתיב ואין ידו משגת בלשון הוה. היינו משום דכל הקרבנות שאדם חייב באמצע השנה לא היה הולך לירושלים מיד אלא ממתין עד בוא הרגל ובא שמה והביא עמו כל חובותיו. והיה מקדיש לפעמים לפני המועד והביא הקרבן במועד. וע׳ מש״כ בס׳ דברים י״ב כ״ו. וא״כ אם היה דל בשעת הקדש והקדיש קרבן עני ואח״כ נתעשר בשעת הרגל היה צריך להביא קרבן עשיר. וכדאי׳ ביומא דמ״ב ובשלהי מס׳ כריתות מש״ה הזהיר הכתוב שלא יפריש קרבן עני אם לא שרואה בדעתו שלא תשיג ידו גם בשעת הקרבה במועד. וכן הוא ביולדת וכל מח״כ.","complete":false},{"workId":"Tur_HaArokh_on_Leviticus","unitId":"Tur_HaArokh_on_Leviticus.14.11","commentator":"טור הארוך","sourceLine":"טור הארוך · Perush al ha-Torah, Hanover, 1838 · נחלת הכלל · ספריא","chapter":14,"verse":34,"dh":"ונתתי נגע צרעת בבית ארץ אחוזתכם.","text":"כתב הרמב\"ן הכתוב מדבר כנגד כל ישראל והיה ראוי לומר דברו אל כל עדת בני ישראל אלא שהכתוב מקצר. אי נמי מדבר עמהם במקום כל ישראל. והטעם שאין כוונת הפרשה עתה רק ללמד להם כל דיני הצרעת ושילמדו אותם לכהנים ומשה לא הזהיר בהם עתה את ישראל אלא בבואם לארץ הזהירם בהם השמר בנגע הצרעת לשמור מאוד ולעשות ככל אשר יורו אתכם כאשר צויתים כי להם צוה תחלה במשפטים האלה:","complete":true},{"workId":"Rabbeinu_Bahya_on_Leviticus","unitId":"Rabbeinu_Bahya_on_Leviticus.14.19","commentator":"רבינו בחיי","sourceLine":"רבינו בחיי · Midrash Rabbeinu Bachya [ben Asher]. Warsaw, 1878 · נחלת הכלל · ספריא","chapter":14,"verse":54,"dh":"זאת התורה לכל נגע הצרעת ולנתק, ולצרעת הבגד ולבית, ולשאת ולספחת ולבהרת.","text":"אע\"פ שקבלת רז\"ל היא האמת והיא המעידה על עניני הצרעת, שבתחלה מלקה אותו בביתו כדי שיכניע לבבו ויפשפש במעשיו ויחזור בתשובה, חזר בו מוטב ואם לאו מלקהו בבגדו, חזר בו מוטב ואם לאו מלקהו בגופו ממש, אין סדור הענין כן בפרשיות, כי פרשת נגע צרעת כי תהיה באדם היא הקודמת, ואחריה פרשת והבגד כי יהיה בו נגע צרעת, ואחריה פרשת ונתתי נגע צרעת בבית ארץ אחזתכם. ואחזה התורה הדרך הזה כי הזכירו תחלה צרעת הגופות ואחר כך צרעת הבגדים ואח\"כ צרעת הבתים, לפי שהתורה כל דרכיה דרכי נועם וכל נתיבותיה שלום, וכדי שלא יהא הסדור מסודר בפורענות הולך וגדל, וכמו שהיה הענין, אלא הולך ומתמעט כנתבאר לנו בסדר הפרשיות.","complete":true},{"workId":"Or_HaChaim_on_Leviticus","unitId":"Or_HaChaim_on_Leviticus.15.10","commentator":"אור החיים","sourceLine":"אור החיים · Vocalized Edition · נחלת הכלל · ספריא","chapter":15,"verse":18,"dh":"וְרָחֲצוּ בַמַּיִם.","text":"טַעַם זִכְרוֹן רְחִיצָתוֹ, אָמְרוּ זִכְרוֹנָם לִבְרָכָה (תורת כהנים) לְהַשְׁווֹת לָהּ מִשְׁפַּט רְחִיצָתָהּ לְכָל הַתְּנָאִים הָרְמוּזִים בְּדִין רְחִיצָתוֹ. וְאִם תֹּאמַר אִם לָזֶה נִתְכַּוֵּן הַפָּסוּק לֹא הָיָה צָרִיךְ, וְהָיִינוּ לוֹמְדִים כֵּן מֵאָמְרוֹ ״וְאִשָּׁה״ בְּתוֹסֶפֶת ו׳ מוֹסִיף עַל עִנְיָן רִאשׁוֹן, לְהַשְׁווֹת מִשְׁפַּט שְׁנֵיהֶם וְלִתֵּן אֶת הָאָמוּר הָעֶלְיוֹן בַּתַּחְתּוֹן, כְּמוֹ שֶׁדָּרְשׁוּ בְּתוֹרַת כֹּהֲנִים בְּפָרָשַׁת וַיִּקְרָא כָּל אוֹתָם דִּינִים שֶׁכָּתוּב בָּהֶם וָא״ו בִּתְחִלָּה.","complete":false}],"achrei-mot":[{"workId":"Haamek_Davar_on_Leviticus","unitId":"Haamek_Davar_on_Leviticus.16.1","commentator":"העמק דבר","sourceLine":"העמק דבר · ספר תורת אלוהים, וילנא 1879 · נחלת הכלל · ספריא","chapter":16,"verse":1,"dh":"בקרבתם לפני ה׳ וימותו.","text":"אם נפרש שבא להשלמת ספור הסבה שמתו. הרי מיותר תיבת וימותו. ותו ק׳ מאי וידבר ה׳ והדר ויאמר ה׳. אלא האי בקרבתם לפני ה׳ וימותו הוא הדבור הראשון. והענין דאע״ג שמתו נו״א בהקריבם אש זרה ולכל תנא כדאית ליה ביומא פ׳ הוציאו לו. בכ״ז לא היו ראוים שימותו מיד. וכי מי שהעובר על חייבי מיתה ב״ש פוגע בו מדה״ד מיד ולמה מתו נו״א מיד ע״ז בא הדבור מפי הגבורה למשה. כי בקרבתם לפני ה׳ וימותו. משום שחטאם היה בעת שקרבו לפני ה׳ בפלטין של ממה״מ הקב״ה מש״ה פגעו בהם תומ״י מלאכי מות. ואח״כ אמר ה׳ למשה כל הפ׳ והא שהקדים לה זה הדבור למאמר הפ׳ הוא כדי ללמד לדורות הבאים דבר הנוגע לפ׳ של יוה״כ.","complete":false},{"workId":"Or_HaChaim_on_Leviticus","unitId":"Or_HaChaim_on_Leviticus.16.39","commentator":"אור החיים","sourceLine":"אור החיים · Vocalized Edition · נחלת הכלל · ספריא","chapter":16,"verse":26,"dh":"וְהַמְשַׁלֵּחַ וְגוֹ׳ לַעֲזָאזֵל.","text":"צָרִיךְ לָדַעַת מַה הוּא עֲזָאזֵל, וְרַבּוֹתֵינוּ זִכְרוֹנָם לִבְרָכָה (יומא סז:) פֵּרְשׁוּ עַז וְקָשֶׁה. וְיֵשׁ בָּזֶה הַרְבֵּה דְּרָשׁוֹת, עַל כָּל פָּנִים אֵין הַדַּעַת מִתְיַשֶּׁבֶת. וַיֵּאוֹרוּ עֵינַי בְּדִבְרֵי אַנְשֵׁי אֱמֶת שׁוֹנִין בְּש״ע נְהוֹרִים שֶׁל תּוֹרָה, שֶׁאָמְרוּ (זוהר ח״ב קנז.) כִּי הַמִּדְבָּר הֶחָרוּב הוּא מְקוֹם ס״מ הָרָשָׁע, וּכְפִי זֶה בְּחִינָה זוֹ תִּקָּרֵא ״מִדְבָּר״, וְתִקָּרֵא ״עֲזָאזֵל״, וְתִקָּרֵא ״עוּזָא וַעֲזָאֵל״, שֶׁאָמְרוּ זִכְרוֹנָם לִבְרָכָה שֶׁלָּהֶם יִרְמֹז שֵׁם זֶה. וְאוּלַי כִּי הַתֵּבָה תַּגִּיד זֶה עַל זֶה הַדֶּרֶךְ:","complete":false},{"workId":"Tur_HaArokh_on_Leviticus","unitId":"Tur_HaArokh_on_Leviticus.17.2","commentator":"טור הארוך","sourceLine":"טור הארוך · Perush al ha-Torah, Hanover, 1838 · נחלת הכלל · ספריא","chapter":17,"verse":3,"dh":"אשר ישחט שור או כשב או עז במחנה או אשר ישחט מחוץ למחנה.","text":"פי' הרמב\"ן פשט הפרשה איירי בב' עניינים לאסור בשר תאוה וחייב כרת אפי' על השוחט חולין בחוץ אם לא שיביאם אל פתח אהל מועד להקריבם שלמים להיות החלב והדם לגבוה והבשר לבעלים ואחר כך אמר איש איש מבני ישראל אשר יעלה עולה או זבח וגו' הזהיר שלא יעשה מזבח לה' בחוץ ויקריבו עליו השלמים הנזכרים או עולה כעין הנעש' במוקדשין בשעת היתר הבמות רק בפתח אהל מועד יעל' אותם לשם ולכך אמר או אשר ישחט מחוץ למחנ' כי אע\"פ שבביאתכ' לארץ אתיר לכם בשר תאוה לפי שתהיו רחוקים כדכתיב כי ירחיב אבל במדבר אע\"פ שהוא מחוץ למחנה מכל מקום קרובים אתם לאהל מועד וראוי להביאו אל פתח אהל מועד וזהו כר' ישמעאל דאמר שנאסר להם בשר תאוה.","complete":false},{"workId":"Rabbeinu_Bahya_on_Leviticus","unitId":"Rabbeinu_Bahya_on_Leviticus.18.8","commentator":"רבינו בחיי","sourceLine":"רבינו בחיי · Midrash Rabbeinu Bachya [ben Asher]. Warsaw, 1878 · נחלת הכלל · ספריא","chapter":18,"verse":6,"dh":"איש איש אל כל שאר בשרו לא תקרבו וגו'.","text":"הכתוב הזה יאסור המשגל בשאר הבשר, ושאר הבשר הוא מה שמונה והולך בפרשה. לפי שאין קיום המין מן השאר ואין התולדה ראויה, ועל כן יאסר הכתוב ביאה כזאת. ומכאן אתה למד שענין המשגל אסור מדין התורה זולתי לקיום המין בלבד, וזהו שכתוב (ויקרא כ׳:י״ט) כי את שארו הערה, למדך הכתוב כי מפני השאר ירחיק הענין. וענין הנדה שאסרה תורה יורה כן שלא תתירנו אלא לקיום המין, שהרי אין קיום המין מדם הנדות, כי העובר נוצר מדם האשה או כלו או רובו אבל מדם הנדות לא יהיה נוצר כלל, כך כתב הרמב\"ן ז\"ל. ומה יאמר הרב בפצוע דכא שהוא מותר לבא בקהל ה' כגון גיורת ומשוחררת וזה ראיה שכל שאינו לקיום המין אינו אסור וכמו שאבאר בהגיעי שם בע\"ה.","complete":true},{"workId":"Kli_Yakar_on_Leviticus","unitId":"Kli_Yakar_on_Leviticus.18.8","commentator":"כלי יקר","sourceLine":"כלי יקר · Vocalized Edition · נחלת הכלל · ספריא","chapter":18,"verse":24,"dh":"אַל תִּטַּמְּאוּ בְּכָל אֵלֶּה.","text":"מַשְׁמָע שֶׁלֹּא יָבֹאוּ לִידֵי הַקָּצֶה הָאַחֲרוֹן מִן הָרַע שֶׁתִּטְמָא הָאָרֶץ עַד שֶׁיִּטַּמְּאוּ בְּכָל אֵלֶּה, וְאַחַר כָּךְ אָמַר ״וְלֹא תַעֲשׂוּ מִכֹּל הַתּוֹעֵבוֹת״, מַשְׁמָע אֲפִלּוּ בְּמִקְצָתָן תִּטְמָא הָאָרֶץ. וְנִרְאֶה לְפָרֵשׁ שֶׁלְּכָךְ הִזְכִּיר שְׁנֵי מִינֵי עֳנָשִׁים, הֲלֹא הֵמָּה הֲקָאַת הָאָרֶץ, וּכְרִיתוּת הַנְּפָשׁוֹת הָעוֹשׂוֹת.","complete":false}],"kedoshim":[{"workId":"Kli_Yakar_on_Leviticus","unitId":"Kli_Yakar_on_Leviticus.19.1","commentator":"כלי יקר","sourceLine":"כלי יקר · Vocalized Edition · נחלת הכלל · ספריא","chapter":19,"verse":2,"dh":"דַּבֵּר אֶל כָּל עֲדַת בְּנֵי יִשְׂרָאֵל וְאָמַרְתָּ אֲלֵהֶם קְדֹשִׁים תִּהְיוּ.","text":"פֵּרֵט ״כָּל עֲדַת״, כִּי אֵין עֵדָה פָּחוֹת מֵעֲשָׂרָה וְאֵין דָּבָר שֶׁבִּקְדֻשָּׁה פָּחוֹת מֵעֲשָׂרָה, עַל כֵּן אָמַר כָּאן ״דַּבֵּר אֶל כָּל עֲדַת בְּנֵי יִשְׂרָאֵל״, אֶל כָּל עֵדָה וְעֵדָה שֶׁיִּהְיוּ קְדוֹשִׁים, עַל יְדֵי שֶׁהֵם מֻתָּרִים לְכָל דָּבָר שֶׁבִּקְדֻשָּׁה אֲשֶׁר בּוֹ מַקְדִּישִׁים שְׁמוֹ יִתְבָּרַךְ. זֶהוּ שֶׁאָמַר ״כִּי קָדוֹשׁ אָנִי״.","complete":true},{"workId":"Rabbeinu_Bahya_on_Leviticus","unitId":"Rabbeinu_Bahya_on_Leviticus.19.20","commentator":"רבינו בחיי","sourceLine":"רבינו בחיי · Midrash Rabbeinu Bachya [ben Asher]. Warsaw, 1878 · נחלת הכלל · ספריא","chapter":19,"verse":15,"dh":"בצדק תשפוט עמיתך.","text":"יזהיר שיהיה המשפט בצדק כלומר שיצדיק משפט איש ולא יעותנו שכל מי שישפט בצדק הנה הוא מעמיד כסא המלך שנאמר (תהילים פ״ט:ט״ו) צדק ומשפט מכון כסאך ואם יעות המפשט הלא הוא פוגם הכסא אשר למלך ויזלזל בכבודו, ואמרו במדרש אם הוא שופט בצדק שכינה עמו שנאמר (שם פב) אלהים נצב בעדת אל ואם לא שכינה מסתלקת שנאמר (שם יב) משוד עניים מאנקת אביונים עתה אקום יאמר ה', ורוח הקדש צווחת ואומרת רומה על שמים אלהים על כל הארץ כבודך.","complete":true},{"workId":"Tur_HaArokh_on_Leviticus","unitId":"Tur_HaArokh_on_Leviticus.19.21","commentator":"טור הארוך","sourceLine":"טור הארוך · Perush al ha-Torah, Hanover, 1838 · נחלת הכלל · ספריא","chapter":19,"verse":23,"dh":"וערלתם ערלתו.","text":"פירש\"י ואטמתם אטימתו שיהא אטום ונסגר מליהנות ממנו. וכתב הרמב\"ן והזכיר הכתוב (אטימה) בפרי הבא תוך ג' שנים מה שלא עשה כן בשאר איסורי הנאה כי ביאת הפרי בתחלתו נקרא פתיחה כמו שנאמר פתח הסמדר ולכך אמר ג' שנים יהיה לכם ערלים כאילו הפירות סגורים באילנות לא הוציאו פרח ולא פתחו סמדר.","complete":false},{"workId":"Or_HaChaim_on_Leviticus","unitId":"Or_HaChaim_on_Leviticus.19.87","commentator":"אור החיים","sourceLine":"אור החיים · Vocalized Edition · נחלת הכלל · ספריא","chapter":19,"verse":33,"dh":"וְכִי יָגוּר אִתְּךָ וְגוֹ׳.","text":"אָמַר לָשׁוֹן יָחִיד אִתְּךָ וְחָזַר לוֹמַר לְשׁוֹן רַבִּים בְּאַרְצְכֶם. לְצַד כִּי הַמְשָׁכַת הַגֵּרִים תִּהְיֶה בְּאֶמְצָעוּת הַצַּדִּיק אַבְרָהָם אָבִינוּ עָלָיו הַשָּׁלוֹם, גַּם לְצַד טֹהַר אֶרֶץ הַקְּדוֹשָׁה תִּגָּרֵר נַפְשׁוֹת הַשְּׁבוּיוֹת, לָזֶה אָמַר אִתְּךָ לְשׁוֹן יָחִיד לִרְמֹז אֶל הַצַּדִּיק, כִּי לֹא כֻּלָּן הֵם בְּגֶדֶר הַמְשָׁכַת עַנְפֵי הַקְּדֻשָּׁה, וְאָמַר בְּאַרְצְכֶם לִרְמֹז לְמַעֲשֵׂה הָאָרֶץ, שֶׁגַּם הִיא יֶשְׁנָהּ בְּגֶדֶר פְּעֻלָּה טוֹבָה זוֹ.","complete":true},{"workId":"Sforno_on_Leviticus","unitId":"Sforno_on_Leviticus.20.1","commentator":"ספורנו","sourceLine":"ספורנו · ובלכתך בדרך · נחלת הכלל · ספריא","chapter":20,"verse":2,"dh":"אשר יתן מזרעו למולך.","text":"אחר שבאר הכונה האלהית לקדש את ישראל למען ידמו אליו כפי האפשר והורה אותם את הדרך אשר בהם תושג התכלית המכוונת מאת האל יתעלה והזהיר מהפכה דבר בעונש המיטמאים בא' מג' מיני טומאות המנגדות לקדושה הנזכרת. האחת היא הטומאה בדעות כענין המולך שאמר בו למען טמא את מקדשי וכענין האובות והידעונים שאמר עליהם למעלה אל תבקשו לטמאה בהם. והשנית היא הטומאה בזרע וזה בעריות שאמר עליהם למעלה אל תטמאו בכל אלה כי בכל אלה נטמאו הגוים ותטמא הארץ. והשלישית הטומאה במאכלות האסורות שאמר עליהם בסוף זאת הפרשה אשר הבדלתי לכם לטמא.","complete":false},{"workId":"Haamek_Davar_on_Leviticus","unitId":"Haamek_Davar_on_Leviticus.20.13","commentator":"העמק דבר","sourceLine":"העמק דבר · ספר תורת אלוהים, וילנא 1879 · נחלת הכלל · ספריא","chapter":20,"verse":8,"dh":"ועשיתם אותם.","text":"תוסיפו לחדש בפלפולה. ובא המקרא הזה לכאן משום שעסק התורה מועיל לתפלה ודביקות בה׳. כדאי׳ במס׳ עבודת כוכבים ד״ג כל הלומד תורה בלילה חוט ש״ח משוך עליו ביום שנאמר יומם יצוה ה׳ חסדו ובלילה שירה עמי תפלה לאל חיי. ביאורו דתכלית חוט ש״ח הוא לתפלה לאל חיי. ובמס׳ תמיד אי׳ כל הלומד תורה בלילה שכינה כנגדו שנאמר קומי רוני בלילה לראש אשמורות שפכי כמים לבך נכח פני אדני שאי אליו כפיך על נפש עולליך וגו׳. והיינו דלא כתיב בזה המקרא משפטי משום שלזה התועלת אין נ״מ בלמוד דינים הלכה למעשה אלא רק כח התלמוד מקדש ומעלה את האדם שתהא תפלתו מקובלת. ומש״ה אפילו למוד חקי תורה לבד מועיל לזה:","complete":true}],"emor":[{"workId":"Tur_HaArokh_on_Leviticus","unitId":"Tur_HaArokh_on_Leviticus.21.1","commentator":"טור הארוך","sourceLine":"טור הארוך · Perush al ha-Torah, Hanover, 1838 · נחלת הכלל · ספריא","chapter":21,"verse":1,"dh":"אמור אל הכהנים.","text":"אמור ואמרת להזהיר גדולים על הקטנים. וכתב הרמב\"ן והזהיר כמה פעמים בתורה על הקטנים בדם ובשרצים ובטומאה ומהם נלמוד לכל איסורין שבתורה וכתב עוד האזהרה הזאת שלא נסייע לקטנים שיעברו אבל אם הם יעשו לדעת עצמם אין אנו מצווין עליהם להפרישם.","complete":false},{"workId":"Kli_Yakar_on_Leviticus","unitId":"Kli_Yakar_on_Leviticus.21.10","commentator":"כלי יקר","sourceLine":"כלי יקר · Vocalized Edition · נחלת הכלל · ספריא","chapter":21,"verse":17,"dh":"אִישׁ מִזַּרְעֲךָ אֲשֶׁר יִהְיֶה בוֹ מוּם.","text":"כָּאן אָמַר ״בוֹ מוּם״, וּלְמַטָּה הָפַךְ וְאָמַר ״מוּם בּוֹ״, וְכָאן אָמַר ״אֲשֶׁר יִהְיֶה״ – לְהַבָּא מַשְׁמָע, וְאַחַר כָּךְ אָמַר ״כָּל אִישׁ אֲשֶׁר בּוֹ מוּם״ – בַּהֹוֶה מַשְׁמָע. וּמַהוּ שֶׁנָּתַן טַעַם לַדָּבָר בְּאוֹתוֹ דָּבָר עַצְמוֹ וְאָמַר: ״כִּי כָל אִישׁ אֲשֶׁר בּוֹ מוּם לֹא יִקְרַב״. וּמַה שֶּׁפֵּרַשׁ רַשִׁ״י: אֵינוֹ דִּין שֶׁיִּקְרַב, כְּמוֹ ״הַקְרִיבֵהוּ נָא לְפֶחָתֶךָ״, אֵינוֹ מְפֹרָשׁ בַּמִּקְרָא.","complete":true},{"workId":"Sforno_on_Leviticus","unitId":"Sforno_on_Leviticus.22.5","commentator":"ספורנו","sourceLine":"ספורנו · ובלכתך בדרך · נחלת הכלל · ספריא","chapter":22,"verse":18,"dh":"אשר יקריב קרבנו.","text":"אחר שדבר בכהנים המקריבים וקדושתם דבר בתנאי הנקרבים ואמר לכל נדריהם ולכל נדבותם. שאף על פי שהם קרבנות נדבה ויחשוב שכל מה שיתנדב אפילו בעל מום יהיה לרצון כיון שלא היה זה שנתן חובה עליו כמו שחשבו קצת מישראל והראה טעותם הנביא באמרו וכי תגישון עור לזבוח אין רע וכי תגישו פסח וחולה אין רע הקריבהו נא לפחתך:","complete":true},{"workId":"Or_HaChaim_on_Leviticus","unitId":"Or_HaChaim_on_Leviticus.23.1","commentator":"אור החיים","sourceLine":"אור החיים · Vocalized Edition · נחלת הכלל · ספריא","chapter":23,"verse":2,"dh":"מוֹעֲדֵי ה׳ וְגוֹ׳.","text":"גְּזֵרַת הַדִּבּוּר. רַזַ״ל אָמְרוּ (תורת כהנים) כִּי הוּא ״אֲשֶׁר תִּקְרְאוּ אוֹתָם״, פֵּרוּשׁ כִּי מוֹעֲדֵי ה׳ הֵם בִּזְמַן שֶׁיִּקְרְאוּ אוֹתָם יִשְׂרָאֵל. וְצָרִיךְ לָדַעַת לָמָּה חָזַר לוֹמַר ״אֵלֶּה הֵם מוֹעֲדָי״. עוֹד צָרִיךְ לָדַעַת לָמָּה חָזַר לְצַוּוֹת עַל הַשַּׁבָּת. וְעוֹד רוֹאֶה אֲנִי שֶׁחָזַר לוֹמַר פַּעַם שֵׁנִי אַחַר מִצְוַת הַשַּׁבָּת ״אֵלֶּה מוֹעֲדֵי ה׳״.","complete":true},{"workId":"Haamek_Davar_on_Leviticus","unitId":"Haamek_Davar_on_Leviticus.23.21","commentator":"העמק דבר","sourceLine":"העמק דבר · ספר תורת אלוהים, וילנא 1879 · נחלת הכלל · ספריא","chapter":23,"verse":24,"dh":"יהיה לכם שבתון.","text":"מכאן למדו חז״ל בשבת דכ״ד ובכ״מ דיו״ט עשה אע״ג דבגמ׳ הביאו שבתון עשה מכ״מ עיקר ההוכחה מדכתיב בר״ה יהיה לכם שבתון בלשון צווי. ומכאן למדנו בכל מועדי ה׳ דכתיב שבתון. [ונראה דאע״ג דרב אשי הוא שאמר דיו״ט הוי עשה ול״ת ואמוראי קמאי פליגי ע״ז מכל מקום בר״ה הכל מודים. כי סתמא דגמרא הוא במסכת ראש השנה דף ל״ב ב׳ ובזה מיושב קו׳ הטורי אבן על שיטת ר״ת יע״ש] זהו דרשת חז״ל. ועוד לאלוה מלין אמאי פירש הכתוב אזהרת עשה זו ביחוד בר״ה. עוד יש להבין הא דכתיב כאן זכרון תרועה ובאמת המצוה להריע בפועל כמו שכתוב בפ׳ מוספין יום תרועה. וא״כ מהו זכרון. עוד יש להבין מה זה פי׳ הכתוב תרועה והלא אין תרועה בלי תקיעה.","complete":false}],"behar":[{"workId":"Tur_HaArokh_on_Leviticus","unitId":"Tur_HaArokh_on_Leviticus.25.1","commentator":"טור הארוך","sourceLine":"טור הארוך · Perush al ha-Torah, Hanover, 1838 · נחלת הכלל · ספריא","chapter":25,"verse":1,"dh":"בהר סיני.","text":"פירש\"י מה ענין שמטה אצל הר סיני והלא כל המצות נאמרו בסיני אלא מה שמיטה נאמרו כללותיה ופרטותיה ודקדוקיה בסיני וכו'. והקשה הרמב\"ן עליו כי הרבה מצות יש שלא נשנו בערבות מואב כמו שמטת קרקע ונדע מהן שנאמרו כלליהן ופרטיהן בסיני או באהל מועד ועוד מניין שהוקשו שאר הדברות שנשנו בערבות מואב לשמיטה שלא נשנית ואדרבה יותר נראה לומר כיון שנשנו בערבות מואב שלא נאמר בסיני אלא כלליהן ולכך נשנו לבאר פרטיהן.","complete":false},{"workId":"Kli_Yakar_on_Leviticus","unitId":"Kli_Yakar_on_Leviticus.25.10","commentator":"כלי יקר","sourceLine":"כלי יקר · Vocalized Edition · נחלת הכלל · ספריא","chapter":25,"verse":14,"dh":"אוֹ קָנֹה מִיַּד עֲמִיתֶךָ אַל תּוֹנוּ.","text":"דָּרְשׁוּ רז״ל (ב״מ מז:) דָּבָר הַנִּקְנֶה מִיָּד לְיָד שַׁיָּךְ בּוֹ אוֹנָאָה, אֲבָל לְקַרְקָעוֹת אֵין אוֹנָאָה. וְטַעֲמוֹ שֶׁל דָּבָר שֶׁכָּל דָּבָר הַנִּמְכָּר אֵינוֹ בְּעֵרֶךְ אֶחָד בְּכָל הַזְּמַנִּים, כִּי כְּפִי הִשְׁתַּנּוּת הַזְּמַנִּים לִפְעָמִים יוּקְרוּ אוֹ יוּזְלוּ, עַל כֵּן לְעוֹלָם אֵין עֵרֶךְ יָדוּעַ לְשׁוּם דָּבָר הַנִּמְכָּר. לְפִיכָךְ הַקַּרְקַע אַף עַל פִּי שֶׁבַּאֲשֶׁר הִיא שָׁם הָיָה מוֹכְרוֹ בְּזוֹל אוֹ בְּיֹקֶר, מִכָּל מָקוֹם לֹא יִמָּלֵט שֶׁיָּבֹא הַזְּמַן שֶׁתִּהְיֶה נִמְכֶּרֶת בְּאוֹתוֹ עֵרֶךְ שֶׁהוּא קוֹנֶה אוֹתָהּ עַכְשָׁיו.","complete":false},{"workId":"Or_HaChaim_on_Leviticus","unitId":"Or_HaChaim_on_Leviticus.25.23","commentator":"אור החיים","sourceLine":"אור החיים · Vocalized Edition · נחלת הכלל · ספריא","chapter":25,"verse":19,"dh":"וְנָתְנָה הָאָרֶץ פִּרְיָהּ.","text":"פֵּרוּשׁ פְּרִי הַקָּצוּב בְּכֹחָהּ לַעֲשׂוֹת, שֶׁהֲגַם שֶׁנִּרְאֶה פְּרִי הָאָרֶץ לֹא נְשַׁעֵר כִּי זֶה הוּא כֹּחַ הָאָרֶץ וְלֹא יוֹתֵר, שֶׁהֲלֹא תִּמְצָא (כתובות קיב.) שֶׁגָּעַר הֶחָכָם בָּאָרֶץ וְעָצְרָה כֹּחָהּ וְלֹא נָתְנָה פֵּרוֹתֶיהָ אַחַר כָּךְ כַּסֵּדֶר הָרִאשׁוֹן, וְהָרוֹאֶה פֵּרוֹתֶיהָ אַחַר גַּעֲרָתוֹ לֹא קוֹדֶם יַחְשׁוֹב כִּי הוּא זֶה כֹּחָהּ.","complete":true},{"workId":"Haamek_Davar_on_Leviticus","unitId":"Haamek_Davar_on_Leviticus.25.37","commentator":"העמק דבר","sourceLine":"העמק דבר · ספר תורת אלוהים, וילנא 1879 · נחלת הכלל · ספריא","chapter":25,"verse":26,"dh":"והשיגה ידו.","text":"הכי מיבעי או השיגה ידו. ואיש כי לא יהיה לו גואל מיותר. ובא להורות לנו דרך מוסר כי זה שלא יהיה לו גואל יבא לידי כך שתשיג ידו. דמי שיש לו גואל והוא בוטח עליו מסיר בטחונו מה׳ משא״כ אם אין לו על מי לסמוך ה״ה חוסה בו ית׳ והקב״ה יודע חוסי בו וממציא לפניו כדי גאולתו. (ואח״כ ראיתי שהקדימני בזה בס׳ מלאכת מחשבת) וכתיב ואיש. ולא ואם לא יהיה לו גואל. ללמדנו דגם הבוטח בה׳ מכ״מ צריך להיו׳ איש היודע את בוראו ומשתדל בתפלה ובקשה ממנו ית׳. וכמבואר בויקרא רבה פ׳ י״ז טוב ה׳ לקויו יכול לכל תלמוד לומר לנפש תדרשנו. פי׳ גם יבקש בתפלה:","complete":true},{"workId":"Ramban_on_Leviticus","unitId":"Ramban_on_Leviticus.25.15","commentator":"רמב״ן","sourceLine":"רמב״ן · On Your Way New · נחלת הכלל · ספריא","chapter":25,"verse":29,"dh":"ואיש כי ימכר בית מושב עיר חומה","text":"בעבור שממכר ביתו של אדם קשה בעיניו מאד ויבוש ממנו בעת שימכרנו רצתה התורה שיגאלנו בתוך השנה הראשונה ובעבור כי האדם לשדה נעבד וממנו יצא לחם למחיתו רצה שיצא השדה ביובל אבל הבית לאחר היאוש ששינה דירתו ועמד שנה בבית אחר לא יזיק לו כי לא תמעט מחיתו אם יחלט ובתי החצרים עשויים לשמירת השדות ולהיותם מושב לעובדי האדמה ועל כן דינם כשדה הארץ:","complete":true},{"workId":"Rabbeinu_Bahya_on_Leviticus","unitId":"Rabbeinu_Bahya_on_Leviticus.25.30","commentator":"רבינו בחיי","sourceLine":"רבינו בחיי · Midrash Rabbeinu Bachya [ben Asher]. Warsaw, 1878 · נחלת הכלל · ספריא","chapter":25,"verse":47,"dh":"לעקר משפחת גר.","text":"ע\"ד הפשט גוי עקרי שמעולם לא נתגייר והוא ממשפחת גר. ובאור הכתוב כי בין שיהיה נמכר לגר שהוא תושב עמנו או לעקר כלומר לגוי עצמו וכן התרגום לארמאי, מכל מקום אחרי נמכר גאולה תהיה לו, כי הדבר מסור לכל אחד מישראל, והוא שאמר אחד מאחיו יגאלנו, או הקרובים שהם קודמים וזהו או דודו או בן דודו יגאלנו, או שיגאל הוא את עצמו זהו או השיגה ידו ונגאל.","complete":true}],"bechukotai":[{"workId":"Kli_Yakar_on_Leviticus","unitId":"Kli_Yakar_on_Leviticus.26.1","commentator":"כלי יקר","sourceLine":"כלי יקר · Vocalized Edition · נחלת הכלל · ספריא","chapter":26,"verse":3,"dh":"אִם בְּחֻקּוֹתַי תֵּלֵכוּ וְגֵו׳.","text":"פֵּרֵשׁ רַשִׁ״י שֶׁתִּהְיוּ עֲמֵלִים בַּתּוֹרָה כו׳. אַף עַל פִּי שֶׁרַשִׁ״י הִכְרִיחַ זֶה מִן יִתּוּר הַפְּסוּקִים, שֶׁהֲרֵי קִיּוּם הַמִּצְוֹת כְּבָר אָמוּר כו׳, מִכָּל מָקוֹם גַּם מִצַּד הַלָּשׁוֹן הַדָּבָר צָרִיךְ בֵּאוּר. וְהוּא, שֶׁדַּעְתּוֹ לַעֲשׂוֹת שְׁלֹשָׁה חֲלֻקּוֹת בְּפָסוּק זֶה, אֲשֶׁר כְּנֶגְדָּם אָמַר שְׁלֹשָׁה פְּעָמִים ״וְנָתַתִּי״. בְּפָרָשָׁה רִאשׁוֹנָה אָמַר ״אִם בְּחֻקּוֹתַי תֵּלֵכוּ״, עַל הֶעָמֵל בַּתּוֹרָה וְקוֹבֵעַ עִתִּים לַתּוֹרָה חֹק וְלֹא יַעֲבֹר.","complete":false},{"workId":"Or_HaChaim_on_Leviticus","unitId":"Or_HaChaim_on_Leviticus.26.66","commentator":"אור החיים","sourceLine":"אור החיים · Vocalized Edition · נחלת הכלל · ספריא","chapter":26,"verse":6,"dh":"וְנָתַתִּי שָׁלוֹם בָּאָרֶץ.","text":"צָרִיךְ לָדַעַת לָמָּה הֻצְרַךְ לוֹמַר זֶה אַחַר שֶׁכְּבָר אָמַר ״וִישַׁבְתֶּם לָבֶטַח״, וְאוּלַי שֶׁיְּכַוֵּן עַל עַם בְּנֵי יִשְׂרָאֵל עַצְמָם שֶׁלֹּא יִהְיֶה לָהֶם פֵּרוּד הַלְּבָבוֹת, שֶׁיִּטַּע ה׳ בֵּינֵיהֶם שָׁלוֹם וְרֵעוּת. אוֹ אֶפְשָׁר שֶׁיְּכַוֵּן עַל כְּלָלוּת הָעוֹלָם, וְתֵדַע שֶׁכְּשֶׁמְּדַבֵּר עַל אֶרֶץ יִשְׂרָאֵל מַזְכִּירָהּ בְּכִנּוּי, כְּאָמְרוֹ בְּסָמוּךְ ״בְּאַרְצְכֶם״, וְכָאן אָמַר בָּאָרֶץ שֶׁמַּבְטִיחָם כִּי יִהְיֶה שָׁלוֹם בְּכָל הָעוֹלָם.","complete":false},{"workId":"Sforno_on_Leviticus","unitId":"Sforno_on_Leviticus.26.14","commentator":"ספורנו","sourceLine":"ספורנו · ובלכתך בדרך · נחלת הכלל · ספריא","chapter":26,"verse":10,"dh":"וישן מפני חדש תוציאו.","text":"יהיה לכם מהנושן די צרכיכם אף על פי שמאז שיהיה ישן תוציאו ממנו לפליטי האומות לפרנסם כאמרו כי הגוי והממלכה אשר לא יעבדוך יאבדו. והטעם שתוציאו דבר שיש בו חיי נפש מארצכם אל האומות הוא מפני שכבר בא החדש ולא תדאגו שיחסר לכם כמו שהיה כאמרם (כתובות פרק שני דייני גזירות) אין מוציאין מארץ ישראל דבר שיש בו חיי נפש כגון יינות שמנים, וסלתות:","complete":true},{"workId":"Ramban_on_Leviticus","unitId":"Ramban_on_Leviticus.27.1","commentator":"רמב״ן","sourceLine":"רמב״ן · On Your Way New · נחלת הכלל · ספריא","chapter":27,"verse":1,"dh":"וידבר ה' אל משה לאמר וגו' איש כי יפלא","text":"גם זו הפרשה דבוקה שהיתה בהר סיני מחוברת אל התוכחות כי היא במשפטי היובל כמו שהזכיר במקדיש שדה מקנה (להלן פסוקים כג-כד) ושדה אחוזה (שם יז יח) אלא שכלל משפטי כל הנודרים בפרשה אחת ולכך אמר בסוף (ויקרא כ״ז:ל״ד) אלה המצות אשר צוה ה' את משה אל בני ישראל בהר סיני על כל הנאמרות למעלה כי מכאן ואילך ידבר במצות אהל מועד:","complete":true},{"workId":"Haamek_Davar_on_Leviticus","unitId":"Haamek_Davar_on_Leviticus.27.15","commentator":"העמק דבר","sourceLine":"העמק דבר · ספר תורת אלוהים, וילנא 1879 · נחלת הכלל · ספריא","chapter":27,"verse":16,"dh":"זרע חומר שערים וגו׳.","text":"והנה יש להסביר טעמא דהאי דינא אע״ג שמכ״מ חק הוא שהרי אין נ״מ בין פרדסות סבסטי בין חולת המחוז כדתנן בפ״ג דערכין מכ״מ ה״ז ככל חוקי התורה שעיקרן בטעם והפרטים חקה כמש״כ הרמב״ן כ״פ. וע׳ תוס׳ פסחים ד״ל ע״ב בד״ה התורה. ונראה משום דגזרה התורה שאם לא יגאל המקדיש ומכרה לאחר יוצאת לכהנים ביובל. וא״כ אין כדאי להקונה להשביחה שהרי לא יטול מן הכהנים את השבח. כמו המוכר שדה אחוזה שמקבל השבח מן הבעלים כמש״כ לעיל כ״ה כ״ח. וא״כ אין כדאי לאדם לפדות מן הקדש אלא באופן שלא יעבדה מש״ה איננה שוה אלא בזרע שעורים שא״צ עיבוד רב. וממילא אפילו כשהבעלים גואלין א״צ ליתן יותר רק החומש.","complete":false},{"workId":"Rabbeinu_Bahya_on_Leviticus","unitId":"Rabbeinu_Bahya_on_Leviticus.27.12","commentator":"רבינו בחיי","sourceLine":"רבינו בחיי · Midrash Rabbeinu Bachya [ben Asher]. Warsaw, 1878 · נחלת הכלל · ספריא","chapter":27,"verse":29,"dh":"אבל","text":"הרמב\"ן ז\"ל פירש כי הכתוב הזה על דרך הפשט יאמר כי כל המחרים משלו בין אדם בין בהמה ושדה אחזתו הוא קדש להשם, שהן חרמי כהנים אין להן פדיון, אבל המחרים מאדם שאינו שלו, כגון הנלחמים על אויביהם ונודרין נדר אם נתון תתן את העם הזה בידי והחרמתי את עריהם, בזה ודאי אין דעתו של נודר לתתו לכהנים רק שיהיה הכל אסור בהנאה, וימיתו כל הנמצא בהם כי נתכוין להשמידם ולהכריתם.","complete":false}],"bamidbar":[{"workId":"Or_HaChaim_on_Numbers","unitId":"Or_HaChaim_on_Numbers.1.1","commentator":"אור החיים","sourceLine":"אור החיים · Vocalized Edition · נחלת הכלל · ספריא","chapter":1,"verse":1,"dh":"בְּמִדְבַּר סִינַי וְגוֹ׳.","text":"רַזַ״ל דָּרְשׁוּ (במדבר רבה א:א) הֲבָנוֹת יְקָרוֹת בְּפָסוּק זֶה, וְנִשְׁאַר לְהָעִיר לָמָּה לֹא הִשְׁוָה ה׳ מִדּוֹתָיו יִתְבָּרַךְ בְּשִׁעוּר הַדְּבָרִים, כִּי כְּשֶׁהִזְכִּיר הוֹדָעַת הַמָּקוֹם הִקְדִּים מַחְבֶּרֶת הַכְּלָלוּת שֶׁהוּא מִדְבַּר סִינַי וְאַחַר כָּךְ הִזְכִּיר פְּרַט הַמָּקוֹם וְאָמַר בְּאֹהֶל מוֹעֵד, וּכְשֶׁהִזְכִּיר הוֹדָעַת הַזְּמַן הִקְדִּים זִכְרוֹן פְּרַט הַזְּמַן וְאָמַר בְּאֶחָד לַחֹדֶשׁ הַשֵּׁנִי וְאַחַר כָּךְ הִזְכִּיר מַחְבֶּרֶת כְּלָלוּת הַזְּמַן וְאָמַר בַּשָּׁנָה הַשֵּׁנִית.","complete":true},{"workId":"Haamek_Davar_on_Numbers","unitId":"Haamek_Davar_on_Numbers.1.15","commentator":"העמק דבר","sourceLine":"העמק דבר · ספר תורת אלוהים, וילנא 1879 · נחלת הכלל · ספריא","chapter":1,"verse":22,"dh":"פקודיו במספר שמות לגלגלותם.","text":"האי פקודיו מיותר וכן לגלגלותם. והרי בכל השבטים ליתא וסמך על הא דכתיב בשבט ראובן הראשון. וא״כ למאי כתיב הכי בשבט שמעון. ונראה משום דשבט שמעון מאז עודם במדבר סיני הי׳ בשבטו פורה ראש. וראוים להענש עד שנגלה הדבר בשטים. ע״כ היו בהם טובים ורעים. מש״ה כתיב פקודיו שני אופני פקודים. ואחר שכתיב שנוי בשבטו. חזר הכתוב לכתוב לגלגלותם כיון שיצא לידון בדבר חדש א״א יכול להחזירו לכללו עד שיהי נכתב בפירוש:","complete":true},{"workId":"Ramban_on_Numbers","unitId":"Ramban_on_Numbers.2.1","commentator":"רמב״ן","sourceLine":"רמב״ן · Vocalized Edition · נחלת הכלל · ספריא","chapter":2,"verse":2,"dh":"אִישׁ עַל דִּגְלוֹ בְאֹתֹת–","text":"כָּל דֶּגֶל יִהְיֶה לוֹ מַפָּה צְבוּעָה תְּלוּיָה בּוֹ, צִבְעוֹ שֶׁל זֶה לֹא כְּצִבְעוֹ שֶׁל זֶה, צֶבַע כָּל אֶחָד כְּעֵין אַבְנוֹ הַקְּבוּעָה בַּחֹשֶׁן, וּמִתּוֹךְ כָּךְ כָּל אֶחָד מַכִּיר אֶת דִּגְלוֹ - לְשׁוֹן רַשִׁ״י (רש״י על במדבר ב׳:ב׳). וְכָתַב ר״א (אבן עזרא על במדבר ב׳:ב׳):","complete":false},{"workId":"Rabbeinu_Bahya_on_Numbers","unitId":"Rabbeinu_Bahya_on_Numbers.3.1","commentator":"רבינו בחיי","sourceLine":"רבינו בחיי · Midrash Rabbeinu Bachya [ben Asher]. Warsaw, 1878 · נחלת הכלל · ספריא","chapter":3,"verse":1,"dh":"ואלה תולדות אהרן ומשה.","text":"הזכיר משה לפי שלמדם תורה, כי תלמידיו של אדם הן הן תולדותיו העקריות, והיו תולדות אהרן בהולדה ותולדות משה בלמוד התורה, ולזה הזכיר הר סיני שבו נתנה תורה, ואמר ביום דבר ה' את משה בהר סיני. וכן דרשו רז\"ל כל המלמד את בן חברו תורה מעלה עליו הכתוב כאלו ילדו. ואחרי כן הזכיר ואלה שמות בני אהרן לבאר שהיו בנים לאהרן לבדו, ולזה הזכיר ארבעתם בשמותם. ואחרי כן הזכיר שלישית אלה שמות בני אהרן הכהנים המשוחים אשר מלא וגו'.","complete":true},{"workId":"Tur_HaArokh_on_Numbers","unitId":"Tur_HaArokh_on_Numbers.3.4","commentator":"טור הארוך","sourceLine":"טור הארוך · Perush al ha-Torah, Hanover, 1838 · נחלת הכלל · ספריא","chapter":3,"verse":14,"dh":"וידבר י\"י אל משה במדבר סיני.","text":"כתב הרמב\"ן בעבור שאמר למעלה ביום דבר י\"י אל משה בהר סיני חזר ואמר כי לא היתה צוואת הפקידה של הלויים בהר סיני כי בהיות (בחירת) תולדות בני אהרן לבדם היתה בהר סיני ביום צוותו על מעשה המשכן אבל הלויים לא נצטווה בבחירתם אלא במדבר סיני. והנה לא היו הלויים כשאר השבטים כי מבן חודש ומעלה לא היו רק כ\"ב אלף ומבן ל' שנה ח' אלפים ועדיין לא נשאו הארון שנאמר שהיה הארון מכלה בהם והטעם מפני שלא היו בעבודת פרך ולכך לא היו גם כן בברכת כן ירבה וכן יפרוץ ואולי היה מפני כעסו של יעקב עליהם כי גם שמעון שהיה עתה מרובה באוכלסין נתמעט בכניסתו לארץ לכ\"ב אלף:","complete":true}],"nasso":[{"workId":"Haamek_Davar_on_Numbers","unitId":"Haamek_Davar_on_Numbers.4.20","commentator":"העמק דבר","sourceLine":"העמק דבר · ספר תורת אלוהים, וילנא 1879 · נחלת הכלל · ספריא","chapter":4,"verse":23,"dh":"כל הבא לצבא צבא.","text":"בבני קהת ומררי כתיב כל הבא לצבא. וכאן כתיב לצבא צבא. ולאו דבר ריק הוא. והענין דיש לדעת דבני גרשון היו מיוחדים במעלה בשיר שבשעת עבודה. כמו בימי דוד ושלמה היה אסף מבני גרשון הראש קודם להימן מבני קהת ובביאורי על הספרי הוכחתי הכי מברייתא שם. וזהו משמעות לצבוא צבא. דצבא לחוד משמעו איזה התמנות של כל אדם בביתו או בעירו. ועוד משמעו צבא קיבוץ אנשים לד״א כמו הנשים הצובאות. ולצבוא צבא משמעו מצביאים את הקיבוץ. והיינו עבודת השיר דבקיבוץ כדאיתא בערכין פ״ב. וברבה איתא לצבוא צבא אלו שוערים לעבוד עבודה אלו משוררים. והיינו דכתיב כאן לעבוד עבודה. ולא כתיב לעבודה כמו בבני מררי. אלא כדרשת הגמ׳ בערכין דף י״א במקרא עבודת עבודה.","complete":false},{"workId":"Ramban_on_Numbers","unitId":"Ramban_on_Numbers.5.1","commentator":"רמב״ן","sourceLine":"רמב״ן · Vocalized Edition · נחלת הכלל · ספריא","chapter":5,"verse":2,"dh":"וִישַׁלְּחוּ מִן הַמַּחֲנֶה–","text":"אַחַר שֶׁהֵקִים אֶת הַמִּשְׁכָּן, צִוָּה בְּשִׁלּוּחַ הַטְּמֵאִים מִן הַמַּחֲנֶה, שֶׁיִּהְיֶה הַמַּחֲנֶה קָדוֹשׁ וְרָאוּי שֶׁתִּשְׁרֶה בּוֹ שְׁכִינָה, וְהִיא מִצְוָה נוֹהֶגֶת מִיָּד וּלְדוֹרוֹת. וּבַעֲבוּר שֶׁמָּנָה יִשְׂרָאֵל לְמִשְׁפְּחוֹתָם לְבֵית אֲבוֹתָם, וְהִבְדִּיל מֵהֶם עֵרֶב רַב אֲשֶׁר בְּתוֹכָם, הִשְׁלִים בַּאֲשַׁם הַגְּזֵלוֹת דִּין הַגּוֹזֵל אֶת הַגֵּר:","complete":true},{"workId":"Kli_Yakar_on_Numbers","unitId":"Kli_Yakar_on_Numbers.5.4","commentator":"כלי יקר","sourceLine":"כלי יקר · Vocalized Edition · נחלת הכלל · ספריא","chapter":5,"verse":12,"dh":"אִישׁ אִישׁ כִּי תִשְׂטֶה אִשְׁתּוֹ וְגוֹ׳.","text":"סְמִיכוּת פָּרָשָׁה זוֹ לַפָּסוּק הַקּוֹדֵם פֵּרֵשׁ רַשִׁ״י, אִם אַתָּה מְעַכֵּב מַתְּנוֹת הַכֹּהֵן חַיֶּיךָ שֶׁתִּצְטָרֵךְ לָבֹא אֵלָיו לְהָבִיא לוֹ אֶת הַסּוֹטָה. פֵּרוּשׁ לְפֵרוּשׁוֹ לְפִי שֶׁהַמְּעַכֵּב הַמַּתָּנוֹת יָבֹא לִידֵי עֹנִי, כְּמוֹ שֶׁפֵּרֵשׁ רַשִׁ״י לְמַעְלָה (ה י), וְאָמְרוּ רז״ל (סוטה ד:): כָּל הַבָּא עַל אִשָּׁה זוֹנָה לְסוֹף מְבַקֵּשׁ כִּכַּר לֶחֶם וְאֵינוֹ מוֹצֵא, שֶׁנֶּאֱמַר (משלי ו כו): ״כִּי בְעַד אִשָּׁה זוֹנָה עַד כִּכַּר לָחֶם״. וּכְשֶׁהָאִשָּׁה רוֹאָה שֶׁבַּעְלָהּ בָּא לִידֵי עֹנִי הִיא חוֹשַׁדְתּוֹ שֶׁבָּא לִידֵי עֹנִי מֵחֲמַת שֶׁהָיָה רוֹעֵה זוֹנוֹת, כְּמוֹ שֶׁנֶּאֱמַר (שם כט ג):","complete":false},{"workId":"Rabbeinu_Bahya_on_Numbers","unitId":"Rabbeinu_Bahya_on_Numbers.7.4","commentator":"רבינו בחיי","sourceLine":"רבינו בחיי · Midrash Rabbeinu Bachya [ben Asher]. Warsaw, 1878 · נחלת הכלל · ספריא","chapter":7,"verse":1,"dh":"ובמדרש","text":"ויהי ביום כלות משה, זהו שאמר הכתוב (משלי כ״ז:י״ח) נוצר תאנה יאכל פריה ושומר אדוניו יכובד, אין הקב\"ה מקפח שכר כל בריה, אלא בכל מה שהאדם יגע ונותן נפשו על הדבר אין הקב\"ה מקפח שכרו, לכך נאמר נוצר תאנה וגו'. תדע לך ששלמה בנה בית המקדש ובשביל שנתן דוד נפשו עליו נקרא על שמו שנאמר (תהילים ל׳:א׳) מזמור שיר חנוכת הבית לדוד, לשלמה אין כתיב כאן אלא לדוד. וכן אתה מוצא במשכן שבשביל שנתן משה נפשו על המשכן אמר הקב\"ה איני כותבו אלא על שמו שנאמר ויהי ביום כלות משה, הוי אומר נוצר תאנה יאכל פריה.","complete":false},{"workId":"Or_HaChaim_on_Numbers","unitId":"Or_HaChaim_on_Numbers.7.15","commentator":"אור החיים","sourceLine":"אור החיים · Vocalized Edition · נחלת הכלל · ספריא","chapter":7,"verse":42,"dh":"אֶלְיָסָף בֶּן דְּעוּאֵל.","text":"יִרְמֹז לֶהֱיוֹת שֶׁנֶּאֶסְפוּ לְעָרֵיהֶם תְּחִלָּה עַל פִּי ה׳ כָּאָמוּר, זוּלַת גִּבּוֹרֵי חַיִל שֶׁעָבְרוּ כָּל חָלוּץ וְגוֹ׳, וְהוּא אָמְרוֹ אֶל יָסָף. עוֹד עַל פִּי דִּבְרֵיהֶם זִכְרוֹנָם לִבְרָכָה שֶׁאֶרֶץ סִיחוֹן וְעוֹג לֹא הָיְתָה בִּכְלַל מַתְּנַת אֶרֶץ יִשְׂרָאֵל שֶׁנָּתַן ה׳ לְאַבְרָהָם, כְּמוֹ שֶׁאָמְרוּ בְּסִפְרֵי (חלק ב פיסקא רצט) וְזֶה לְשׁוֹנָם: פְּרָט לְעֵבֶר הַיַּרְדֵּן שֶׁנָּטַלְתָּ מֵעַצְמְךָ, עַד כָּאן.","complete":false}],"behaalotcha":[{"workId":"Ramban_on_Numbers","unitId":"Ramban_on_Numbers.8.1","commentator":"רמב״ן","sourceLine":"רמב״ן · Vocalized Edition · נחלת הכלל · ספריא","chapter":8,"verse":2,"dh":"בְּהַעֲלֹתְךָ–","text":"לָמָּה נִסְמְכָה פָּרָשַׁת מְנוֹרָה לַחֲנֻכַּת הַנְּשִׂיאִים? לְפִי שֶׁכְּשֶׁרָאָה אַהֲרֹן חֲנֻכַּת הַנְּשִׂיאִים, חָלְשָׁה דַעְתּוֹ שֶׁלֹּא הָיָה עִמָּהֶם בַּחֲנֻכָּה, לֹא הוּא וְלֹא שִׁבְטוֹ; אָמַר לוֹ הקב״ה: חַיֶּיךָ, שֶׁלְּךָ גְּדוֹלָה מִשֶּׁלָּהֶם, שֶׁאַתָּה מַדְלִיק וּמֵטִיב אֶת הַנֵּרוֹת בֹּקֶר וָעֶרֶב, לְשׁוֹן רַשִׁ״י (רש״י על במדבר ח׳:ב׳) מִמִּדְרַשׁ אַגָּדָה. וְלֹא נִתְבָּרֵר לִי לָמָּה נִחֲמוֹ בְּהַדְלָקַת הַנֵּרוֹת וְלֹא נִחֲמוֹ בִּקְטֹרֶת בֹּקֶר וָעֶרֶב, שֶׁשִּׁבְּחוֹ בּוֹ הַכָּתוּב:","complete":false},{"workId":"Haamek_Davar_on_Numbers","unitId":"Haamek_Davar_on_Numbers.8.23","commentator":"העמק דבר","sourceLine":"העמק דבר · ספר תורת אלוהים, וילנא 1879 · נחלת הכלל · ספריא","chapter":8,"verse":15,"dh":"וטהרת אותם.","text":"חזר להזהיר על הטהרה. כי מעלת האדם כשם שהיא מגביה לב האדם בדרכי ה׳. כך יש להזהר שלא תוסיף מכשול ע״י גאות וחה״ש וגם כל הגדול מחבירו יצרו גדול. ונמצא הקריבה לקדושה גורם לטומאה וכדבר חגי הנביא ואשר יקריבו שם טמא הוא וכמו שביארנו בס׳ ויקרא ו׳ י״א וכמו שאירע באמת אח״כ לקרח והבאים אחריו מבני לוי. שגדולתם היא הכשילתם. ע״כ באה אזהרה דלאחר שיעבדו את א״מ יהיו נזהרים בטהרה לפי ערכם:","complete":true},{"workId":"Tur_HaArokh_on_Numbers","unitId":"Tur_HaArokh_on_Numbers.9.1","commentator":"טור הארוך","sourceLine":"טור הארוך · Perush al ha-Torah, Hanover, 1838 · נחלת הכלל · ספריא","chapter":9,"verse":1,"dh":"בשנה השנית לצאתם מארץ מצרים.","text":"אין מוקדם ומאוחר בתורה שזו הפרשה קדמה לפרשה שבראש הספר ולכך לא התחיל בזו הפרשה שבגנותן דיבר הכתוב שלא עשו במדבר אלא זה הפסח בשביל שלא מלו בשביל שלא נשבה להם רוח צפונית וזה היו גנותן שקלקלתם בענין המרגלים גרם להם שנתנדו ולא נשבה להם רוח צפונית וכן נמי נאסרו בכל הקדשים שמילת זכרים מעכבת לאכול בקדשים.","complete":false},{"workId":"Or_HaChaim_on_Numbers","unitId":"Or_HaChaim_on_Numbers.9.23","commentator":"אור החיים","sourceLine":"אור החיים · Vocalized Edition · נחלת הכלל · ספריא","chapter":9,"verse":17,"dh":"וּלְפִי הֵעָלוֹת.","text":"אָמַר וָא״ו בִּתְחִלַּת עִנְיָן, לוֹמַר כִּי עִנְיַן הֶעָנָן אֲשֶׁר עַל הַמִּשְׁכָּן הָיָה מְשַׁמֵּשׁ שְׁנֵי דְּבָרִים: אֶחָד הוּא לְמִכְסֶה עַל הָאֹהֶל לְכָבוֹד וּלְתִפְאָרֶת, וְהוּא מַאֲמַר כִּסָּה הֶעָנָן אֶת הַמִּשְׁכָּן לְאֹהֶל (עַל) הָעֵדוּת, וְהוֹסִיף עוֹד וְאָמַר וּלְפִי וְגוֹ׳, פֵּרוּשׁ וְעוֹד הָיָה הֶעָנָן לְצֹרֶךְ זֶה, שֶׁלְּפִי הֵעָלוֹתוֹ יִסְעוּ בְּנֵי יִשְׂרָאֵל כְּדֵי שֶׁיֵּדְעוּ זְמַן הַנְּסִיעָה וּזְמַן הַחֲנִיָּה.","complete":true},{"workId":"Sforno_on_Numbers","unitId":"Sforno_on_Numbers.10.6","commentator":"ספורנו","sourceLine":"ספורנו · ובלכתך בדרך · נחלת הכלל · ספריא","chapter":10,"verse":11,"dh":"בחדש השני בעשרים בחדש.","text":"אחר שעשו הטמאים פסח שני בי\"ד בחדש נעשו חצוצרות ובהם נועדו העדה והנשיאים למשה והודיענו סדר מסעם על ידי חצוצרות וסדר חצוצרות במקדש ובמלחמה ובכן נעלה הענן ללכת אל קדש ברנע שהיא העיר הראשונה בארץ ישראל שהיו פוגעים באותו הדרך שהיה דרך המדבר הגדול והנורא כאמרו ונסע מחורב ונלך את כל המדבר הגדול והנורא ונבא עד קדש ברנע:","complete":true},{"workId":"Rabbeinu_Bahya_on_Numbers","unitId":"Rabbeinu_Bahya_on_Numbers.10.7","commentator":"רבינו בחיי","sourceLine":"רבינו בחיי · Midrash Rabbeinu Bachya [ben Asher]. Warsaw, 1878 · נחלת הכלל · ספריא","chapter":10,"verse":35,"dh":"ויהי בנסוע הארון.","text":"הפסיק כאן בשני פסוקים אלה והיה ראוי להדביק ויהי העם כמתאוננים עם בנסעם מן המחנה מפני שישראל אחר שנסעו מהר סיני שהיה קרוב לישוב ונתרחקו ממנו ובאו עתה בתוך המדבר הגדול והנורא דרך שלשת ימים היו מצטערים מאד ומתאוננים על פחד הדרך כי אמרו איך נוכל לסבול הצער והענוי, וא\"כ כיון שהכל ספור אחד וענין אחד לא היה ראוי שיפסיק ביניהם בפרשת ויהי בנסוע.","complete":true}],"shlach":[{"workId":"Haamek_Davar_on_Numbers","unitId":"Haamek_Davar_on_Numbers.13.1","commentator":"העמק דבר","sourceLine":"העמק דבר · ספר תורת אלוהים, וילנא 1879 · נחלת הכלל · ספריא","chapter":13,"verse":2,"dh":"שלח לך אנשים וגו׳.","text":"פרש״י לדעתך אני איני מצוה לך כו׳. ודאי לשון שלח לך אינו במשמע אלא כמו קח לך. לך לך. שהוא מצוה כמשמעו. אלא ההכרח לפרש הכי כמבואר בספר דברים שמתחלה אך המה ישראל בקשו זאת. אבל מכ״מ א״א לעקם גם זה המקרא לגמרי. ואין מקרא יוצא מידי פשוטו. עוד יש לשום לב מה ראו ישראל בכאן לזה ולא בהיותם בחורב. אלא כך הענין. דודאי לפי הליכות עולם הטבע היה השלוח נחוץ לראות איך ובאיזה צד לכבוש הארץ. וכמש״כ הרמב״ן ז״ל וכמבואר בלשון ישראל שאמרו נשלחה אנשים לפנינו ויחפרו לנו את הארץ. וישיבו אותנו דבר. את הדרך אשר נעלה בה. ואת הערים אשר נבא אליהן. הרי לא בקשו לדעת הטובה היא אם רעה. ועוד כמה דברים אם ראוי ליכנס לא״י או לא.","complete":false},{"workId":"Rabbeinu_Bahya_on_Numbers","unitId":"Rabbeinu_Bahya_on_Numbers.13.17","commentator":"רבינו בחיי","sourceLine":"רבינו בחיי · Midrash Rabbeinu Bachya [ben Asher]. Warsaw, 1878 · נחלת הכלל · ספריא","chapter":13,"verse":22,"dh":"וע\"ד","text":"המדרש היתה חברון מבונה אחד משבעה בצען. ובאור זה כי חברון היתה פסולת של ארץ ישראל ולכך הקצוה לבית הקברות, והיתה מבונה על אחת משבעה בצען שהיא עיקר מלכות מצרים שנאמר (ישעיהו ל׳:ד׳) כי היו בצען שריו, וכתיב במצרים (בראשית י״ג:י׳) כגן ה' כארץ מצרים, ובא הכתוב להודיענו בזה שבחה של ארץ ישראל.","complete":true},{"workId":"Tur_HaArokh_on_Numbers","unitId":"Tur_HaArokh_on_Numbers.14.7","commentator":"טור הארוך","sourceLine":"טור הארוך · Perush al ha-Torah, Hanover, 1838 · נחלת הכלל · ספריא","chapter":14,"verse":9,"dh":"סר צלם מעליהם.","text":"פי' רש\"י מגנם וחוזקם כי הכשרים שבהם מתו. ד\"א צלו של המקום סר מעליהם. והרמב\"ן כתב ר' אברהם פי' צלם מגן וצנה אשר הם צל על הנלחמים פי' כי נפל פחדינו עליהם ולא יקחו מגן וצנה להחלץ ולהלחם כנגדנו. ויתכן שרומז הכתוב למה שנודע כי בליל החתימה לא יהיה צל לראש האיש אשר ימות בשנה ההיא ולכך אמר סר צלם מעליהם כי נגזר עליהם מיתה וה' אתנו אל תיראום. או ירמוז לשרי מעלה שאין אומה נופלת עד שיפול השר שלה תחלה כענין שנאמר יפקוד השם על צבא המרום במרום ואחר כך על מלכי האדמה באדמה פי' סר הכח אשר בצלו יחיה וה' אשר משפיל אותם אתנו אל תיראום:","complete":true},{"workId":"Ramban_on_Numbers","unitId":"Ramban_on_Numbers.14.14","commentator":"רמב״ן","sourceLine":"רמב״ן · Vocalized Edition · נחלת הכלל · ספריא","chapter":14,"verse":28,"dh":null,"text":"וְטַעַם אִם לֹא כַּאֲשֶׁר דִּבַּרְתֶּם בְּאָזְנָי – אִם כַּאֲשֶׁר דִּבַּרְתֶּם כֵּן לֹא אֶעֱשֶׂה לָכֶם, כְּטַעַם תְּמִיהָה. וְכֵן דֶּרֶךְ הַלָּשׁוֹן: ״לֹא אֶל עַמִּים רַבִּים עִמְקֵי שָׂפָה וְכִבְדֵי לָשׁוֹן אֲשֶׁר לֹא תִשְׁמַע דִּבְרֵיהֶם, אִם לֹא אֲלֵיהֶם שְׁלַחְתִּיךָ הֵמָּה יִשְׁמְעוּ אֵלֶיךָ״ (יחזקאל ג ו), וְכֵן ״אִם לֹא כַּאֲשֶׁר דִּמִּיתִי כֵּן הָיָתָה״ (ישעיהו יד כד):","complete":true}],"korach":[{"workId":"Rabbeinu_Bahya_on_Numbers","unitId":"Rabbeinu_Bahya_on_Numbers.16.2","commentator":"רבינו בחיי","sourceLine":"רבינו בחיי · Midrash Rabbeinu Bachya [ben Asher]. Warsaw, 1878 · נחלת הכלל · ספריא","chapter":16,"verse":1,"dh":"שלמה","text":"המלך עליו השלום יזהיר בכאן האדם שישתדל בטובת חבירו ואל ישתדל ברעתו ונזקו, לפי שהוא מעותד שיאכל פרי מעשיו וישתלם לו ככל אשר יעשה מדה כנגד מדה, וכל אחד ואחד יאכל מה שזרע וילקוט פרי מה שנטע בין צדיק בין רשע, הוא שכתוב בצדיק (ישעיהו ג׳:י׳-י״א) אמרו צדיק כי טוב כי פרי מעלליהם יאכלו, וכתיב ברשע (שם) אוי לרשע רע כי גמול ידיו יעשה לו. ולשון שוחר מענין תפלה, כלשון (משלי ח׳:י״ז) ומשחרי ימצאוני.","complete":false},{"workId":"Tur_HaArokh_on_Numbers","unitId":"Tur_HaArokh_on_Numbers.16.10","commentator":"טור הארוך","sourceLine":"טור הארוך · Perush al ha-Torah, Hanover, 1838 · נחלת הכלל · ספריא","chapter":16,"verse":15,"dh":"אל תפן אה מנחתם.","text":"פירש\"י לפי פשוטו על הקטרת שהם מקריבים למחר. וכתב הרמב\"ן ואינו נכון לפי שעל דתן ואבירם אמר כן שחרה לו על דבריהם והם לא היו בתוך העדה הנועדים על ה' להקטיר קטרת. אבל פשוטו לפי שהיו רוצים בכהונה להקריב קרבן אמר משה אל תפן אל מנחתם אל קרבן שיקריבו לפניך ואל תפלה שיתפללו לך כי כל הקרבנות גם תפלה יקראו מנחה בכתובים וכן אמר אונקלוס קרבנהון איזה דבר שיקריבו לפניך:","complete":true},{"workId":"Or_HaChaim_on_Numbers","unitId":"Or_HaChaim_on_Numbers.16.37","commentator":"אור החיים","sourceLine":"אור החיים · Vocalized Edition · נחלת הכלל · ספריא","chapter":16,"verse":21,"dh":"הִבָּדְלוּ מִתּוֹךְ וְגוֹ׳.","text":"לֹא עַל מֹשֶׁה וְאַהֲרֹן הוּא אוֹמֵר, כִּי לְאֵלֶּה לֹא תִּפְגַּע מִדַּת הַדִּין הֲגַם שֶׁיִּהְיוּ בְּתוֹךְ הָעֵדָה הַכָּלָה חָס וְשָׁלוֹם, וְזֶה לְךָ הָאוֹת – אַהֲרֹן שֶׁהָיָה בְּתוֹךְ עֲדַת קֹרַח וְנִבְקְעָה הָאֲדָמָה תַּחְתֵּיהֶם וְלֹא נִפְגַּע. אֶלָּא כַּוָּנַת מַאֲמַר ה׳ הוּא עַל הַצַּדִּיקִים שֶׁהָיוּ בְּתוֹךְ הָעֵדָה, כִּיהוֹשֻׁעַ וְכָלֵב וּשְׁאָר הַצַּדִּיקִים וּבְנֵי בָּתֵּיהֶם שֶׁל מֹשֶׁה וְאַהֲרֹן וְשֶׁל שְׁאָר הַצַּדִּיקִים.","complete":false},{"workId":"Ramban_on_Numbers","unitId":"Ramban_on_Numbers.17.4","commentator":"רמב״ן","sourceLine":"רמב״ן · Vocalized Edition · נחלת הכלל · ספריא","chapter":17,"verse":10,"dh":"הֵרֹמּוּ מִתּוֹךְ הָעֵדָה הַזֹּאת–","text":"לֹא הֲבִינוֹתִי טַעַם הַכָּתוּב הַזֶּה וַחֲבֵרוֹ לְמַעְלָה ״הִבָּדְלוּ מִתּוֹךְ הָעֵדָה הַזֹּאת״ (במדבר ט״ז:כ״א), כִּי יֵשׁ בָּאֱלֹהִים לְהָמִית בַּדֶּבֶר רַבִּים סְבִיב צַדִּיק אֶחָד וְהוּא לְבַדּוֹ נִשְׁאָר, כַּאֲשֶׁר הָיָה בִּבְכוֹרֵי מִצְרַיִם. וְכֵן הָיָה בְּכָל הַמַּגֵּפוֹת, שְׁלֹשָׁה יְשֵׁנִים בְּטַלִּית אַחַת, הַשְּׁנַיִם מֵתִים וְהָאֶמְצָעִי נִמְלָט.","complete":false},{"workId":"Haamek_Davar_on_Numbers","unitId":"Haamek_Davar_on_Numbers.17.26","commentator":"העמק דבר","sourceLine":"העמק דבר · ספר תורת אלוהים, וילנא 1879 · נחלת הכלל · ספריא","chapter":17,"verse":17,"dh":"וקח מאתם.","text":"ויתנו אליך מיבעי. וכמו דכתיב במעשה ויתנו אליו וגו׳ אלא משמעות קח בע״כ כדאי׳ בב״ב דף ח׳ ב׳ עה״פ והם יקחו את הזהב. וכמש״כ ריש פרשת תרומה. וכאשר לא נצרך מטות אלא לקטני אמנה בדבר משה בשם ה׳. ואם כן היו נראים נותני המטות המה הנשיאים כאלו המה אינם מאמינים ח״ו. ובאמת לא עלה מחשבה זרה זו בלבבם. ולא היו מרוצים ליתן. ע״כ היה הצווי שיקח בע״כ. דאע״ג שלא נצרך המטות בשבילם הלא נצרך בשביל אחרים באותו הדור ולדורות כמו שיבואר. וע׳ להלן כ״א:","complete":true},{"workId":"Rashbam_on_Numbers","unitId":"Rashbam_on_Numbers.17.14","commentator":"רשב״ם","sourceLine":"רשב״ם · רשב\"ם על במדבר, דעת · נחלת הכלל · ספריא","chapter":17,"verse":27,"dh":null,"text":"כל הקרב הקרב - כל איש ואיש אשר יקרב אל המשכן לשומרו, או אל כלי המשכן עם הלוים ימות, שעדיין לא התרה בם הקדוש ברוך הוא שעדיין לא נכתב והזר הקרב יומת - ולכך הוא מזהירם בפרשה זו וזר לא יקרב אליכם, והזר הקרב יומת - שמכאן ואילך לא יקרבו כלל ולא ימותו, שאפילו בפרשה אמור אל הכהנים שכתוב שם: דבר אל אהרן לאמר איש מזרעך אשר יהיה בו מום לא יגש להקריב לחם ה' - שם לא פסל אלא בעלי מומים אבל זרים לא פסל ומה שפסל שם בפרשת: אמור אליהם כל איש אשר יקרב וגו' - באובד בטומאת הגוף מדבר, אבל בעבודת זרים במשכן ובכליו לא ראינו עדיין חיוב מיתה.","complete":true}],"chukat":[{"workId":"Tur_HaArokh_on_Numbers","unitId":"Tur_HaArokh_on_Numbers.19.1","commentator":"טור הארוך","sourceLine":"טור הארוך · Perush al ha-Torah, Hanover, 1838 · נחלת הכלל · ספריא","chapter":19,"verse":2,"dh":"זאת חקת התורה.","text":"פי' רש\"י שנאמר בה חוקה לפי שאומות העולם מונין בה את ישראל וכו'. וכתב הרמב\"ן ומה שמונין יותר בפרה מבשאר קרבנות שמכפרים ויש מהם שמטהרים כקרבנות הזב והיולדת לפי שהיא נעשה בחוץ ונראה להם שהיא נזבחת לשעירים על פני השדה. והפרשה הזאת תשלים בתורת כהנים ונכתבה כאן אחר מתנות כהונה לומר שטהרתן של ישראל תהי' ע\"י הכהנים. ופי':","complete":true},{"workId":"Ramban_on_Numbers","unitId":"Ramban_on_Numbers.19.8","commentator":"רמב״ן","sourceLine":"רמב״ן · Vocalized Edition · נחלת הכלל · ספריא","chapter":19,"verse":20,"dh":"אֶת מִקְדַּש ה' טִמֵּא–","text":"הִזְכִּיר הַכָּתוּב הַכָּרֵת הַזֶּה בִּסְתָם וְאָמַר ״אֶת מִשְׁכַּן ה' טִמֵּא״ (לעיל יג), בַּעֲבוּר שֶׁכְּבָר הִזְהִיר בַּמִּקְדָּשׁ מִן הַטֻּמְאָה, כְּמוֹ שֶׁאָמַר: ״בְּכָל קֹדֶשׁ לֹא תִגָּע וְאֶל הַמִּקְדָּשׁ לֹא תָבֹא״ (ויקרא יב ד), כִּי הִזְכִּיר שָׁם בַּטֻּמְאָה הַקַּלָּה כָּאִשָּׁה הַיּוֹלֶדֶת בִּימֵי טֹהַר שֶׁהוּא בְּתוֹלַדְתָּהּ, וְהוּא הַדִּין בְּכָל הַטְּמֵאִים. וּכְבָר הִזְכִּיר גַּם כֵּן הַטְּבִילָה: ״וְאִם לֹא יְכַבֵּס וּבְשָׂרוֹ לֹא יִרְחָץ וְנָשָׂא עֲוֹנוֹ״ (שם יז טז), כְּלוֹמַר שֶׁיִּשָּׂא עֲוֹנוֹ בְּעָבְרוֹ עַל הַמֻּזְהָר מִמֶּנּוּ.","complete":false},{"workId":"Kli_Yakar_on_Numbers","unitId":"Kli_Yakar_on_Numbers.20.9","commentator":"כלי יקר","sourceLine":"כלי יקר · Vocalized Edition · נחלת הכלל · ספריא","chapter":20,"verse":8,"dh":"קַח אֶת הַמַּטֶּה וְהַקְהֵל אֶת הָעֵדָה וְגוֹ׳.","text":"אִם צִוָּהוּ ה׳ לְדַבֵּר אֶל הַסֶּלַע אִם כֵּן מַטֶּה זֶה לָמָּה לוֹ, מִדְּלָא קָאָמַר ״קַח אֶת מַטְּךָ״ וְאָמַר ״אֶת הַמַּטֶּה״, שְׁמַע מִנַּהּ בְּמַטֶּה יָדוּעַ הוּא מְדַבֵּר. וּמַה שֶּׁאָמַר ״מִלִּפְנֵי ה׳״, וְכִי מַטֵּה מֹשֶׁה עָמַד לִפְנֵי ה׳? וְלָמָּה קְרָאָם ״מוֹרִים״ דַּוְקָא בִּתְלוּנָּה זוֹ? וְהִנֵּה בְּמָהוּת חֵטְא זֶה בָּאוּ אַחַת עֶשְׂרֵה דֵּעוֹת, זְכָרָם מַהֲרִי״א בְּסִפְרוֹ, וְשָׁם תִּמְצָא דֵּעוֹת הַרְבֵּה רְחוֹקִים מִפְּשׁוּטוֹ. וְעַתָּה הַבֵּט יָמִין וּרְאֵה וְלִבְּךָ תָּשִׂית לְדַעְתִּי.","complete":true},{"workId":"Or_HaChaim_on_Numbers","unitId":"Or_HaChaim_on_Numbers.20.33","commentator":"אור החיים","sourceLine":"אור החיים · Vocalized Edition · נחלת הכלל · ספריא","chapter":20,"verse":14,"dh":"אָחִיךָ יִשְׂרָאֵל אַתָּה יָדַעְתָּ וְגוֹ׳.","text":"טַעַם אָמְרוֹ אָחִיךָ, גַּם אָמְרוֹ אַתָּה יָדַעְתָּ, לוֹמַר כִּי תְּלָאָה זוֹ לֹא נִסְבְּבָה מִמֶּנִּי אֶלָּא מֵאֲבוֹתֵינוּ, וַאֲנִי וְאַתָּה אַחִים שָׁוִים בַּדָּבָר, שֶׁשְּׁטָר זֶה שֶׁל הַתְּלָאָה הָיָה כָּתוּב עַל אָבִינוּ וְאֶחָד מִן הָאַחִים פְּרָעוֹ. וְתִמְצָא שֶׁאָמְרוּ זִכְרוֹנָם לִבְרָכָה (בראשית רבה פב) בְּפָסוּק ״וַיֵּלֶךְ אֶל אֶרֶץ״ (בראשית לו,ח) וְזֶה לְשׁוֹנָם: מִפְּנֵי הַחוֹב, שֶׁלֹּא רָצָה לִפְרֹעַ חוֹב אָבִיו, עַד כָּאן.","complete":true},{"workId":"Haamek_Davar_on_Numbers","unitId":"Haamek_Davar_on_Numbers.20.33","commentator":"העמק דבר","sourceLine":"העמק דבר · ספר תורת אלוהים, וילנא 1879 · נחלת הכלל · ספריא","chapter":20,"verse":23,"dh":"על גבול ארץ אדום.","text":"היינו בקצה מזרחית דרומית מש״ה כשיצאו מגבול אדום בדרום היה להם עוד לסבוב מזרח ארץ אדום כמש״כ להלן כ״א ד׳. והא שפירש הכתוב כאן דהר ההר הוא על גבול אדום יותר ממקרא הקודם פרש״י שבא לעונש על שנתקרבו לאדום. והיינו משום שישבו בקדש ונתקרבו עמם יותר מן הצורך. או במה ששלחו שנית למלך אדום מדעת עצמם. ולפי הפשט בא הכתוב ללמדנו שלא נקבר אהרן באדמת אדום כי אם על הגבול והיה הפקר וידוע בפרק יש נוחלין שגנאי לצדיק שיהא נקבר באדמה שאינה שלו:","complete":true},{"workId":"Rabbeinu_Bahya_on_Numbers","unitId":"Rabbeinu_Bahya_on_Numbers.21.10","commentator":"רבינו בחיי","sourceLine":"רבינו בחיי · Midrash Rabbeinu Bachya [ben Asher]. Warsaw, 1878 · נחלת הכלל · ספריא","chapter":21,"verse":10,"dh":"ויסעו בני ישראל ויחנו באובות.","text":"אמרו במדרש שנעשו אויבים למקום. ויחנו בעיי העברים שהיו מלאים עברה. ויחנו בנחל זרד, לא היה הנחל אלא מלא זרת ולא יכלו לעברו ל\"ח שנה, וזהו שכתוב (דברים ב׳:י״ד) ועברו לכם את נחל זרד , וכתיב (שם) והימים אשר הלכנו מקדש ברנע עד אשר עברנו את נחל זרד שלשים ושמנה שנה. משם נסעו ויחנו מעבר ארנון, שנתרצה להם הקב\"ה, עד כאן. ונראה לומר כי מה שנאמר נתרצה להם הקב\"ה שכוון בזה לפי מה שאמר מעבר ארנון והיה ראוי לומר ויחנו בעבר ארנון, אבל אמר מעבר כי נסתלקה מהם אותה עברה שכל ל\"ח שנה היו נזופין, לכך אמר שנתרצה להם הקב\"ה. וכן מצינו שמיד בא הדבור למשה ואמר לו הקב\"ה מיד (שם) קומו סעו ועברו את נחל ארנון, וכענין שכתוב באלה הדברים.","complete":true}],"balak":[{"workId":"Tur_HaArokh_on_Numbers","unitId":"Tur_HaArokh_on_Numbers.22.1","commentator":"טור הארוך","sourceLine":"טור הארוך · Perush al ha-Torah, Hanover, 1838 · נחלת הכלל · ספריא","chapter":22,"verse":2,"dh":"וירא בלק בן צפור וגו' ויגר מואב מפני העם מאד כי רב הוא.","text":"ומואב היה קטן בגוים כי לא היה קדמון כמו הכנענים והאמורים וזולתם שהיו מימי נח לכך היו יראים מפני בני ישראל שהיו עם רב. והנה ידעו שלא באו לירש ארצם שידעו מה שנצטוו אל תצר את מואב וגם כי שלחו להם אעברה בארצך כאשר שלחו לסיחון אלא היו יראים שיחריבו ארצם בעוברם עליהם וזהו ששלחו לזקני מדין כלחוך השור אע\"פ שלא ילכדו את ארצנו ילחכו ברובם את כל סביבותינו כלחוך השור וילכדו את כל סביבותינו כאשר עשו למלכי האמורי ויתנו אותנו למס עובד:","complete":true},{"workId":"Or_HaChaim_on_Numbers","unitId":"Or_HaChaim_on_Numbers.22.31","commentator":"אור החיים","sourceLine":"אור החיים · Vocalized Edition · נחלת הכלל · ספריא","chapter":22,"verse":13,"dh":"וַיָּקָם בִּלְעָם בַּבֹּקֶר.","text":"אוּלַי לְפִי שֶׁהָיְתָה בְּשׂוֹרָה רָעָה לָהֶם, לֹא רָצָה לְגַלּוֹת לָהֶם בַּלַּיְלָה, לְפִי מַה שֶׁאָמַרְנוּ שֶׁהָיוּ בִּמְלוֹנוֹ עַצְמָהּ וְהִמְתִּין עַד הַבֹּקֶר. אוֹ יִרְצֶה שֶׁלֹּא קָם מִתַּרְדֵּמָתוֹ עַד הַבֹּקֶר, וְהוּא אָמְרוֹ וַיָּקָם בִּלְעָם בַּבֹּקֶר וְלֹא קוֹדֵם. אוֹ אֶפְשָׁר שֶׁיְּדַבֵּר הַכָּתוּב בִּגְנוּת בִּלְעָם שֶׁשְּׁלָחָם מַהֵר כְּדֵי שֶׁיְּמַהֵר לִשְׁלֹחַ אֲחֵרִים נִכְבָּדִים. אוֹ לְהוֹדִיעַ צָרוּת עֵינוֹ שֶׁמִּהֵר לְשָׁלְחָם קוֹדֶם הַגָּעַת זְמַן הָאוֹכֶל, הֵפֶךְ מִנְּדִיבוּת אֲבִי הַנַּעֲרָה פִּלֶגֶשׁ בַּגִּבְעָה (שופטים יט) שֶׁאָמַר לַחֲתָנוֹ שֶׁעָמַד לָלֶכֶת בַּבֹּקֶר:","complete":false},{"workId":"Kli_Yakar_on_Numbers","unitId":"Kli_Yakar_on_Numbers.22.18","commentator":"כלי יקר","sourceLine":"כלי יקר · Vocalized Edition · נחלת הכלל · ספריא","chapter":22,"verse":23,"dh":"וַתֵּט הָאָתוֹן מִן הַדֶּרֶךְ וְגוֹ׳.","text":"בַּתַּנְחוּמָא (בלק ח) אָמְרוּ: סִימָנֵי אָבוֹת הֶרְאָה לוֹ כוּ׳. כִּי ״וַתֵּלֶךְ בַּשָּׂדֶה״ מָקוֹם רָחָב, לוֹמַר שֶׁאִם יִרְצֶה לְקַבֵּל זֶרַע אַבְרָהָם יִמְצָא לְקַלֵּל בְּנֵי קְטוּרָה, וְיִשְׁמָעֵאל. וְאִם יִרְצֶה לְקַלֵּל זֶרַע יִצְחָק, יִמְצָא צַד אֶחָד לְקַלֵּל, כִּי יָכוֹל לְהַטּוֹת אֶל עֵשָׂו. אַךְ מִצַּד יַעֲקֹב, שֶׁהָיְתָה מִטָּתוֹ שְׁלֵמָה, עָמַד בְּמָקוֹם צָר, כִּי מִצִּדּוֹ ״אֵין דֶּרֶךְ לִנְטוֹת יָמִין וּשְׂמֹאל״. וְיֵשׁ עוֹד דְּרָכִים אֲחֵרִים אֶל הַמְפָרְשִׁים.","complete":true},{"workId":"Ramban_on_Numbers","unitId":"Ramban_on_Numbers.22.15","commentator":"רמב״ן","sourceLine":"רמב״ן · Vocalized Edition · נחלת הכלל · ספריא","chapter":22,"verse":41,"dh":"וַיַּעֲלֵהוּ בָּמוֹת בָּעַל וַיַּרְא מִשָּׁם קְצֵה הָעָם–","text":"הָיָה מַעֲלֶה אוֹתוֹ בְּמָקוֹם שֶׁיִּרְאֶנּוּ, כְּדֵי שֶׁיִּתְכַּוֵּן אֵלָיו בְּקִלְלָתוֹ וְלֹא תִפָּרֵד נַפְשׁוֹ מֵהֶם, כִּי אֵלֶּה מִכֹּחוֹת הַנֶּפֶשׁ לִהְיוֹת דְּבֵקָה בְּעֵת הָרְאִיָּה, כַּיָּדוּעַ מֵעִנְיַן הַחֲכָמִים (ב״ק קיז): ״דְּלוֹ לִי גְּבִינַאי דְּבָעֵינָא לְמֶחְזְיֵיהּ, דְּלוֹ לֵיהּ, יְהַב בֵּיהּ עֵינֵיהּ וְנָח נַפְשֵׁיהּ״. וְהִגִּיד הַכָּתוּב כִּי לֹא רָאָה כָּל הַמַּחֲנֶה, כִּי הָיוּ חוֹנִים אַרְבָּעָה דְּגָלִים לְאַרְבַּע רוּחוֹת הַשָּׁמַיִם. וּבַפַּעַם הַשְּׁנִיָּה אָמַר לוֹ בָּלָק:","complete":false},{"workId":"Haamek_Davar_on_Numbers","unitId":"Haamek_Davar_on_Numbers.23.29","commentator":"העמק דבר","sourceLine":"העמק דבר · ספר תורת אלוהים, וילנא 1879 · נחלת הכלל · ספריא","chapter":23,"verse":13,"dh":"לך","text":"נא. בכל הפרשה כתיב בה״א לכה. דמשמעו שרק אתה מיוחד לזה ולא אחר. כמבואר בירו׳ סוכה פ״ד ורבה ויקרא פ״א. מש״ה גבי ארה כתיב לכה ארה שאין אחר ראוי לזה. אבל בהליכה שהלך עם השרים כמבואר להלן י״ז כתיב לך. משא״כ להלן כ״ז בהליכה לבית פעור שלא הלך אלא בלעם ובלק כמבואר שם מש״ה כתיב לכה:","complete":true}],"pinchas":[{"workId":"Kli_Yakar_on_Numbers","unitId":"Kli_Yakar_on_Numbers.25.1","commentator":"כלי יקר","sourceLine":"כלי יקר · Vocalized Edition · נחלת הכלל · ספריא","chapter":25,"verse":11,"dh":"פִּינְחָס בֶּן אֶלְעָזָר בֶּן אַהֲרֹן הַכֹּהֵן וְגוֹ׳.","text":"הַכֹּל לִרְבוּתָא נָקַט, כִּי אַף עַל פִּי שֶׁהָיָה ״בֶּן אֶלְעָזָר״ אֲשֶׁר לָקַח לוֹ מִבְּנוֹת פּוּטִיאֵל, מִזֶּרַע יִתְרוֹ שֶׁפִּטֵּם עֲגָלִים לַעֲבוֹדָה זָרָה, וְהָיָה לוֹ לִמְנֹעַ אֶת עַצְמוֹ מִמַּעֲשֶׂה זֶה פֶּן יֹאמְרוּ לוֹ לֵיצָנֵי הַדּוֹר: בַּת יִתְרוֹ מִי הִתִּיר לְאָבִיךָ, וְאֵיךְ אַתָּה מְקַנֵּא עַל הַמִּדְיָנִית, וְכֵן אֲבִי אָבִיךָ פִּטֵּם עֲגָלִים לַעֲבוֹדָה זָרָה, וְאֵיךְ אַתָּה מְקַנֵּא עַל הָעֲבוֹדָה זָרָה. וְהָיָה ״בֶּן אַהֲרֹן הַכֹּהֵן״ וְיֹאמְרוּ לוֹ: אֲבִי אָבִיךָ זֶה פִּטֵּם עֲגָלִים לַעֲבוֹדָה זָרָה, וְהוּא עָשָׂה הָעֵגֶל. וְאַף עַל פִּי כֵן לֹא הָיָה מַקְפִּיד עַל כְּבוֹדוֹ.","complete":false},{"workId":"Ramban_on_Numbers","unitId":"Ramban_on_Numbers.26.1","commentator":"רמב״ן","sourceLine":"רמב״ן · Vocalized Edition · נחלת הכלל · ספריא","chapter":26,"verse":5,"dh":"חֲנוֹךְ מִשְׁפַּחַת הַחֲנֹכִי–","text":"אוּלַי כַּאֲשֶׁר נִתְחַלְּקָה הָאָרֶץ לַשְּׁבָטִים עַל דַּעַת רַבּוֹתֵינוּ (ב״ב קכב) וְנָטַל שֵׁבֶט שִׁמְעוֹן הַמּוּעָט כְּשֵׁבֶט יְהוּדָה הַמְרוּבֶּה חֵלֶק כְּחֵלֶק, כָּךְ נִתְחַלְּקָה לְבָתֵּי אָבוֹת לְיוֹרְדֵי מִצְרַיִם, וְעָשׂוּ מִנַּחֲלַת רְאוּבֵן ד' חֲלָקִים, וְהָיָה חֵלֶק מִשְׁפַּחַת הַחֲנוֹכִי כְּחֵלֶק מִשְׁפַּחַת הַפַּלּוּאִי וְחֶצְרוֹן וְכַרְמִי, אַף עַל פִּי שֶׁאֵינָן שָׁווֹת בְּמִסְפַּר שֵׁמוֹת לְגֻלְגְּלוֹתָם. וְזֶה טַעַם הַמִּנְיָן הַזֶּה שֶׁיִּמְנוּ הַמִּשְׁפָּחָה לְיוֹרְדֵי מִצְרַיִם וְלֹא יַזְכִּיר \"לְגֻלְגְּלוֹתָם\", וְאַף עַל פִּי שֶׁיַּזְכִּיר מִסְפָּרָם בִּכְלָל.","complete":false},{"workId":"Or_HaChaim_on_Numbers","unitId":"Or_HaChaim_on_Numbers.26.38","commentator":"אור החיים","sourceLine":"אור החיים · Vocalized Edition · נחלת הכלל · ספריא","chapter":26,"verse":53,"dh":"לָאֵלֶּה תֵּחָלֵק הָאָרֶץ וְגוֹ׳.","text":"אָמְרוֹ לָאֵלֶּה, נֶחְלְקוּ רַזַ״ל בְּפֶרֶק יֵשׁ נוֹחֲלִין (בבא בתרא קיז.) וְזֶה לְשׁוֹנָם: רַבִּי יֹאשִׁיָּה אָמַר לְיוֹצְאֵי מִצְרַיִם נִתְחַלְּקָה, שֶׁנֶּאֱמַר ״לִשְׁמוֹת מַטּוֹת אֲבוֹתָם יִנְחָלוּ״, אֶלָּא מָה אֲנִי מְקַיֵּם ״לָאֵלֶּה״ וְגוֹ׳? לָאֵלֶּה לְהוֹצִיא אֶת הַטְּפֵלִים, פֵּרוּשׁ שֶׁלֹּא יַחֲלֹק אֶלָּא לְיוֹצְאֵי מִצְרַיִם מִבֶּן עֶשְׂרִים. וְרַבִּי יוֹנָתָן אוֹמֵר לְבָאֵי הָאָרֶץ נִתְחַלְּקָה, שֶׁנֶּאֱמַר ״לָאֵלֶּה תֵּחָלֵק הָאָרֶץ״, וּמָה אֲנִי מְקַיֵּם ״לִשְׁמוֹת מַטּוֹת״? מְשֻׁנָּה נַחֲלָה זוֹ וְכוּ׳ וְכָאן מֵתִים יוֹרְשִׁים וְכוּ׳ עַד כָּאן.","complete":false},{"workId":"Haamek_Davar_on_Numbers","unitId":"Haamek_Davar_on_Numbers.27.9","commentator":"העמק דבר","sourceLine":"העמק דבר · ספר תורת אלוהים, וילנא 1879 · נחלת הכלל · ספריא","chapter":27,"verse":7,"dh":"נתן תתן להם וגו׳.","text":"כ״ז המקרא נראה מיותר. והכי מיבעי דבר אל ב״י איש כי ימות וגו׳. ולפי הדרש בב״ב דקי״ט בא לרבות חלק בכורה ועוד ארבעה חלקים. ולפי הפשט יש להבין עפ״י דאי׳ שם דק״ט רבי א׳ בכולן נאמר נתינה ובבת נאמר העברה שאין לך שמעביר נחלה משבט לשבט אלא בת. וזהו ודאי עומק לשון הכתוב . וא״כ בב״צ דכתיב והעברת את נחלת אביהן להן למדנו שהותרו ב״צ לכל השבטים. וכדאי׳ שם דק״כ אלא דשם למדו מדכתיב לטוב בעיניהם תהיינה לנשים. וזה לא נצרכנו אלא לת״ק דרבי. ודרשי הא דכתיב והעברת לרבות חלק בכורה וכפי׳ רשב״ם בדקי״ח כדכתיב והעברת כל פטר רחם. אבל לרבי הלא מבואר במקומו שהן רשאין להעביר נחלה. ומש״ה פירש הקב״ה בהם בפ״ע.","complete":false},{"workId":"Rabbeinu_Bahya_on_Numbers","unitId":"Rabbeinu_Bahya_on_Numbers.28.2","commentator":"רבינו בחיי","sourceLine":"רבינו בחיי · Midrash Rabbeinu Bachya [ben Asher]. Warsaw, 1878 · נחלת הכלל · ספריא","chapter":28,"verse":2,"dh":"וע\"ד","text":"הפשט קרבני זה הדם, את לרבות מלח דכתיב, (ויקרא ב) על כל קרבנך תקריב מלח לכך טובלין לחם המוציא במלח שהקרבן נקרא לחם, לחמי אלו אמורין, לאשי הנתנין לאש על מזבחי, תשמרו שיהיו כהנים לוים וישראלים עומדים על גביו, מכאן למדו ותקנו מעמדות, במועדו כלומר בכל יום ויום הוא מועד התמידין, אבל בא לומר שלא יקדים כלום קודם עולת הבקר ולא יאחר כלום אחר עולת הערב, במועדו אפילו בשבת ואפילו בטומאה.","complete":true}],"matot":[{"workId":"Or_HaChaim_on_Numbers","unitId":"Or_HaChaim_on_Numbers.30.3","commentator":"אור החיים","sourceLine":"אור החיים · Vocalized Edition · נחלת הכלל · ספריא","chapter":30,"verse":2,"dh":"אֶל רָאשֵׁי הַמַּטּוֹת וְגוֹ׳.","text":"צָרִיךְ לָדַעַת מַה נִשְׁתַּנֵּית מִצְוָה זוֹ שֶׁפֵּרַט בָּהּ הַכָּתוּב רָאשֵׁי הַמַּטּוֹת, וְרַבּוֹתֵינוּ זִכְרוֹנָם לִבְרָכָה בְּסִפְרֵי אָמְרוּ: לְפִי שֶׁבְּמַאֲמַר הַחֲצוֹצְרוֹת הִקְדִּים קְרִיאַת הָעֵדָה לַנְּשִׂיאִים, חָשׁ לוֹמַר שֶׁהָעֵדָה קוֹדֶמֶת לַנְּשִׂיאִים, תַּלְמוּד לוֹמַר ״אֶל רָאשֵׁי״ וְגוֹ׳ שֶׁהֵם הַקּוֹדְמִים. וּבְמָקוֹם אַחֵר (נדרים עח:, בבא בתרא קכ:) אָמְרוּ שֶׁבָּא לוֹמַר הֶתֵּר נְדָרִים בְּיָחִיד מֻמְחֶה, וְכָל זֶה דֶּרֶךְ דְּרָשׁ וְאַסְמַכְתּוֹת. עוֹד צָרִיךְ לָדַעַת לָמָּה הֻצְרַךְ לוֹמַר הַמַּטּוֹת לִבְנֵי, שֶׁלֹּא הָיָה לוֹ לוֹמַר אֶלָּא ״אֶל רָאשֵׁי מַטּוֹת בְּנֵי יִשְׂרָאֵל״.","complete":false},{"workId":"Ramban_on_Numbers","unitId":"Ramban_on_Numbers.31.1","commentator":"רמב״ן","sourceLine":"רמב״ן · Vocalized Edition · נחלת הכלל · ספריא","chapter":31,"verse":2,"dh":"נְקֹם נִקְמַת בְּנֵי יִשְׂרָאֵל וְגוֹ' אַחַר תֵּאָסֵף אֶל עַמֶּיךָ–","text":"נִגְזַר עַל מֹשֶׁה רַבֵּינוּ שֶׁלֹּא יַעֲבֹר אֶת הַיַּרְדֵּן, אֲבָל מֵעֵבֶר לַיַּרְדֵּן עָשָׂה כָּל מִצְווֹת יִשְׂרָאֵל: נִצַּח שְׁנֵי מַלְכֵי הָאֱמוֹרִי הַגְּדוֹלִים וְחִלֵּק אֶת אַרְצָם בְּנַחֲלָה, וְהוּא רָאוּי שֶׁיַּעֲשֶׂה נְקָמָה בְּשׂוֹנְאֵי ה', וְאֵין עַל יְהוֹשֻׁעַ רַק מִצְווֹת הָאָרֶץ. וְעוֹד שֶׁחָלַק לוֹ הַקב״ה כָּבוֹד זֶה שֶׁיִּרְאֶה וְיִשְׂמַח צַדִּיק כִּי חָזָה נָקָם, וְזֶה טַעַם ״אַחַר תֵּאָסֵף אֶל עַמֶּךָ״. וּמֹשֶׁה חָלַק כָּבוֹד לְפִינְחָס שֶׁהִתְחִיל בַּמִּצְוָה וְעָלָיו לְגוֹמְרָהּ, וַעֲשָׂאוֹ מְשׁוּחַ מִלְחָמָה זוֹ. וְאֵין רָאוּי שֶׁיֵּלֵךְ אֶלְעָזָר כִּי הוּא הַכֹּהֵן הַגָּדוֹל:","complete":true},{"workId":"Rabbeinu_Bahya_on_Numbers","unitId":"Rabbeinu_Bahya_on_Numbers.32.3","commentator":"רבינו בחיי","sourceLine":"רבינו בחיי · Midrash Rabbeinu Bachya [ben Asher]. Warsaw, 1878 · נחלת הכלל · ספריא","chapter":32,"verse":2,"dh":"ובמדרש","text":"ומקנה רב העושר כשבא מן השמים הוא מתקיים וכשאינו בא מן השמים אינו מתקיים, שני עשירים עמדו בעולם קרח מישראל והמן מאומות העולם ושניהם אבדו מן העולם, שלא היתה מתנתם מן השמים שהיו חוטפין אותה להם. וכן אתה מוצא בבני גד ובבני ראובן שהיו עשירים הרבה והיה להם מקנה רב וחבבו את ממונם וישבו להם חוצה לארץ והפרישו עצמן מאחיהם בשביל קנינם, לפיכך גלו תחלה מכל השבטים, שנאמר (דברי הימים א ה׳:כ״ו) ויגלם לראובני ולגדי ולחצי שבט המנשי.","complete":false},{"workId":"Haamek_Davar_on_Numbers","unitId":"Haamek_Davar_on_Numbers.32.18","commentator":"העמק דבר","sourceLine":"העמק דבר · ספר תורת אלוהים, וילנא 1879 · נחלת הכלל · ספריא","chapter":32,"verse":22,"dh":"לפני ה׳.","text":"כי קדושת הארץ תלוי׳ הרבה בחילוק ובברור כל אחד על נחלתו. כידוע שבזה תלי׳ דיני יובל ועוד כמה דינים שאין נוהג אלא בזמן שהיובל נוהג. והרי זה עיקר רצון ה׳ שתהא הארץ מיושבת בקדושתה לפניו. ואז תהי׳ הנהגתו והשגחתו ביחוד עליה. ובזה תהיו נקיים גם מה׳ גם מישראל. והוסיף עוד משה לכונה זו נ״מ למעשה. והיתה הארץ הזאת לאחזה לפני ה׳. גם הארץ הזאת עה״י. אע״ג שבאמת קיל קדושתה מגליל ויהודה מכ״מ תהי׳ הארץ לאחזה לפני ה׳. בקבלת השגחתו ית׳ וכל מנהגי א״י כמו בעשרת השבטים:","complete":true}],"masei":[{"workId":"Ramban_on_Numbers","unitId":"Ramban_on_Numbers.33.1","commentator":"רמב״ן","sourceLine":"רמב״ן · Vocalized Edition · נחלת הכלל · ספריא","chapter":33,"verse":1,"dh":"אֵלֶּה מַסְעֵי–","text":"אַחֲרֵי נִקְמַת מִדְיָן שֶׁאָמַר לוֹ הַקב״ה לְמֹשֶׁה ״אַחַר תֵּאָסֵף אֶל עַמֶּיךָ״ (במדבר ל״א:ב׳), וְאַחֲרֵי שֶׁחִלֵּק אֶרֶץ סִיחוֹן וְעוֹג וּבָנוּ הֶעָרִים הַנִּזְכָּרוֹת, נָתַן דַּעְתּוֹ לִכְתֹּב הַמַּסָּעוֹת. וְנִתְכַּוֵּן בָּזֶה לְהוֹדִיעַ חֲסָדָיו שֶׁל הַקב״ה עִמָּהֶם, שֶׁאַף עַל פִּי שֶׁגָּזַר עֲלֵיהֶם לְטַלְטְלָם וְלַהֲנִיעָם בַּמִּדְבָּר, לֹא תַּחְשֹׁב שֶׁהָיוּ נָעִים וּמְטֻלְטָלִין מִמָּקוֹם לְמָקוֹם תָּמִיד וְלֹא הָיְתָה לָהֶם מְנוּחָה, אֲבָל בְּכָל הַזְּמַן הַגָּדוֹל לֹא הָלְכוּ אֶלָּא אַרְבָּעִים וּשְׁנַיִם מַסָּעוֹת, כְּמוֹ שֶׁכָּתַב הָרַב רַשִׁ״י מִדִּבְרֵי רַבִּי מֹשֶׁה הַדַּרְשָׁן.","complete":false},{"workId":"Haamek_Davar_on_Numbers","unitId":"Haamek_Davar_on_Numbers.33.13","commentator":"העמק דבר","sourceLine":"העמק דבר · ספר תורת אלוהים, וילנא 1879 · נחלת הכלל · ספריא","chapter":33,"verse":51,"dh":"כי אתם עוברים את הירדן וגו׳.","text":"אבל כ״ז שלא עברו את הירדן לא״י לא הוזהרו להאביד ע״ז בעה״י. דאזהרה זו היא משום קדושת הארץ. ואין עה״י מתקדש אלא אחר שנתקדש א״י כמו לענין ערי מקלט שאינן קולטות עד שיהיו נגמר גם בא״י משום דערי מקלט תלוי בקדושת הארץ בזמן שהיובל נוהג. ויובל תלוי בזמן שכל ישראל על אדמתם וע׳ להלן ל״ה י׳ ומש״ה לא הוזהרו לבער ע״ז מעה״י עד שיטהרו מא״י:","complete":true},{"workId":"Rabbeinu_Bahya_on_Numbers","unitId":"Rabbeinu_Bahya_on_Numbers.34.10","commentator":"רבינו בחיי","sourceLine":"רבינו בחיי · Midrash Rabbeinu Bachya [ben Asher]. Warsaw, 1878 · נחלת הכלל · ספריא","chapter":34,"verse":17,"dh":"אלה שמות האנשים אשר ינחלו לכם את הארץ.","text":"פירש רש\"י ז\"ל ינחלו לכם בשבילכם, שכל נשיא ונשיא אפוטרופוס לשבטו, ומחלק נחלת השבט למשפחות ולגברים ובורר לכל אחד ואחד חלק יפה, ומה שהם עושים יהא עשוי כאלו עשאוהו שלוחיהם. והזכיר תחלה אלעזר כי יהושע יצא על פיו. והזכיר עשרה שבטים ונשיא עם כל אחד ואחד, ולא הזכיר ראובן וגד כי כבר לקחו חלקם מעבר לירדן מזרחה. והתחיל בנשיאים מיהודה כמו שיצא הגורל תחלה. ואמר ולמטה בני דן נשיא בקי בן יגלי.","complete":true},{"workId":"Or_HaChaim_on_Numbers","unitId":"Or_HaChaim_on_Numbers.35.1","commentator":"אור החיים","sourceLine":"אור החיים · Vocalized Edition · נחלת הכלל · ספריא","chapter":35,"verse":2,"dh":"וְנָתְנוּ לַלְוִיִּם וְגוֹ׳.","text":"פֵּרוּשׁ, הֲגַם שֶׁצִּוָּה ה׳ שֶׁלֹּא יִהְיֶה לַלְוִיִּם חֵלֶק וְנַחֲלָה בָּאָרֶץ, אֲבָל בְּתוֹרַת חֶסֶד יִתְּנוּ לָהֶם מַתְּנַת חִנָּם מִמַּה שֶׁהִגִּיעָם, כְּדִין שֶׁמְּפַרְנְסִים מִי שֶׁהִשִּׂיגָה (אולי צריך לומר שלא השיגה) יָדוֹ, וְהוּא מַה שֶׁדִּקְדֵּק לוֹמַר עָרִים לָשָׁבֶת, פֵּרוּשׁ לְצַד הַהֶכְרֵחַ לָשֶׁבֶת בָּהֶם וְגוֹ׳, וְלָזֶה כָּפַל לוֹמַר אַחַר כָּךְ וְהָיוּ הֶעָרִים לָהֶם לָשָׁבֶת, לְהָעִירְךָ כִּי מַאֲמַר ״לָשָׁבֶת״ רִאשׁוֹן הִיא טַעַם הַנְּתִינָה, וּמַאֲמַר ״וְהָיוּ הֶעָרִים לָהֶם לָשָׁבֶת״ הוּא לוֹמַר לְךָ שֶׁצָּרִיךְ שֶׁיִּהְיוּ רְאוּיִים לִישִׁיבָה.","complete":false}],"devarim":[{"workId":"Haamek_Davar_on_Deuteronomy","unitId":"Haamek_Davar_on_Deuteronomy.1.1","commentator":"העמק דבר","sourceLine":"העמק דבר · ספר תורת אלוהים, וילנא 1879 · נחלת הכלל · ספריא","chapter":1,"verse":1,"dh":"אלה הדברים.","text":"היינו כל הספר עד פ׳ וילך. והנה לא היו כל הדברים הרבים ההם במעמד אחד ולא ביום אחד. אלא הקהיל את העם בכמה עתים ודבר איזה ענין מזה הספר. ומפרש הפסוק שפעם הקהיל את העם במדבר. פעם בערבה. פעם מול סוף. פעם בין פארן ובין תופל פעם בלבן ופעם בחצרות. שהית׳ עיר בעה״י הנקראת חצרות. ואין זו חצרות דמסעות. פעם במקום שנקרא די זהב. ובאשר דחניית ישראל בעה״י לא הי׳ כאופן חנייתם במדבר שהי׳ במקום א׳ על דגליהם וכשנדרש משה להקהיל את העדה הי׳ לזה מקום מיוחד חצר המשכן משא״כ בעה״י היו ישראל מפוזרים בערים שירשו בארצות סיחון ועוג. ורק הארון עמד במקום א׳. ומשה רבינו הקהיל את העם במקומות שונים.","complete":false},{"workId":"Tur_HaArokh_on_Deuteronomy","unitId":"Tur_HaArokh_on_Deuteronomy.1.8","commentator":"טור הארוך","sourceLine":"טור הארוך · Perush al ha-Torah, Hanover, 1838 · נחלת הכלל · ספריא","chapter":1,"verse":12,"dh":"טרחכם ומשאכם וריבכם.","text":"פי' הרמב\"ן על דרך הפשט רמז משה לישראל שלשת הדברים שאמר ליתרו שהי' עושה לעם טרחכם כנגד והודעתי את חוקי האלקים כי טורח גדול הוא ללמד ליוצאי מצרים החוקים והתורות ופירושן וביאורן וסודן. ומשאכם כנגד לדרוש אלקים שהוא ענין תפלה שמתפלל עליהם מלשון ונשאת תפלה. ואל תשא בעדם רנה ותפלה. וריבכם כפשוטו ענין המשפטים ואמר הבו לכם אנשי' חכמים על הדיינים בלבד. א\"נ משאכם שהייתם מבקשים בשר ומים כדכתיב לתת את משא כל העם הזה עלי:","complete":true},{"workId":"Ramban_on_Deuteronomy","unitId":"Ramban_on_Deuteronomy.1.12","commentator":"רמב״ן","sourceLine":"רמב״ן · On Your Way new · נחלת הכלל · ספריא","chapter":1,"verse":22,"dh":"את הדרך אשר נעלה בה","text":"אין דרך שאין בה עקמימות ואת הערים אשר נבא אליהן תחלה לכבוש לשון רש\"י (רש\"י על דברים א׳:כ״ב) וכן בספרי (דברים כב) אין לך דרך שאין בה עקמימות אין לך דרך שאין בה כמנות אין לך דרך שאין בה פרשות ואת הערים אשר נבא אליהן לידע באי זה דרך אנו באין כלומר מאין נכנס בארץ שנכבוש אותן הערים תחלה והוא מה שפירשתי בסדר שלח לך (במדבר יג ב) שלא בקשו ישראל מרגלים אלא להורות בפניהם הדרך:","complete":true},{"workId":"Rabbeinu_Bahya_on_Deuteronomy","unitId":"Rabbeinu_Bahya_on_Deuteronomy.2.2","commentator":"רבינו בחיי","sourceLine":"רבינו בחיי · Midrash Rabbeinu Bachya [ben Asher]. Warsaw, 1878 · נחלת הכלל · ספריא","chapter":2,"verse":3,"dh":"פנו לכם צפונה.","text":"אמרו במדרש רבה, אם באתה שעתו של עשו הצפינו עצמכם מלפניו, שנאמר פנו לכם צפונה. דבר אחר פנו לכם צפונה, אמר הקב\"ה מזבח אחד יש לי והוא עתיד לפגרו. דבר אחר פנו לכם צפונה, צפון אחד היה לי ביניכם זה בית המקדש שהייתי נצפן עמכם בו, והוא עתיד להחריבו שנאמר (יחזקאל ז׳:כ״ב) והסבותי פני מהם וחללו את צפוני.","complete":true},{"workId":"Or_HaChaim_on_Deuteronomy","unitId":"Or_HaChaim_on_Deuteronomy.2.8","commentator":"אור החיים","sourceLine":"אור החיים · Vocalized Edition · נחלת הכלל · ספריא","chapter":2,"verse":31,"dh":"רְאֵה הַחִלֹּתִי וְגוֹ׳.","text":"אָמַר הַחִלֹּתִי לְשׁוֹן עָבָר, חוֹזֵר אֶל מַאֲמַר ״הִקְשָׁה ה׳ אֶת רוּחוֹ לְמַעַן תִּתּוֹ בְּיָדֶךָ״, וּמַאֲמַר הַחִלֹּתִי חוֹזֵר לַנְּתִינָה לֹא לְמַאֲמַר ״לְפָנֶיךָ״, וּמֹשֶׁה הֵבִין שֶׁחוֹזֵר לְכָל הָאָמוּר, וְלָזֶה הִתְחַנֵּן לַה׳ בְּחָשְׁבוֹ שֶׁהֻתַּר הַנֶּדֶר, כְּאָמְרָם זִכְרוֹנָם לִבְרָכָה (ספרי ריש פרשת ואתחנן).","complete":true}],"vaetchanan":[{"workId":"Haamek_Davar_on_Deuteronomy","unitId":"Haamek_Davar_on_Deuteronomy.3.18","commentator":"העמק דבר","sourceLine":"העמק דבר · ספר תורת אלוהים, וילנא 1879 · נחלת הכלל · ספריא","chapter":3,"verse":23,"dh":"בעת ההיא.","text":"שנחלק הנחלה לב״ג וב״ר. וראה כי ההכרח להשריש בישראל כח התלמוד והעסק בה כמו שביארנו שזה היה שורש הגלות והגלות גורם ההכרח לתלמוד. ורצה משה רבינו שיהיה זה הפעולה בא״י שמסוגל יותר מעה״י ואין חכמה כחכמת א״י וכמש״כ לעיל. וביחוד ירושלים אשר היא מסוגלת לצאת תורה ממנה. וביחוד מקום בהמ״ק בהר ה׳ יראה . וביקש לבא לשם להרביץ תורה:","complete":true},{"workId":"Rabbeinu_Bahya_on_Deuteronomy","unitId":"Rabbeinu_Bahya_on_Deuteronomy.4.4","commentator":"רבינו בחיי","sourceLine":"רבינו בחיי · Midrash Rabbeinu Bachya [ben Asher]. Warsaw, 1878 · נחלת הכלל · ספריא","chapter":4,"verse":6,"dh":"ושמרתם ועשיתם כי היא חכמתכם ובינתכם לעיני העמים.","text":"למדך הכתוב כאן כי כל המצות תלויות במצות השמור והעשייה וכלן נכללות בהן, כגון שתאמר חכמת הרפואה נכללה בתורה בפסוק (שמות ט״ו:כ״ו) ויאמר אם שמוע תשמע לקול ה' אלהיך והישר בעיניו תעשה והאזנת למצותיו ושמרת כל חקיו כל המחלה אשר שמתי במצרים לא אשים עליך כי אני ה' רופאך, וכן כל שאר החכמות. ודרשו רז\"ל, לעיני העמים, אי זו היא חכמה שהיא לעיני העמים, זה היודע לחשב תקופות ומזלות, וכל היודע לחשב בהם ואינו מחשב עליו הכתוב אומר (ישעיהו ה׳:י״ב) ואת פעל ה' לא יביטו ומעשה ידיו לא ראו.","complete":true},{"workId":"Rashbam_on_Deuteronomy","unitId":"Rashbam_on_Deuteronomy.4.11","commentator":"רשב״ם","sourceLine":"רשב״ם · רשב\"ם על דברים - דעת · נחלת הכלל · ספריא","chapter":4,"verse":41,"dh":null,"text":"אז יבדיל משה - למה הפסיק דברי משה שהן מחוברין יחד זה אחר זה וכתב זה המעשה בינתים? אלא לפי שהאריך בדברים עד עכשיו ועתה מתחיל לפרש המצות היאך ביאר את התורה הזאת. והוא צריך לומר בשופטים ושוטרים: שלש ערים תבדיל לך בתוך ארצך אשר ה' אלהיך נותן לך. ואם ירחב (לעתיד לבא) ויספת לך עוד שלש ערים על השלש האלה. ועל שלש ערים שצוה לו הקב\"ה באלה מסעי לעשות בעבר הירדן לא הזכיר שם ולא צוה משה לישראל, לכך כתיב כאן, כי משה הבדילם כבר ולכך לא צוה לישראל.","complete":true},{"workId":"Or_HaChaim_on_Deuteronomy","unitId":"Or_HaChaim_on_Deuteronomy.5.1","commentator":"אור החיים","sourceLine":"אור החיים · Vocalized Edition · נחלת הכלל · ספריא","chapter":5,"verse":1,"dh":"וַיִּקְרָא מֹשֶׁה.","text":"אוּלַי לְפִי שֶׁיָּרְשׁוּ כָּל הָאֲרָצוֹת הָהֵם, הָיוּ יִשְׂרָאֵל מְפֻזָּרִים בְּכָל הַמְּקוֹמוֹת הָהֵם, לָזֶה הֻצְרַךְ לִקְרוֹת לְכֻלָּן. אוֹ אֶפְשָׁר שֶׁעַד עַתָּה הָיָה מְדַבֵּר עִם הָאֲנָשִׁים, וּכְשֶׁרָצָה לוֹמַר עֲשֶׂרֶת הַדִּבְּרוֹת קָרָא גַּם לַנָּשִׁים וְהַטַּף כְּמַעֲמַד הַר סִינַי, כְּאָמְרוֹ ״כָּל יִשְׂרָאֵל״.","complete":true},{"workId":"Tur_HaArokh_on_Deuteronomy","unitId":"Tur_HaArokh_on_Deuteronomy.5.13","commentator":"טור הארוך","sourceLine":"טור הארוך · Perush al ha-Torah, Hanover, 1838 · נחלת הכלל · ספריא","chapter":5,"verse":19,"dh":"ולא יסף.","text":"ומתרגמינן ולא פסק פירש\"י בפי' אחד שלא היה בו הפסק אלא שוה בתחלה ובסוף. וכתב הרמב\"ן והכתוב שאומר ויהי קול השופר הולך וחזק מאד ואמרו ולמה כך לשבר האוזן במה שיכול' לשמוע ואולי בקול השופר היה כן אבל קול השם בעשרת הדברים הי' שוה. והנכון כי האומר לא פסק עשה יסף מן ונאספה שמחה וגיל. תוסף רוחם יגועון שעניינם לדעתו המנע הדבר פי' כי לא נמנע גדלו ותקפו עד שהשלים כל הדברות. ועל הפשט ולא יסף שלא יסף להראות עוד בקול גדול כמוהו:","complete":true},{"workId":"Sforno_on_Deuteronomy","unitId":"Sforno_on_Deuteronomy.6.11","commentator":"ספורנו","sourceLine":"ספורנו · ובלכתך בדרך · נחלת הכלל · ספריא","chapter":6,"verse":4,"dh":"ה' אחד.","text":"ובהיותו נותן המציאות אחר אפיסות מוחלט התבאר שאין נמצא זולתו ממין מציאותו ושהוא נבדל במין ממציאות עולם הנפסדים וממציאות עולם הגלגלים וממציאות עולם המלאכים באופן שהוא יחיד בעולמו הרביעי. וזה נראה שנרמז בהיות אות הדל\"ת של אחד גדולה ובאות העי\"ן של שמע הגדולה נרמז שראוי לפקוח עין ולהגדיל העיון בזה. ולזה אמרו ז\"ל (ברכות פרק היה קורא) ובלבד שיאריך בדל\"ת של אחד למען יכוין לזה:","complete":true}],"eikev":[{"workId":"Tur_HaArokh_on_Deuteronomy","unitId":"Tur_HaArokh_on_Deuteronomy.7.8","commentator":"טור הארוך","sourceLine":"טור הארוך · Perush al ha-Torah, Hanover, 1838 · נחלת הכלל · ספריא","chapter":7,"verse":12,"dh":"והיה עקב תשמעון.","text":"פירש\"י אם המצות הקלות שאדם דש בעקיבו תשמעון וכו'. ולפי זה צריך לפרש שהפסוק מדבר בשני דברים והיה עקב תשמעון מצות הקלות ואת המשפטים תשמעון גם כן. והרמב\"ן כתב לפירש\"י אולי מזהיר במשפטים קלים בדיני ממונות שלא יבזו אותם. והמפרשים פירשו כי עקב הוא שכר באחרית וכן בשמר' עקב רב ופי' הפסוק והיה באחרית תשמעון המשפטים ישמור לך השם הברית והחסד כי בלשון הקודש קורא להתחלת כל דבר בלשון ראש וכך קורא לאחרית כל דבר בלשון עקב כי הלשון תופס דמיונו באדם והראש בו תחלה והעקב אחרית.","complete":false},{"workId":"Haamek_Davar_on_Deuteronomy","unitId":"Haamek_Davar_on_Deuteronomy.8.15","commentator":"העמק דבר","sourceLine":"העמק דבר · ספר תורת אלוהים, וילנא 1879 · נחלת הכלל · ספריא","chapter":8,"verse":11,"dh":"השמר לך פן","text":"תשכח את ה׳ אלהיך. אין הכונה כאן כמו לעיל ו׳ י״ב השמר לך פן תשכח את ה׳. דשם מיירי בשעת כיבוש הארץ כמו שביארנו שם והזהירם שלא יסיחו דעתם מן ה׳ כמבואר בענין. אבל כאן מיירי לאחר שנתיישבו בארץ כדכתיב בסמוך ובתים טובים תבנה וישבת והזהירם שלא ישכחו בדרך כלל שה׳ מנהיגם ומפרנסם והיינו דכתיב את ה׳ אלהיך והדבר מובן דמכש״כ הננו מוזהרים ע״ז בעת הגלות. אלא בראש הפ׳ שהזהירנו על הבטחון העיר ביותר על עת הגלות. וכאן שהזהירנו על השכחה בהשגחת ה׳ העיר ביותר על עת של ישיבת הארץ במנוחה והשקט. (וע׳ מש״כ בס׳ ויקרא כ״ג שהזהירה תורה בישיבת סוכה להיות לאות לשני אופנים הללו):","complete":true},{"workId":"Rabbeinu_Bahya_on_Deuteronomy","unitId":"Rabbeinu_Bahya_on_Deuteronomy.9.2","commentator":"רבינו בחיי","sourceLine":"רבינו בחיי · Midrash Rabbeinu Bachya [ben Asher]. Warsaw, 1878 · נחלת הכלל · ספריא","chapter":9,"verse":5,"dh":"לא בצדקתך וביושר לבבך וגו' כי ברשעת הגוים האלה.","text":"נראה כי אילו היו צדיקים לא היו מגורשים משם וא\"כ מה יהיה בשבועת האבות, אבל הענין כי הגוים הרשעים ראויים שיתגרשו משם ואף אם היו צדיקים לא ישארו בארץ, כי הארץ פקדון בידם מזמן הבטחת האבות, והקב\"ה יוכל להיטיב עמהם לתת להם ארץ אחרת כי לה' הארץ ומלואה, אבל זאת אי אפשר להם שישארו שם למען הקים את הדבר.","complete":true},{"workId":"Or_HaChaim_on_Deuteronomy","unitId":"Or_HaChaim_on_Deuteronomy.10.1","commentator":"אור החיים","sourceLine":"אור החיים · Vocalized Edition · נחלת הכלל · ספריא","chapter":10,"verse":1,"dh":"בָּעֵת הַהִיא וְגוֹ׳ פְּסָל לְךָ.","text":"פֵּרוּשׁ, לְפִי שֶׁלּוּחוֹת הָרִאשׁוֹנִים מַעֲשֵׂה אֱלֹהִים הֵמָּה וְלֹא מַעֲשֵׂה יְדֵי מֹשֶׁה, וְאַחַר שֶׁנַּעֲשָׂה הָעֵגֶל לֹא הָיוּ רְאוּיִים לְלוּחוֹת כָּזֶה, וְאָמַר ה׳ לְמֹשֶׁה שֶׁיִּפְסוֹל אוֹתָם מִדְּבָרִים שֶׁהֵם מִתְיַחֲסִים אֵלָיו, לִשְׁלוֹל הַמִּתְיַחֲסִים לְאֵל עֶלְיוֹן שֶׁהֵם הָרִאשׁוֹנִים.","complete":true},{"workId":"Kli_Yakar_on_Deuteronomy","unitId":"Kli_Yakar_on_Deuteronomy.10.6","commentator":"כלי יקר","sourceLine":"כלי יקר · Vocalized Edition · נחלת הכלל · ספריא","chapter":10,"verse":12,"dh":"וְעַתָּה יִשְׂרָאֵל מָה ה׳ אֱלֹהֶיךָ שֹׁאֵל מֵעִמָּךְ כִּי אִם לְיִרְאָה.","text":"רַבּוֹתֵינוּ זִכְרוֹנָם לִבְרָכָה אָמְרוּ (ברכות לג:): וְכִי הַיִּרְאָה מִלְּתָא זוּטַרְתִּי הִיא? אִין, לְגַבֵּי מֹשֶׁה זוּטַרְתִּי הִיא. וּמַקְשִׁים כָּאן: וְכִי בַּעֲבוּר זֶה אָמַר לְכָל יִשְׂרָאֵל מָה ה׳ שֹׁאֵל מֵעִמָּךְ? וְיֵשׁ מְתָרְצִים, לְגַבֵּי מֹשֶׁה הַיְינוּ כְּשֶׁהָיוּ יִשְׂרָאֵל אֵצֶל מֹשֶׁה, שֶׁהָיָה מַדְרִיכָם בְּמִדַּת הַיִּרְאָה, אָז זוּטַרְתִּי הִיא. וַאֲנִי אוֹמֵר שֶׁזֶּהוּ כַּוָּנַת הַפָּסוּק שֶׁאָמַר ״וְעַתָּה יִשְׂרָאֵל״, מַה הוּא ״וְעַתָּה״? אֶלָּא לְפִי שֶׁנֶּאֱמַר אַחַר כָּךְ:","complete":false},{"workId":"Rashbam_on_Deuteronomy","unitId":"Rashbam_on_Deuteronomy.11.3","commentator":"רשב״ם","sourceLine":"רשב״ם · רשב\"ם על דברים - דעת · נחלת הכלל · ספריא","chapter":11,"verse":10,"dh":null,"text":"כי הארץ אשר אתה בא שמה לרשתה לא כארץ מצרים - כן שיטת פרשיות הללו, צריכים אתם לשמור מצות ה' אלהיכם, כי הארץ הזאת טובה מארץ מצרים לשומרי מצותיו ורעה מכל הארצות ללא שומרים, כי הארץ אשר אתה בא שמה איננה כארץ מצרים, שאין צריכין למטר ובין טובים ובין חטאים בטורח השקאת שדותיהם יש להם לחם, אבל ארץ ישראל אם אתם שומרים מצות.","complete":true}],"reeh":[{"workId":"Tur_HaArokh_on_Deuteronomy","unitId":"Tur_HaArokh_on_Deuteronomy.11.12","commentator":"טור הארוך","sourceLine":"טור הארוך · Perush al ha-Torah, Hanover, 1838 · נחלת הכלל · ספריא","chapter":11,"verse":26,"dh":"ראה אנכי נותן לפניכם היום ברכה וקללה.","text":"לפי הפשט אמר לשון יחיד ראה כי עם כל אחד ואחד מדבר. וי\"מ ליהושע אמר ראה אנכי וגו' והזהירו לברך את ישראל כשיעברו את הירדן. וי\"מ לפי שקללות וברכו' שבמשנה תורה כולם נאמרו בלשון יחיד. ד\"א אמר לשון ראה כי המשליך גורל עם חבירו הוא מכסה הגורלות וגם החלקים שלא יברור חבירו חלק היפה אבל אתה ראה הגורלות וראה החלקים ובחרת בחיים וזהו אתה תומך גורלי שאתה תומך ידי ליתן אותה על הגורל הטוב לברור אותו: בברכה נאמר את הברכה לשון ריבוי כי לא נפל מכל דברו הטוב אבל בקללה לא נאמר את אלא והקללה. ובקללה נאמר אם לא תשמעו ובברכה נאמר אשר תשמעון ולא אמר בלשון ספק אלא ודאי תשמעון וגם אמר לשון אשר כענין שנאמר אשרי אדם שומע לי:","complete":true},{"workId":"Haamek_Davar_on_Deuteronomy","unitId":"Haamek_Davar_on_Deuteronomy.12.23","commentator":"העמק דבר","sourceLine":"העמק דבר · ספר תורת אלוהים, וילנא 1879 · נחלת הכלל · ספריא","chapter":12,"verse":11,"dh":"ותרומת ידכם.","text":"כאן אין הפירוש ביכורים שהרי פסוק זה והבא אחריו לא בא להשמיענו אלא בדבר אכילת קדשים שקרב לגבוה ומכ״מ מותרים לנשים ועבדים. והרי ביכורים אינו קרב לגבוה כלל. אלא הפי׳ של ותרומת ידכם היינו נדבות כמש״כ הרמב״ן מש״ה לא כתיב כאן ונדבותיכם תדע שהרי לא כתיב כאן בכורות והיינו משום שאינו נאכל אלא לכהנים כמו ביכורים אלא פי׳ תרומת ידכם הוא נדבות ומש״ה כתיב כאן תרמת חסר. ולא כמו לעיל ו׳ ולהלן י״ז דכתיב מלא. דשם הוא שם העצם וכאן על שם הפעולה אשר תרימו כמו הרימתי ידי וגו׳:","complete":true},{"workId":"Or_HaChaim_on_Deuteronomy","unitId":"Or_HaChaim_on_Deuteronomy.12.25","commentator":"אור החיים","sourceLine":"אור החיים · Vocalized Edition · נחלת הכלל · ספריא","chapter":12,"verse":29,"dh":"כִּי יַכְרִית וְגוֹ׳ אֶת הַגּוֹיִם וְגוֹ׳ הִשָּׁמֶר לְךָ וְגוֹ׳.","text":"צָרִיךְ לָדַעַת: א׳, לָמָּה תָּלָה אַזְהָרַת שְׁמִירַת עֲבוֹדָה זָרָה בְּ״כִּי יַכְרִית״ שֶׁיֵּרָאֶה שֶׁזּוּלַת זֶה אֵינוֹ בָּאַזְהָרָה כְּשֶׁיִּרְאֶה אֶת הַגּוֹיִם עוֹבְדֵי עֲבוֹדָה זָרָה שְׁלֵוִים וּבְטוּחִים שָׁנִים רַבּוֹת, וְזֶה אֵינוֹ, שֶׁאַזְהָרַת עֲבוֹדָה זָרָה אֵינָהּ מִשְׁתַּנֵּית מֵהַמִּבְחָן בְּמַה שֶׁיֶּאֱרַע לְהָאֻמּוֹת. ב׳, אָמְרוֹ פֶּן תִּנָּקֵשׁ וְגוֹ׳ אַחֲרֵי הִשָּׁמְדָם – הֲלֹא אַדְרַבָּא אַחַר שֶׁיִּרְאֶה שֶׁנִּשְׁמְדוּ לְפָנָיו לֹא יִנָּקֵשׁ אַחֲרֵיהֶם, וְדִבְרֵי הַמָּאוֹר רַשִׁ״י זִכְרוֹנוֹ לִבְרָכָה לֹא הִסְפִּיקוּ בּוֹ יִשּׁוּב הַכָּתוּב עַל נָכוֹן.","complete":false},{"workId":"Kli_Yakar_on_Deuteronomy","unitId":"Kli_Yakar_on_Deuteronomy.14.1","commentator":"כלי יקר","sourceLine":"כלי יקר · Vocalized Edition · נחלת הכלל · ספריא","chapter":14,"verse":1,"dh":"לֹא תִתְגֹּדְדוּ וְגוֹ׳.","text":"לְפִי שֶׁהָאֻמּוֹת מִצְטַעֲרִים כַּדִּין עַל דָּבָר אָבֵד אֲשֶׁר הוֹלֵךְ וְלֹא יָשׁוּב, אֲבָל אַתָּה לֹא כֵן, כִּי בְךָ בָּחַר ה׳ לִהְיוֹת לוֹ לְעַם סְגֻלָּה, וְכָל סְגֻלַּת מְלָכִים הַיְנוּ דָּבָר שֶׁמַּכְנִיסִין לְאוֹצָר, כָּךְ הַקָּדוֹשׁ בָּרוּךְ הוּא מַכְנִיס לְאוֹצָר נַפְשׁוֹת הַצַּדִּיקִים הַטְּהוֹרוֹת, וְאֵינוֹ דָבָר הָאָבֵד, וְלָמָּה יִצְטַעֵר עַל דָּבָר שֶׁיֵּשׁ לוֹ מְצִיאוּת וְזוֹרֵחַ הוּא שָׁם, וְרַק הֶעֱרִיב שִׁמְשׁוֹ בָּעוֹלָם הַזֶּה אֲבָל אוֹכֵל הוּא תְּרוּמוֹתָיו בָּעוֹלָם הַנִּצְחִי? וְרַבּוֹתֵינוּ זִכְרוֹנָם לִבְרָכָה (שבת קה:) אָמְרוּ:","complete":false},{"workId":"Rabbeinu_Bahya_on_Deuteronomy","unitId":"Rabbeinu_Bahya_on_Deuteronomy.14.7","commentator":"רבינו בחיי","sourceLine":"רבינו בחיי · Midrash Rabbeinu Bachya [ben Asher]. Warsaw, 1878 · נחלת הכלל · ספריא","chapter":14,"verse":23,"dh":"למען תלמד ליראה.","text":"כי תמצא שם הכהנים והלוים מורי התורה וילמדו אותך העבודה והיראה. ואמרו במסכת תענית עשר תעשר, א\"ר יוחנן עשר בשביל שתתעשר. והנה אין בלשון הכתוב לשון עושר כי שני השיני\"ן סבולת הן, אבל ר' יוחנן היה מפרש כן עשר בשביל שתעשר ממנו שנים רבות, וזהו העושר, כן כתב הראב\"ד ז\"ל שם בפירושיו. והנה זה בודאי נסיון, והתורה אמרה (דברים ו) לא תנסו, אלא כבר דרשו רז\"ל חוץ מזו, שנאמר (מלאכי ג׳:י׳) הביאו את כל המעשר אל בית האוצר ויהי טרף בביתי ובחנוני נא בזאת וגו'.","complete":true},{"workId":"Sforno_on_Deuteronomy","unitId":"Sforno_on_Deuteronomy.15.8","commentator":"ספורנו","sourceLine":"ספורנו · ובלכתך בדרך · נחלת הכלל · ספריא","chapter":15,"verse":19,"dh":"כל הבכור.","text":"אחר שבאר מיני חסד בתבואה והוא מעשר עני ובמעות והוא שמטת כספים והצדקה ובשאר הקנינים בהענקת עבד עברי. באר מצות אשר בהן הודאה לאל יתעלה והן מתן הבכורות הראוי לבעלי המקנה להודות כי מידו המקנה לנו. וחג המצות להודות על הגאולה בזבח הפסח ובמצות ועל האביב בעומר התנופה. וחג השבועות להודות על שבועות חקות קציר ששמר לנו. וחג האסיף להודות על האסיף ושבכל אחד מהם נביא איזה דורון לאדון כאמרו ולא יראה את פני ה' ריקם. ולזה לא הזכיר בהם באיזה חדש ובכמה בחדש יהיו אבל הזכיר האביב והשבועות והאסיף:","complete":true}],"shoftim":[{"workId":"Kli_Yakar_on_Deuteronomy","unitId":"Kli_Yakar_on_Deuteronomy.16.4","commentator":"כלי יקר","sourceLine":"כלי יקר · Vocalized Edition · נחלת הכלל · ספריא","chapter":16,"verse":18,"dh":null,"text":"בֵּאוּר הָעִנְיָן הוּא, שֶׁפָּסוּק זֶה צִוּוּי לְמִי שֶׁיֵּשׁ סִפֵּק בְּיָדוֹ לְמַנּוֹת דַּיָּנִים, שֶׁיְּמַנֶּה אוֹתָם עַל מְנָת שֶׁיִּהְיוּ דַּיָּנִים וְלֹא יַחֲנִיפוּ אֲפִלּוּ לָזֶה הַמְּמַנֶּה אוֹתָם. וְזֶהוּ שֶׁאָמַר ״תִּתֶּן לְךָ״, עַל עַצְמְךָ. וְנִמְשָׁךְ בָּזֶה בְּקַל וָחֹמֶר שֶׁיִּשְׁפְּטוּ אֶת כָּל הָעָם מִשְׁפַּט צֶדֶק, כִּי אִם לֹא יַחֲנִיפוּ גַּם לְךָ, קַל וָחֹמֶר לְכָל הָעָם. לְכָךְ אָמַר ״וְשָׁפְטוּ״ לְשׁוֹן הוֹדָעַת דְּבָרִים, לוֹמַר שֶׁכָּךְ יִהְיֶה בְּוַדַּאי בְּקַל וָחֹמֶר.","complete":false},{"workId":"Tur_HaArokh_on_Deuteronomy","unitId":"Tur_HaArokh_on_Deuteronomy.17.10","commentator":"טור הארוך","sourceLine":"טור הארוך · Perush al ha-Torah, Hanover, 1838 · נחלת הכלל · ספריא","chapter":17,"verse":14,"dh":"ואמרת אשימה עלי מלך.","text":"כתב הרמב\"ן על דעת רבותי' הוא מצות עשה שחייב אותנו לעשות כן אחר ירושה וישיבה כלשון ועשית מעקה. ואמר ואמרת כי מצוה שיבואו לפני הכהנים והלוים ואל השופט ויאמרו רצונינו שנשים עלינו מלך. ולפי דעתי עוד שגם זה מרמיזותיו על העתידות שכן היה כששאלו את שאול אמרו לשמואל שימה לנו מלך:","complete":true},{"workId":"Or_HaChaim_on_Deuteronomy","unitId":"Or_HaChaim_on_Deuteronomy.18.1","commentator":"אור החיים","sourceLine":"אור החיים · Vocalized Edition · נחלת הכלל · ספריא","chapter":18,"verse":1,"dh":"לֹא יִהְיֶה לַכֹּהֲנִים וְגוֹ׳ וְנַחֲלָה לֹא יִהְיֶה וְגוֹ׳.","text":"כָּפַל הַכָּתוּב הָעִנְיָן לוֹמַר שֶׁהֲגַם שֶׁעָבְרוּ וְנָתְנוּ לָהֶם נַחֲלָה, אוֹתָהּ נַחֲלָה לֹא תָּקוּם לִזְכוּתָם, וְהוּא אָמְרוֹ וְנַחֲלָה לֹא יִהְיֶה וְגוֹ׳. וְטַעַם סְמִיכוּת מִצְוָה זוֹ לְמִצְוַת הַמֶּלֶךְ, לוֹמַר שֶׁהַמֶּלֶךְ שָׁוֶה לָעָם בַּמִּצְווֹת הָאֲמוּרִים בָּעִנְיָן לָתֵת לָהֶם מַתְּנוֹתֵיהֶם, וְלֹא יָרוּם לְבָבוֹ מֵאֶחָיו לְבִלְתִּי סוּר מִן הַמִּצְוָה שֶׁמְּצַוֶּה ה׳ לִכְלָלוּת יִשְׂרָאֵל.","complete":true},{"workId":"Sforno_on_Deuteronomy","unitId":"Sforno_on_Deuteronomy.18.2","commentator":"ספורנו","sourceLine":"ספורנו · ובלכתך בדרך · נחלת הכלל · ספריא","chapter":18,"verse":8,"dh":"לבד ממכריו על האבות.","text":"אין על האבות לחלק למשמרות כהונה אלא ממכריו מה שהיה כל משמר מהם יכול למכור לחבירו בחליפין והם קרבנות כל ימות השנה שיחליף כל משמר עם חביריו את חלקו בקרבנות השנה בעד מה שיתנו לו חלקם בשבוע אחת או שתים אבל קרבנות הרגלים שאין להם חליפין ואינם מכלל ממכריו שיוכלו האבות לחלקם למשמרות לפיכך חלק כחלק יאכלו מהם:","complete":true},{"workId":"Ramban_on_Deuteronomy","unitId":"Ramban_on_Deuteronomy.18.5","commentator":"רמב״ן","sourceLine":"רמב״ן · On Your Way new · נחלת הכלל · ספריא","chapter":18,"verse":15,"dh":"נביא מקרבך מאחיך כמני","text":"טעם מקרבך לרמוז שאין נבואה אלא בארץ ישראל ולכך יאמר בה הכתוב (ישעיהו כב א) משא גיא חזיון וכמו שהזכירו רבותינו (מכילתא ריש בא) וכן טעם מאחיך כי השם נתן לך מעלה על כל העמים ולא יתן רוחו רק עליכם כמוני שאני מקרב אחיך יקים לך תחתי וכן מנביא לנביא לשון רש\"י (רש\"י על דברים י״ח:ט״ו) ואמר רבי אברהם (אבן עזרא על דברים י״ח:ט״ו) כמוני שאני נביא השם לא מעונן וקוסם ויתכן שיהיה מקרבך לומר שתוכל לבטוח בדבריו שהוא מאחיך מקרבך וכן על דעתי כמוני שיהיה נאמן לנביא לה' ותאמין בו כאשר אתה מאמין בי ועוד אבאר זה:","complete":true},{"workId":"Haamek_Davar_on_Deuteronomy","unitId":"Haamek_Davar_on_Deuteronomy.19.14","commentator":"העמק דבר","sourceLine":"העמק דבר · ספר תורת אלוהים, וילנא 1879 · נחלת הכלל · ספריא","chapter":19,"verse":14,"dh":"לא תסיג גבול רעך.","text":"יש בזה שתי אזהרות מבוארות בכתוב כדרך משנה תורה. חדא השגת גבול סימני הקרקע שבינו לחבירו. וזהו לשון גבול רעך. אבל א״כ אין הבנה ללשון אשר גבלו ראשונים אלא יש כאן אזהרה שניה שהובא בספרי שאסור לשנות תחום הארץ שעשו הנשיאים ויהושע. היינו אשר גבלו ראשונים. ולזה הפי׳ אין לשון גבול רעך מדויק שהרי מחליפים כולם זל״ז ברצון. אלא ע״כ מבואר כאן שתי אזהרות. וטעם אזהרה שני׳ הוא כמש״כ כ״פ דחלוקת הארץ היה ענין קדושה שהרי בזה תלוי דין יובל וכמה דינים ש״ת והוא קדושת הגוף דלא פקע בכדי ועי׳ מש״כ בהע״ש סי׳ קל״ח:","complete":true}],"ki-teitzei":[{"workId":"Kli_Yakar_on_Deuteronomy","unitId":"Kli_Yakar_on_Deuteronomy.21.3","commentator":"כלי יקר","sourceLine":"כלי יקר · Vocalized Edition · נחלת הכלל · ספריא","chapter":21,"verse":10,"dh":"כִּי תֵצֵא לַמִּלְחָמָה עַל אוֹיְבֶיךָ וְגוֹ׳.","text":"אוֹיְבֶיךָ בְּיוּ״ד לְשׁוֹן רַבִּים, וְאַחַר כָּךְ אָמַר: ״וּנְתָנוֹ״ – הָיָה לוֹ לוֹמַר ״וּנְתָנָם״. ״עַל אוֹיְבֶיךָ״ – ״כְּנֶגֶד אוֹיְבֶיךָ״ הָיָה לוֹ לוֹמַר. וּבַיַּלְקוּט מַסִּיק בְּשֵׁם הַסִּפְרֵי וְזֶה לְשׁוֹנוֹ: ״עַל אוֹיְבֶיךָ״ – כְּנֶגֶד אוֹיְבֶיךָ, ״וּנְתָנוֹ ה׳ אֱלֹהֶיךָ בְּיָדֶךָ״ – אִם עָשִׂיתָ כָּל הָאָמוּר בָּעִנְיָן סוֹף שֶׁה׳ אֱלֹהֶיךָ נוֹתְנוֹ בְּיָדֶךָ. וְלֹא הֵבַנְתִּי דְּבָרָיו, מַהוּ הָאָמוּר בָּעִנְיָן, אִם זֶה הוּא שֶׁאָמַר:","complete":false},{"workId":"Sforno_on_Deuteronomy","unitId":"Sforno_on_Deuteronomy.21.16","commentator":"ספורנו","sourceLine":"ספורנו · ובלכתך בדרך · נחלת הכלל · ספריא","chapter":21,"verse":23,"dh":"כי קללת אלהים תלוי.","text":"הנה כל עצם נבדל מחומר יקרא אלהים ומזה המין הוא עצם הנפש השכלית באדם הנקראת צלם אלהים. וע\"ז הדרך אמרה בעלת אוב לשאול אלהים ראיתי עולים. ובהיות שהבזיון הנעשה למת אחר מיתה הוא בזיון לנפש השכלית אשר היא עצם נבדל הנשאר אחר מיתת הגוף אמר שהוא קללת אלהים כי הלנת התליה לגוף המת בלתי קבורה היא בזיון לאותו העצם הנצחי הנקרא אלהים:","complete":true},{"workId":"Ramban_on_Deuteronomy","unitId":"Ramban_on_Deuteronomy.22.5","commentator":"רמב״ן","sourceLine":"רמב״ן · On Your Way new · נחלת הכלל · ספריא","chapter":22,"verse":8,"dh":"ועשית מעקה","text":"מצות המעקה מחודשת או מבוארת מלא תעמוד על דם רעך (ויקרא יט טז) אבל מצות הכלאים מבוארת שכבר אמר (שם פסוק יט) שדך לא תזרע כלאים והנה במשמע ההוא כל מקום הנזרע והוסיף בכאן כי אם יזרע הכרם כלאים יקדש הזרע אשר יזרע ותבואת הכרם לומר שיאסר בהנאה כהקדש וטעם \"פן\" כמו כי תקדש וכן ומפתח אהל מועד לא תצאו פן תמותו (שם י ז) וכן ולא תגעו בו פן תמותון (בראשית ג ג) ויתכן שפירושו כמו פן ינכרו צרימו פן יאמרו ידינו רמה (דברים ל״ב:כ״ז) כענין שמא לומר לא תזרע אותו כלאים פן יצמח ויאסר עליך הכל כי אינן נאסרין אלא כמו ששנינו (כלאים פ\"ז ה\"ז) תבואה מתקדשת משתשריש וענבים משיעשו כפול הלבן:","complete":true},{"workId":"Or_HaChaim_on_Deuteronomy","unitId":"Or_HaChaim_on_Deuteronomy.23.13","commentator":"אור החיים","sourceLine":"אור החיים · Vocalized Edition · נחלת הכלל · ספריא","chapter":23,"verse":10,"dh":"כִּי תֵצֵא מַחֲנֶה וְגוֹ׳.","text":"פֵּרוּשׁ, הֲגַם שֶׁיֵּשׁ דִּקְדּוּקֵי עֲבֵרוֹת שֶׁה׳ לֹא יַעֲנִישׁ עֲלֵיהֶם, וְאִם יַעֲנִישׁ יִהְיֶה עֹנֶשׁ קַל, מוֹדִיעַ הַכָּתוּב שֶׁבִּשְׁעַת הַסַּכָּנָה, שֶׁהוּא בִּזְמַן שֶׁיּוֹצְאִים עַל אוֹיְבֵיהֶם, צְרִיכִין שְׁמִירָה מִכָּל דִּקְדּוּקֵי עֲבֵרוֹת, כְּאָמְרוֹ מִכֹּל דָּבָר רָע וְגוֹ׳. וְכָלַל בְּתֵבַת דָּבָר גַּם סִבּוֹת שֶׁמִּמֶּנּוּ יְסֻבַּב הָרָע.","complete":false},{"workId":"Haamek_Davar_on_Deuteronomy","unitId":"Haamek_Davar_on_Deuteronomy.23.34","commentator":"העמק דבר","sourceLine":"העמק דבר · ספר תורת אלוהים, וילנא 1879 · נחלת הכלל · ספריא","chapter":23,"verse":26,"dh":"וחרמש לא תניף.","text":"איסור חדש מה שאינו בכרם דשם לא הוזהר לתלוש הענבים בכלי שבוצר לבעליו. אבל בקמה האזהרה שלא יקטוף כי אם ביד ולא בכלי שקוצר לבעלים. והטעם דבכלי בצירה אפשר לבצור מעט או הרבה כפי שנדרש אבל בחרמש א״א לקצור פחות ממלא החרמש ואפשר שלא יהיה נצרך לאכילת מלא חרמש. ע״כ אסרה תורה שלא יקצור לעצמו כלל:","complete":true},{"workId":"Rabbeinu_Bahya_on_Deuteronomy","unitId":"Rabbeinu_Bahya_on_Deuteronomy.24.8","commentator":"רבינו בחיי","sourceLine":"רבינו בחיי · Midrash Rabbeinu Bachya [ben Asher]. Warsaw, 1878 · נחלת הכלל · ספריא","chapter":24,"verse":6,"dh":"לא יחבול רחים ורכב.","text":"טעמו לא יחבול החובל, לפי שהם כלי המזון וחיי הנפשות. והזכירה תורה אלו והוא הדין לשאר הכלים שיש בהם אוכל נפש. ובאור לא יחבול שלא יכנס לביתו של לוה למשכנו, שאפילו בכלים שאין עושים בהן אוכל נפש אינו רשאי, שהרי אמר הכתוב לא תבא אל ביתו לעבוט עבוטו, שאי אפשר לו למלוה בשום פנים ליכנס לביתו של לוה כלל למשכנו, ואפילו שליח ב\"ד, שנאמר בחוץ תעמוד והאיש וגו', וא\"כ למה הוצרך לומר לא יחבול לעבור עליו בשני לאוין.","complete":true}],"ki-tavo":[{"workId":"Or_HaChaim_on_Deuteronomy","unitId":"Or_HaChaim_on_Deuteronomy.26.2","commentator":"אור החיים","sourceLine":"אור החיים · Vocalized Edition · נחלת הכלל · ספריא","chapter":26,"verse":1,"dh":"אֲשֶׁר ה׳ אֱלֹהֶיךָ נוֹתֵן לְךָ נַחֲלָה וִירִשְׁתָּהּ וְגוֹ׳.","text":"צָרִיךְ לָדַעַת מַה הִיא גְּזֵרַת הַכָּתוּב, אִם ״וְלָקַחְתָּ״ וְגוֹ׳ הֲוָה לֵיהּ לְמֵימַר ״תִּקַּח מֵרֵאשִׁית״ כֵּיוָן שֶׁהוּא הַתְחָלַת הַצִּוּוּי. וְנִרְאֶה שֶׁכַּוָּנַת הַכָּתוּב הִיא שֶׁיְּצַו ה׳ אַרְבַּע מִצְווֹת: אֶחָד – שֶׁיֵּדַע בְּלִבּוֹ כִּי לֹא בְּכֹחוֹ וְלֹא בְּעֹצֶם גְּבוּרָתוֹ בָּא לָרֶשֶׁת הָאָרֶץ אֶלָּא מַתַּת ה׳, וְהוּא אָמְרוֹ ״אֲשֶׁר ה׳ אֱלֹהֶיךָ נוֹתֵן לְךָ״. וְדִקְדֵּק לוֹמַר ה׳ אֱלֹהֶיךָ לְהָעִיר שֶׁעַל מְנָת שֶׁיְּקַבֵּל אֱלֹהוּתוֹ עָלָיו הוּא נוֹתֵן.","complete":false},{"workId":"Haamek_Davar_on_Deuteronomy","unitId":"Haamek_Davar_on_Deuteronomy.26.25","commentator":"העמק דבר","sourceLine":"העמק דבר · ספר תורת אלוהים, וילנא 1879 · נחלת הכלל · ספריא","chapter":26,"verse":12,"dh":"שנת המעשר.","text":"מ״ע. כפי׳ הראב״ע. ונקרא ביחוד מעשר עני. שנת המעשר סתם. באשר מ״ר באמת אינו מתנה ללוי שהרי לא נטל חלק בארץ. ואין בזה מתנה כי אם עבודת האדמה והוא חלף עבודתם באהל מועד. וכבר ביארנו בזה בפ׳ קרח. וכן מע״ש הרי הוא בא לאכילת הבעלים בירושלים. אבל מ״ע הוא רק לכבוד ה׳ ומש״ה אי׳ בירו׳ פאה פ״א כבד את ה׳ מהונך ומראשית כל תבואתך. מהונך כמראשית כל תבואתך. והיינו מ״ע. הרי דרק מ״ע מכונה בשם כבוד ה׳. באשר אינו בא אלא לכבודו. וגם ניתן לעניים דכתיב בהו ומכבדו חונן אביון. מש״ה נקרא סתם מעשר:","complete":true},{"workId":"Ramban_on_Deuteronomy","unitId":"Ramban_on_Deuteronomy.26.10","commentator":"רמב״ן","sourceLine":"רמב״ן · On Your Way new · נחלת הכלל · ספריא","chapter":26,"verse":17,"dh":"וללכת בדרכיו","text":"שתעשו הטוב והישר ותגמלו חסד איש את רעהו ולשמר חקיו ומצותיו ומשפטיו יזכיר בפרט החוקים והמשפטים כאשר פירשתי (רמב\"ן על דברים ד׳:ה׳) ויכלול במצותיו כל המצות מצות עשה ולא תעשה ולשמע בקלו ככל אשר יצוה לכם משאר המעשים על ידי או על יד שאר הנביאים כאשר פירשתי (רמב\"ן על דברים י״ג:ה׳) ויתכן שיהו מצותיו מצות עשה ולשמוע בקולו המניעות כלומר מצות לא תעשה:","complete":true},{"workId":"Rabbeinu_Bahya_on_Deuteronomy","unitId":"Rabbeinu_Bahya_on_Deuteronomy.27.1","commentator":"רבינו בחיי","sourceLine":"רבינו בחיי · Midrash Rabbeinu Bachya [ben Asher]. Warsaw, 1878 · נחלת הכלל · ספריא","chapter":27,"verse":1,"dh":"שמור את כל המצוה.","text":"היא מצות הקמת האבנים שמזכיר והולך והקמות לך אבנים גדולות, כלומר מתוך הירדן, ואבנים אלו היו לאות ולזכרון לנס הירדן. וצוה לכתוב עליהן כל התורה, והיו שתים עשרה כי כן כתוב בספר יהושע (יהושע ד׳:ד׳-ה׳) איש אחד משבט, וכתיב (שם) ויאמר להם יהושע עברו לפני ארון ה' אלהיכם אל תוך הירדן והרימו לכם איש אבן אחת על שכמו למספר שבטי בני ישראל, ועשה זה לאות ולזכרון שנכרתו מימי הירדן מפני הארון בעברו בירדן, ושתים עשרה אבנים אלו שלקחו מתוך הירדן העבירום עמהם במלון שהוא הגלגל אשר שם הקימם יהושע, וכתיב (שם) כי ישאלון בניכם מחר לאמר מה האבנים האלה לכם, ואמרתם להם אשר נכרתו מימי הירדן מפני ארון ברית ה'.","complete":false},{"workId":"Kli_Yakar_on_Deuteronomy","unitId":"Kli_Yakar_on_Deuteronomy.27.1","commentator":"כלי יקר","sourceLine":"כלי יקר · Vocalized Edition · נחלת הכלל · ספריא","chapter":27,"verse":12,"dh":"אֵלֶּה יַעַמְדוּ לְבָרֵךְ אֶת הָעָם וְגוֹ׳.","text":"וּבַקְּלָלוֹת לֹא נֶאֱמַר ״אֵלֶּה יַעַמְדוּ לְקַלֵּל״, לְפִי שֶׁהַטּוֹבוֹת בָּאוֹת מֵאֵת ה׳ בְּפֹעַל, אֲבָל הַקְּלָלוֹת אֵינָן בָּאִים כִּי אִם מֵעַצְמָם עַל יְדֵי הֶסְתֵּר פָּנָיו יִתְבָּרַךְ, כִּי מִפִּי עֶלְיוֹן לֹא תֵצֵא הָרָעוֹת (איכה ג לח). לְכָךְ נֶאֱמַר ״וְאֵלֶּה יַעַמְדוּ עַל הַקְּלָלָה״ וְלֹא ״לְקַלֵּל״ כִּי אִם לְיַעֵד בִּיאַת הַקְּלָלוֹת, וְהַדָּבָר בְּסָפֵק אִם יָבֹאוּ אוֹ לֹא, כִּי מֵאַחַר שֶׁאֵינָן בָּאִים כִּי אִם בְּהֶסְתֵּר פָּנִים, אִם כֵּן עֲדַיִן הַדָּבָר תָּלוּי בְּהוֹרָאַת הַמַּעֲרָכָה.","complete":true}],"nitzavim":[{"workId":"Ramban_on_Deuteronomy","unitId":"Ramban_on_Deuteronomy.29.3","commentator":"רמב״ן","sourceLine":"רמב״ן · On Your Way new · נחלת הכלל · ספריא","chapter":29,"verse":9,"dh":null,"text":"טעם אתם נצבים היום לפני ה' אלהיכם שאתם עומדים ומזומנים לפני השם כדי לעמוד בבריתו כי לקבל התורה בבאורה נאספו אליו או שהיו עומדים לפני הארון והברית הוא השבועה והאלה אשר יזכיר לעברך בברית ה' אלהיך ובאלתו ויתכן שכרת עוד עמם ברית כברית הראשונה אשר כרת אתם בהר סיני (שמות כד ה-ח) שהקריב עליהם עולה ולקח חצי הדם לזרוק על המזבח וחצי הדם זרק על העם אבל לא הוצרך להזכיר זה ועל דרך האמת כבר הודעתיך הברית הזאת:","complete":true},{"workId":"Haamek_Davar_on_Deuteronomy","unitId":"Haamek_Davar_on_Deuteronomy.29.18","commentator":"העמק דבר","sourceLine":"העמק דבר · ספר תורת אלוהים, וילנא 1879 · נחלת הכלל · ספריא","chapter":29,"verse":12,"dh":"למען הקים אותך היום לו לעם וגו׳.","text":"עוד היום על תוקף העונשים מלבד פיוס הא׳ שנתבאר שנדרש להיות כן כדי שיגיע מזה קידוש שמו ית׳ שלזה נוצרו. וזה אינו פיוס אלא על יסורים שמגיע מאוה״ע שכסו עלינו צלמות. אבל על חליים רעים ונאמנים בעונשי שמים אשר אין בזה קדה״ש אין בזה פיוס כלל. ע״ז אמר עוד שהוא כדי להקים אותך להיות לו לעם. ומשמעות עם כבר ביארנו לעיל כ״ו י״ח מלשון אנשי חיל המיוחדים מכל המדינה. הן במה שהמה מושגחים ביחוד מן המלוכה במלוי כ״צ לכל אחד לפי ערכו. הן במה שנענשים ביותר על העותם בעונשי הגוף יותר מעונשי אנשי המדינה משום שנקראים על שמו ויש בהעותם בזיון המלך. כך ההבדל בין אוה״ע לכלל ישראל דאוה״ע המה כעבדים יושבי הארץ.","complete":false},{"workId":"Or_HaChaim_on_Deuteronomy","unitId":"Or_HaChaim_on_Deuteronomy.29.11","commentator":"אור החיים","sourceLine":"אור החיים · Vocalized Edition · נחלת הכלל · ספריא","chapter":29,"verse":15,"dh":"כִּי אַתֶּם יְדַעְתֶּם וְגוֹ׳.","text":"צָרִיךְ לָדַעַת לְאֵיזֶה דָּבָר נוֹתֵן הַכָּתוּב טַעַם ״כִּי אַתֶּם יְדַעְתֶּם״, וְרַמְבַּ״ן זִכְרוֹנוֹ לִבְרָכָה פֵּרֵשׁ שֶׁהוּא טַעַם לְהָאָמוּר אַחֲרָיו בְּסָמוּךְ ״פֶּן יֵשׁ בָּכֶם״ וְגוֹ׳, וְהוּא קְצָת דֹּחַק לְהַקְדִּים טַעַם לְמַה שֶׁעָתִיד לוֹמַר אַחֲרֵי כֵן. וְאוּלַי שֶׁדִּבֵּר הַכָּתוּב בְּסֵדֶר זֶה לְהָעִיר דָּבָר אֶחָד, וְהוּא כִּי לְפִי שֶׁהִצְרִיכָם הַכָּתוּב לְהִכָּנֵס לְחַיֵּב עִמָּהֶם גַּם הַבָּאִים אַחֲרֵיהֶם, יֹאמַר הָאוֹמֵר שֶׁשּׁוּרַת הַדִּין מְנַגֶּדֶת הַדָּבָר, שֶׁהֲרֵי אֵין חָבִין לְאָדָם שֶׁלֹּא בְּפָנָיו (כתובות יא.), וְלֹא תוֹעִיל קַבָּלָה זוֹ שֶׁיְּקַבְּלוּ הָאָבוֹת עַל הַבָּנִים.","complete":false},{"workId":"Rabbeinu_Bahya_on_Deuteronomy","unitId":"Rabbeinu_Bahya_on_Deuteronomy.30.1","commentator":"רבינו בחיי","sourceLine":"רבינו בחיי · Midrash Rabbeinu Bachya [ben Asher]. Warsaw, 1878 · נחלת הכלל · ספריא","chapter":30,"verse":2,"dh":"ושבת עד ה' אלהיך וגו', בכל לבבך ובכל נפשך, ושב ה' אלהיך את שבותך.","text":"כבר ידעת מאמר רז\"ל בפרק ראשון של עבודה זרה, אין בן דוד בא עד שיכלו כל הנשמות שבגוף, שנאמר (שם נז) כי רוח מלפני יעטוף ונשמות אני עשיתי. ובאור הכתוב כי לא לעולם אריב עם ישראל ולא לנצח אקצוף שלא אגאל אתכם, כי רוח מלפני יעטוף, כלומר מה שאני גואל אותם זהו בסבת הרוחות אשר הן יוצאין מלפניו, ונשמות שאני עשיתי שהן מתאחרות ליכנס בגוף, ומלת יעטוף לשון אחור, מלשון (בראשית ל) העטופים ללבן.","complete":true},{"workId":"Sforno_on_Deuteronomy","unitId":"Sforno_on_Deuteronomy.30.15","commentator":"ספורנו","sourceLine":"ספורנו · ובלכתך בדרך · נחלת הכלל · ספריא","chapter":30,"verse":11,"dh":"כי המצוה הזאת.","text":"והטעם שאמרתי והשבות אל לבבך בכל הגוים שצריך שהתשובה תהי' בעודך בגלות למען תושע הוא כי אמנם זאת המצוה של תשובה אשר אנכי מצוך היום כאמרו בכל חטא בפרשת ויקרא ואשם ואשמו שהענין כולם הוא שיכיר החוטא את חטאו כמו שפירש אח\"כ באמרו והיה כי יאשם לאחת מאלה והתודה אשר חטא עליה וכן באמרו איש או אשה כי יעשו מכל חטאת האדם ואשמה הנפש ההיא והתודו את עונם.","complete":true},{"workId":"Kli_Yakar_on_Deuteronomy","unitId":"Kli_Yakar_on_Deuteronomy.30.12","commentator":"כלי יקר","sourceLine":"כלי יקר · Vocalized Edition · נחלת הכלל · ספריא","chapter":30,"verse":15,"dh":"רְאֵה נָתַתִּי לְפָנֶיךָ הַיּוֹם אֶת הַחַיִּים וְאֶת הַטּוֹב.","text":"כִּי אִם חַיִּים אַתָּה מְבַקֵּשׁ, צַפֵּה לַטּוֹב, לַעֲשׂוֹת הַטּוֹב בְּעֵינֵי ה׳. וְאִם תֹּאמַר, לָמָּה לֹא הִקְדִּים הַטּוֹב, שֶׁהֲרֵי עַל יְדֵי מַעֲשֵׂה הַטּוֹב יִזְכֶּה לְחַיִּים. תְּשׁוּבָה לַדָּבָר, שֶׁבָּא לְהַזְהִירוֹ שֶׁלֹּא יְבַקֵּשׁ לַעֲשׂוֹת הַטּוֹב בְּעֵינֵי ה׳ כְּדֵי שֶׁיִּחְיֶה, אֶלָּא יִחְיֶה כְּדֵי שֶׁיַּעֲשֶׂה טוֹב, שֶׁלֹּא יְבַקֵּשׁ חַיִּים גּוּפָנִיִּים, כִּי אִם יְבַקֵּשׁ הַחַיִּים כְּדֵי שֶׁיּוּכַל לַעֲבֹד בִּימֵי חַיָּיו אֶת בּוֹרְאוֹ, כְּמוֹ שֶׁכָּתוּב (תהלים לד יג):","complete":false}],"vayeilech":[{"workId":"Ramban_on_Deuteronomy","unitId":"Ramban_on_Deuteronomy.31.1","commentator":"רמב״ן","sourceLine":"רמב״ן · On Your Way new · נחלת הכלל · ספריא","chapter":31,"verse":1,"dh":"וילך משה","text":"כאשר השלים כל דבריו אז הלכו כל הנצבים לפניו והטף והנשים איש לאהליו ולא הוצרך הכתוב להזכיר זה כי כבר אמר (לעיל כט ט יא) אתם נצבים היום כלכם לפני ה' אלהיכם וגו' לעברך בברית ה' אלהיך ואחר עברם בברית ילכו מפניו ויאמר הכתוב עתה כי משה הלך ממחנה לויה אל מחנה ישראל לכבדם כמי שירצה להפטר מחבירו ובא ליטול רשות ממנו:","complete":true},{"workId":"Haamek_Davar_on_Deuteronomy","unitId":"Haamek_Davar_on_Deuteronomy.31.12","commentator":"העמק דבר","sourceLine":"העמק דבר · ספר תורת אלוהים, וילנא 1879 · נחלת הכלל · ספריא","chapter":31,"verse":6,"dh":"ואל תערצו.","text":"ת״א לא תתברון. וכן ת״א על ואל תחת ואל תתבר. מכ״מ ודאי יש שנוי כונות. הערצה הוא שבירת הגדוד שמוסרים עצמם ביד האויב. וכמש״כ בס׳ שמות ט״ו ו׳. ומחיתה הוא שבירת הלב בפ״ע. ע״כ כשהזהיר את ישראל. הוצרך להזהירם שאפי׳ יראו בעצמם במעמד רע איזה גדוד פרטי. והיה אפשר למסור זה הגדוד להאויב. ע״ז הזהירם שלא ישברו את הגדוד בשו״א ויהיו בטוחים שאח״כ ינצחו המה. וע׳ לעיל ז׳ כ״א. משא״כ כשבא להזהיר ליהושע לא היה נצרך להזהיר שלא יהי נמסר הוא להאויב. דא״כ ממילא כל מחנה ישראל ככלל. וזה לא היה עולה עה״ד. אלא נצרך להזהיר שלא יהי לבבו נשבר בשעה שיראה המעמד שלא בטוב. והקב״ה אמר ליהושע בתחלת המלחמה לא תערוץ ולא תחת.","complete":false},{"workId":"Kli_Yakar_on_Deuteronomy","unitId":"Kli_Yakar_on_Deuteronomy.31.6","commentator":"כלי יקר","sourceLine":"כלי יקר · Vocalized Edition · נחלת הכלל · ספריא","chapter":31,"verse":7,"dh":"וַיִּקְרָא מֹשֶׁה לִיהוֹשֻׁעַ וַיֹּאמֶר אֵלָיו לְעֵינֵי כָל יִשְׂרָאֵל וְגוֹ׳.","text":"וְכִי כָּל הָעָם הָיוּ רוֹאִים אֶת הַקּוֹלוֹת? מַהוּ ״וַיֹּאמֶר לְעֵינֵי כָל יִשְׂרָאֵל״? וּמַהוּ ״חֲזַק וֶאֱמָץ״, וְכִי בּוֹ תַּלְיָא? כִּי אִם ה׳ לֹא יְחַזֵּק יָדוֹ, וִיהוֹשֻׁעַ מַה הוּא כִּי יֹאמַר לוֹ ״חֲזַק וֶאֱמָץ״? גַּם יֵשׁ לְכָל מַשְׂכִּיל לְהִתְבּוֹנֵן בַּשִּׁנּוּיִים שֶׁבָּאוּ בֵּין דִּבְרֵי מֹשֶׁה לִיהוֹשֻׁעַ וּבֵין דִּבְרֵי הַקָּדוֹשׁ בָּרוּךְ הוּא לִיהוֹשֻׁעַ, כִּי מֹשֶׁה אָמַר: ״כִּי אַתָּה תָּבוֹא אֶת הָעָם״, וְהַקָּדוֹשׁ בָּרוּךְ הוּא אָמַר: ״כִּי אַתָּה תָּבִיא״. וּמַה שֶּׁפֵּרֵשׁ רַשִׁ״י שֶׁמֹּשֶׁה אָמַר:","complete":false},{"workId":"Rabbeinu_Bahya_on_Deuteronomy","unitId":"Rabbeinu_Bahya_on_Deuteronomy.31.8","commentator":"רבינו בחיי","sourceLine":"רבינו בחיי · Midrash Rabbeinu Bachya [ben Asher]. Warsaw, 1878 · נחלת הכלל · ספריא","chapter":31,"verse":10,"dh":"מקץ שבע שנים במועד שנת השמטה בחג הסכות.","text":"זו היא מצות הקהל, ופירוש מקץ מסוף, וכן כל לשון קץ האמור ענינו סוף, כלשון (בראשית ו) קץ כל בשר בא לפני, והכוונה בסוף השבע שנים, כלומר אחר שיעברו השבע שנים לגמרי, וזהו שמינית בחולו של מועד של חג הסכות. אבל מה שכתוב במצות השמטה (דברים טו) מקץ שבע שנים תעשה שמטה, פירוש מסוף שבע שנים, ויהיה הסוף הזה מכלל השבע, לא שיעברו השבע, וכן אמרו רז\"ל שביעית אינה משמטת אלא בסוף, והוא שקיעת החמה של מוצאי שביעית, וא\"כ הקץ שנאמר כאן והנאמר בשמטה הכל אחד, וזה וזה לשון סוף הוא, אלא שהקץ האמור כאן הוא חוץ למספר השבע והאמור בשמטה הוא מכלל השבע.","complete":true},{"workId":"Tur_HaArokh_on_Deuteronomy","unitId":"Tur_HaArokh_on_Deuteronomy.31.5","commentator":"טור הארוך","sourceLine":"טור הארוך · Perush al ha-Torah, Hanover, 1838 · נחלת הכלל · ספריא","chapter":31,"verse":15,"dh":"ויעמוד עמוד הענן על פתח האהל.","text":"כתב הרמב\"ן הטעם כי רצה לדבר עם משה שישמע יהושע ושם יצוה וצוה את יהושע הוא בעצמו. והנה למשה נאמר ונועדתי לך שם ודברתי עמך מעל הכפורת אבל יהושע לא היה במעלה ההיא ואסור היה לו לכנוס באהל כלל ועל כן אמר ויעמוד עמוד הענן פתח האהל לבאר כי היה הענן וכל הכבוד על פתח האהל חופף עליו:","complete":true},{"workId":"Or_HaChaim_on_Deuteronomy","unitId":"Or_HaChaim_on_Deuteronomy.31.43","commentator":"אור החיים","sourceLine":"אור החיים · Vocalized Edition · נחלת הכלל · ספריא","chapter":31,"verse":27,"dh":"הֵן בְּעוֹדֶנִּי חַי עִמָּכֶם.","text":"יִתְבָּאֵר עַל דֶּרֶךְ אָמְרָם זִכְרוֹנָם לִבְרָכָה (ברכות יח.) צַדִּיקִים בְּמִיתָתָם קְרוּיִים חַיִּים, וְהוּא אָמְרוֹ ״בְּעוֹדֶנִּי חַי עִמָּכֶם״, פֵּרוּשׁ בְּעוֹד שֶׁהַחַיִּים שֶׁלִּי עִמָּכֶם, הָא לָמַדְתָּ שֶׁאַחֲרֵי כֵּן הוּא חַי גַּם כֵּן אֶלָּא שֶׁאֵינוֹ עִמָּהֶם.","complete":true}],"haazinu":[{"workId":"Haamek_Davar_on_Deuteronomy","unitId":"Haamek_Davar_on_Deuteronomy.32.3","commentator":"העמק דבר","sourceLine":"העמק דבר · ספר תורת אלוהים, וילנא 1879 · נחלת הכלל · ספריא","chapter":32,"verse":1,"dh":"ותשמע הארץ.","text":"המושפעים שגם המה פועלים הרבה בקבלת השפעה כלשון הנביא הושע ב׳ אענה את השמים והמה יענו את הארץ והארץ תענה את הדגן וגו׳. בכ״ז בפקודה קלה. ובלשון רכה תשמע. והיינו אמרי פי. ולא אמר אמרי שמשמעו אחר דבור. מלשון אימרא ומחבר ענינים אבל כאן משמעו דבר ה׳ בלשון רכה. וזהו ההתראה שמתרה בהם. ומפרש","complete":true},{"workId":"Rabbeinu_Bahya_on_Deuteronomy","unitId":"Rabbeinu_Bahya_on_Deuteronomy.32.26","commentator":"רבינו בחיי","sourceLine":"רבינו בחיי · Midrash Rabbeinu Bachya [ben Asher]. Warsaw, 1878 · נחלת הכלל · ספריא","chapter":32,"verse":7,"dh":"בינו שנות דור ודור.","text":"כלומר שיבינו מה שנעשה בדורות משעה ששרתה שכינה בהם, זהו שאמר ימצאהו בארץ מדבר. ומלת יצב מקור, כמו להציב, וכן (ירמיה א) לא ידעתי דבר, ויהיה באור הכתוב, כשהקב\"ה הנחיל את האומות וכשהפריד אותם ללשונותם, כענין שכתוב בתולדות שיצאו מנח (בראשית י׳:ל״ב) ומאלה נפרדו הגוים, ותמצא באותה פרשה בתולדות ההם שבעים איש לרמוז על שבעים אומות שעתידין לצאת מהם, ועל כן יבאר הכתוב כי כשהפריד הקב\"ה הלשונות להציב גבולות העמים שהן שבעים, למספר בני ישראל יורדי מצרים שהיו שבעים נפש לא בחר מכולן אלא ישראל שהבדילו לחלקו, זהו כי חלק ה' עמו.","complete":false},{"workId":"Rashbam_on_Deuteronomy","unitId":"Rashbam_on_Deuteronomy.32.23","commentator":"רשב״ם","sourceLine":"רשב״ם · רשב\"ם על דברים - דעת · נחלת הכלל · ספריא","chapter":32,"verse":14,"dh":null,"text":"חלב כרים - אילים מדבריות המפוטמים במרעה, כדכתיב: ירעה מקנך כר נרחב. וכן: לבשו כרים הצאן - דוגמת סוף הפסוק. ועמקים יעטפו בר - הכרים של תבואה לבשו את הצאן, מלאים צאן לרעות בהם. וכן: ואויבי ה' כיקר כרים - כמניעת שדי תבואות שמשתדפין ברגע אחד סמוך לקציר בעוד לילה. כלו בעשן כלו - בשרפת אש. וסופן משחירין. ואני כך ראיתי כך בקציר כן הרשעים, תחלה מצליחים כתבואת כרים ויהפך עליהם לילה וידכאו.","complete":true},{"workId":"Kli_Yakar_on_Deuteronomy","unitId":"Kli_Yakar_on_Deuteronomy.32.39","commentator":"כלי יקר","sourceLine":"כלי יקר · Vocalized Edition · נחלת הכלל · ספריא","chapter":32,"verse":20,"dh":"אֶרְאֶה מָה אַחֲרִיתָם כִּי דוֹר תַּהְפֻּכֹת הֵמָּה.","text":"יִשְׂרָאֵל נִקְרְאוּ בִּשְׁלֹשָׁה שֵׁמוֹת: יַעֲקֹב, יִשְׂרָאֵל, יְשֻׁרוּן, וְסוֹפֵי תֵּבוֹת שֶׁלָּהֶם ״לָבָן״, עַל שֵׁם שֶׁבִּזְכוּתוֹ שֶׁל יַעֲקֹב יַלְבִּין ה׳ עֲוֹנוֹתָם, וְהֵמָּה הָפְכוּ מִלַּת ״לָבָן״ לְ״נָבָל״, כְּמוֹ שֶׁכָּתוּב לְמַעְלָה: ״עַם נָבָל וְלֹא חָכָם״ כְּאָמְרוּ רַבּוֹתֵינוּ זִכְרוֹנָם לִבְרָכָה (סנהדרין צז.): דּוֹר שֶׁל מָשִׁיחַ יִתְהַפֵּךְ הַכֹּל לְמִינוּת, מַאי קְרָא, שֶׁנֶּאֱמַר (ויקרא יג יג): ״כֻּלּוֹ הָפַךְ לָבָן טָהוֹר הוּא״, רוֹצֶה לוֹמַר כִּי הִפּוּךְ תֵּבַת ״לָבָן״ הוּא ״נָבָל״. עַל כֵּן אָמַר כָּאן:","complete":false},{"workId":"Or_HaChaim_on_Deuteronomy","unitId":"Or_HaChaim_on_Deuteronomy.32.59","commentator":"אור החיים","sourceLine":"אור החיים · Vocalized Edition · נחלת הכלל · ספריא","chapter":32,"verse":30,"dh":"אֵיכָה יִרְדֹּף.","text":"יֵשׁ לְפָרְשׁוֹ הֶעָרָה לַגּוֹי שֶׁאֵינוֹ מִתְעוֹרֵר בְּהֶעָרָה נִרְגֶּשֶׁת שֶׁהִיא ״אֵיכָה יִרְדֹּף אֶחָד״ וְגוֹ׳, פֵּרוּשׁ, אֶחָד מֵהָאֻמּוֹת אֶלֶף מִיִּשְׂרָאֵל, פֵּרוּשׁ כִּי בְּכָל מִלְחָמוֹת הָרְגִילִים בֵּין הָאֻמּוֹת לֹא יִמָּצֵא דָּבָר כָּזֶה, שֶׁאֵין שׂוֹנֵא מַשִּׂיג כֹּחַ וּגְבוּרָה כָּזוֹ בֵּין הָעַמִּים.","complete":true}],"vezot-haberakhah":[{"workId":"Rabbeinu_Bahya_on_Deuteronomy","unitId":"Rabbeinu_Bahya_on_Deuteronomy.33.2","commentator":"רבינו בחיי","sourceLine":"רבינו בחיי · Midrash Rabbeinu Bachya [ben Asher]. Warsaw, 1878 · נחלת הכלל · ספריא","chapter":33,"verse":1,"dh":"שלמה","text":"המלך ע\"ה בפרשה החתומה בפסוק זה (משלי לא) התחיל אשת חיל מי ימצא, ועל דרך הפשט דבר באשה משכלת זריזה בעניני ביתה מתעמלת וטורחת במלאכתה ביום ובלילה, הוא שאמר (שם) טעמה כי טוב סחרה לא יכבה בלילה נרה, והיא מפורסמת בטוב הנהגתה עם העניים, מחזקת בידם ומפרנסת אותם מיגיע כפיה, הוא שאמר (שם) כפה פרשה לעני וידיה שלחה לאביון. ומתוך הפרשה הזאת למדנו מוסר ודרך ארץ שישתדל האדם אחר האשה הטובה, לפי שהיא יסוד הבית ועקרו, ועמה יבנה ויתכונן.","complete":false},{"workId":"Tur_HaArokh_on_Deuteronomy","unitId":"Tur_HaArokh_on_Deuteronomy.33.20","commentator":"טור הארוך","sourceLine":"טור הארוך · Perush al ha-Torah, Hanover, 1838 · נחלת הכלל · ספריא","chapter":33,"verse":8,"dh":"וללוי אמר.","text":"פירש\"י ועל לוי אמר כמו אמרי לי אחי הוא. וכתב הרמב\"ן ולפי דעתי כי בעבור שהזכיר משה בברכתו שם ראובן ויהודה יחי ראובן קול יהודה ולא הזכיר שם שאר השבטים בברכתם לכך אמר זה הלשון וללוי ולבנימין לומר כי היו השבטים לפניו וקורא ללוי ומשיא עיניו עליו ואומר תומיך ואוריך וכן לכל שבט ושבט ברך אותם פנים אל פנים:","complete":true},{"workId":"Kli_Yakar_on_Deuteronomy","unitId":"Kli_Yakar_on_Deuteronomy.33.19","commentator":"כלי יקר","sourceLine":"כלי יקר · Vocalized Edition · נחלת הכלל · ספריא","chapter":33,"verse":13,"dh":"וּלְיוֹסֵף אָמַר מְבֹרֶכֶת ה׳ אַרְצוֹ.","text":"בְּרָכָה זוֹ הִיא מַמָּשׁ מֵעֵין בִּרְכַּת יַעֲקֹב שֶׁבֵּרְכוֹ בְּרִבּוּי הַתְּבוּאוֹת, עַל שֶׁהָיָה זָן וּמְפַרְנֵס אֶת כָּל בֵּית יִשְׂרָאֵל. וְהוֹסִיף כָּאן מִמֶּגֶד תְּבוּאוֹת שֶׁמֶשׁ וְיָרֵחַ, כִּי כְּבָר נִשְׁתַּעְבְּדוּ לוֹ בַּחֲלוֹמוֹ, ״וְהִנֵּה הַשֶּׁמֶשׁ וְהַיָּרֵחַ״ וְגוֹ׳ (בראשית לז ט).","complete":true},{"workId":"Or_HaChaim_on_Deuteronomy","unitId":"Or_HaChaim_on_Deuteronomy.33.61","commentator":"אור החיים","sourceLine":"אור החיים · Vocalized Edition · נחלת הכלל · ספריא","chapter":33,"verse":18,"dh":"שְׂמַח זְבוּלֻן וְגוֹ׳.","text":"הֲגַם שֶׁבְּעִנְיְנֵי עוֹלָם הַזֶּה בִּכְלָלוּת אֵין לִשְׂמוֹחַ בָּהֶם, דִּכְתִיב (קהלת ב:ב) ״וּלְשִׂמְחָה מַה זֹּה עוֹשָׂה״, אָמַר הַנָּבִיא שֶׁזְּבוּלוּן יֶשְׁנוֹ בְּשִׂמְחָה, הֲגַם בִּיצִיאָתוֹ מִבֵּית הַמִּדְרָשׁ לִסְחוֹרָה, וְהַטַּעַם כְּדֵי שֶׁיִּתְקַיֵּם יִשָּׂשכָר בְּאָהֳלוֹ כְּאָמְרוֹ ״וְיִשָּׂשכָר בְּאֹהָלֶיךָ״.","complete":true},{"workId":"Haamek_Davar_on_Deuteronomy","unitId":"Haamek_Davar_on_Deuteronomy.33.59","commentator":"העמק דבר","sourceLine":"העמק דבר · ספר תורת אלוהים, וילנא 1879 · נחלת הכלל · ספריא","chapter":33,"verse":22,"dh":"ולדן אמר דן גור אריה.","text":"הנה גבורת ארי אינו ניכר במקום מרעה צאן כבשים ואילים שאין להם עוז להלחם. אלא ביער אם הוא מוצא שור פראי מנגח בקרניו וכחו רב מאד. בזה נצרך לגבורת ארי. אבל גור אריה שאינו חזק כ״כ לא יתחר עם שור אלא נכנס במקום מרעה צאן וכך המשיל את גבורת דן שהוא כגור אריה אשר יזנק מן הבשן ששם מרעה אילים כמבואר בשירת האזינו. ומשמעות יזנק כ׳ הרמב״ם בפירוש המשניות חולין פ״ב קול הנשמע מנשימת בני אדם בשעת הנשימה. וענין זה הלשון לכאן דגור אריה בא בקול דק ועמוק כקול הזינוק ובזה מפחיד לב האילים ונופלים לפניו. וברכה זו הגיעה לשמשון שהראה כח גבורתו בהמון פלשתים ולא עם גבורי מלחמה ולא כיהודה שנלחם עם גבורים ואדירים ויכול להם.","complete":false},{"workId":"Sforno_on_Deuteronomy","unitId":"Sforno_on_Deuteronomy.33.57","commentator":"ספורנו","sourceLine":"ספורנו · ובלכתך בדרך · נחלת הכלל · ספריא","chapter":33,"verse":28,"dh":null,"text":"בדד עין יעקב אל ארץ דגן ותירוש אף שמיו יערפו טל. יהי רצון שלקץ הימין עין יעקב והוא האדון אשר אתם מבקשים אשר הוא עין ישראל בסוף ובעקב הכל וכן שמיו יערפו טל יביעו טל בשפע אל ארץ דגן ותירוש כי אמנם המשיח יערוף לקחי כטל שהכל שמחים בו וג\"כ השמים יביעו טל בשפע אל ארץ דגן ותירוש. כמו שהיה הענין בששת ימי בראשית קודם חטא של אדם הראשון כי לא המטיר ואדם אין לעבוד ואיד יעלה והשקה באופן שבהיות הארץ מעצמה ארץ דגן ותירוש בבא עליה עריפת טל לברכה מספיק להתפרנס את יושביה שלא בצער כאשר היתה הכוונה שיתפרנס אדם הראשון קודם חטאו כאמרם ז\"ל (פרק בתרא דכתובות) עתידה ארץ ישראל שתוציא גלוסקאות וכלי מילת:","complete":true}]});
